window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch03"]={"id":"ch03","title":"第三章(一) 内膜系统","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"内质网 · 蛋白质分选 · 高尔基体 · 溶酶体","modules":[{"i":0,"name":"模块一：真核细胞分室化与内质网","slides":[{"i":0,"sec":"第一节 分室化","title":"第三章 内膜系统与蛋白质分选 (p1)","notes":"第三章 内膜系统与蛋白质分选、膜泡运输。一、真核细胞内的膜被细胞器及其功能:分室化；二、蛋白质的分选(protein sorting)及定向转运——膜泡运输、跨膜运输、核孔运输。","page":1,"level":"掌握","img":"assets/img/ch03/p001.jpg","anim":null,"fig":null,"points":null,"check":{"q":"根据本章内容，蛋白质的定向转运方式不包括下列哪一项？","o":["A. 膜泡运输","B. 跨膜运输","C. 核孔运输","D. 自由扩散运输"],"a":"D","e":"本章指出蛋白质分选与定向转运包括膜泡运输、跨膜运输和核孔运输三种方式，不包括自由扩散。","oe":["膜泡运输是蛋白质定向转运的方式之一。","跨膜运输是蛋白质定向转运的方式之一。","核孔运输是蛋白质进入细胞核的定向转运方式之一。","自由扩散用于小分子，不属于蛋白质定向转运方式，故为答案。"]},"cards":[{"front":"内膜系统与蛋白质分选的核心内容有哪些？","back":"膜被细胞器与分室化；蛋白质分选及定向转运：膜泡运输、跨膜运输、核孔运输","mnemonic":"分室—分选—三运输","type":"组成数字","useImg":false,"blank":"膜泡运输","blank2":"跨膜运输"}]},{"i":1,"sec":"第一节 分室化","title":"真核细胞分室化 (p2)","notes":"Part I 真核细胞分室化-膜被细胞器。Membranes divide the cytoplasm of eukaryotic cells into distinct compartments——膜把真核细胞质分隔成不同区室，各细胞器功能专一化，是效率的基础。","page":2,"level":"掌握","img":"assets/img/ch03/p002.jpg","anim":"compartmentalization","fig":null,"points":["内膜系统＝细胞质中由单层膜包被、结构与功能上相互关联的细胞器群。","包括：内质网、高尔基体、溶酶体、胞内体、分泌泡、植物液泡等。","线粒体、叶绿体、过氧化物酶体虽有膜，但不属内膜系统。"],"check":{"q":"真核细胞分室化的核心意义是什么？","o":["A. 使细胞体积增大","B. 膜把细胞质分隔成功能专一的不同区室，提高效率","C. 使细胞器之间完全隔离、互不联系","D. 增加细胞膜的表面积"],"a":"B","e":"膜把真核细胞质分隔成不同区室，各细胞器功能专一化，是效率的基础。","oe":["分室化并非以增大细胞体积为核心意义。","膜将细胞质分隔为功能专一的区室，提高代谢效率，正确。","各区室间通过膜泡、膜接触等相互联系，并非完全隔离。","分室化的意义在于功能区隔，而非单纯增加膜表面积。"]},"cards":[{"front":"真核细胞分室化（膜被细胞器）的意义是什么？","back":"膜把细胞质分隔成不同区室；各细胞器功能专一化，是细胞效率的基础","mnemonic":"膜隔区室，专工出高效","type":"功能","useImg":true,"blank":"细胞质","blank2":"细胞器功能专一化"}]},{"i":2,"sec":"第一节 分室化","title":"内膜系统定义 (p3)","notes":"Endomembrane System内膜系统：在结构、功能乃至发生上相关的、由单层膜围绕成的细胞器或细胞结构。它们的膜是相互流动的、可相互转化的。包括内质网、高尔基体、溶酶体、胞内体、液泡及分泌小泡等(不含线粒体、叶绿体、过氧化物酶体)。","page":3,"level":"掌握","img":"assets/img/ch03/p003.jpg","anim":null,"fig":"这张图给出内膜系统的“膜流”方向：核膜与内质网相通 → 内质网出芽形成运输小泡 → 高尔基体顺面(CGN) → 中间膜囊 → 反面(TGN) → 分选到溶酶体、分泌泡或质膜。读图抓住“一条主干、多个岔路”：主干是 ER→Golgi→TGN，岔路在 TGN 决定货物去溶酶体还是分泌到胞外。","points":null,"check":null,"cards":[{"front":"内膜系统的定义是什么？","back":"在结构、功能及发生上相关、由单层膜围绕的细胞器或结构；膜相互流动、可相互转化","mnemonic":"单层膜、相关联、可流动","type":"定义","useImg":false,"blank":"单层膜","blank2":"膜相互流动"},{"front":"内膜系统包括哪些细胞器？不包括哪些？","back":"包括内质网、高尔基体、溶酶体、胞内体、液泡及分泌小泡；不包括线粒体、叶绿体、过氧化物酶体","mnemonic":"内高溶体液泡泡，线叶过不算","type":"组成数字","useImg":false,"blank":"内质网","blank2":"高尔基体"}]},{"i":3,"sec":"第一节 分室化","title":"内吞途径 (p4)","notes":"Endocytic pathway from the plasma membrane to lysosomes：质膜→早期胞内体(内体,endosome)→晚期胞内体→溶酶体。是细胞摄取胞外物质的降解途径。\n\n【本页英文讲解】\n本页讲内吞途径（endocytic pathway）从质膜到溶酶体的运输路线。细胞经内吞摄取胞外物质后，依次经质膜→早期胞内体（early endosome）→晚期胞内体（late endosome）→溶酶体（lysosome），最终被降解。这是与分泌途径方向相反的膜泡运输通路。考点：各站点顺序及内体分选功能，见翟中和教材第七章、第八章。","page":4,"level":"掌握","img":"assets/img/ch03/p004.jpg","anim":null,"fig":"早期内体接收来自质膜的胞吞小泡，腔内 pH 逐渐降低；随质子泵持续泵入 H⁺，早期内体成熟为晚期内体，最终与溶酶体融合。图的关键是“成熟＝pH 下降＋货物分选”。","points":null,"check":{"q":"内吞途径中，从质膜到溶酶体的正确顺序是？","o":["A. 质膜→晚期胞内体→早期胞内体→溶酶体","B. 质膜→早期胞内体→晚期胞内体→溶酶体","C. 质膜→溶酶体→早期胞内体→晚期胞内体","D. 质膜→高尔基体→早期胞内体→溶酶体"],"a":"B","e":"内吞途径为质膜→早期胞内体→晚期胞内体→溶酶体，是摄取胞外物质的降解途径。","oe":["内吞顺序应为早期胞内体在前、晚期胞内体在后，该选项颠倒。","内吞途径为质膜→早期胞内体→晚期胞内体→溶酶体，正确。","溶酶体是内吞途径的终点，不可能先于胞内体。","内吞途径经胞内体到溶酶体，不经过高尔基体。"]},"cards":[{"front":"内吞途径的路径是什么？","back":"质膜→早期胞内体→晚期胞内体→溶酶体；是摄取胞外物质的降解途径","mnemonic":"质早晚溶，由外到内降解","type":"流程","useImg":true,"blank":"溶酶体","blank2":"胞内体"}]},{"i":4,"sec":"第一节 分室化","title":"其他膜性细胞器 (p5)","notes":"区别：Several other membranous organelles of the cytoplasm——线粒体、叶绿体、过氧化物酶体虽具膜，但不由内膜系统衍生，不属于内膜系统。其膜蛋白由自身基因组或特殊途径导入。","page":5,"level":"理解","img":"assets/img/ch03/p005.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列哪种细胞器虽具膜，但不属于内膜系统？","o":["A. 内质网","B. 高尔基体","C. 线粒体","D. 溶酶体"],"a":"C","e":"线粒体、叶绿体、过氧化物酶体虽具膜，但不由内膜系统衍生，不属于内膜系统。","oe":["内质网由内膜系统衍生，属于内膜系统。","高尔基体由内膜系统衍生，属于内膜系统。","线粒体虽具膜，但不由内膜系统衍生，不属于内膜系统，正确。","溶酶体由内膜系统衍生，属于内膜系统。"]},"cards":null},{"i":5,"sec":"第一节 分室化","title":"细胞膜系统的研究方法 (p6)","notes":"A few approaches to the study of cytomembranes：①放射自显影与电镜技术；②GFP标记活细胞观察蛋白运动；③差速离心与密度梯度离心分离细胞器；④亚细胞组分分离。","page":6,"level":"掌握","img":"assets/img/ch03/p006.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列哪项不属于研究细胞膜系统的方法？","o":["A. 放射自显影与电镜技术","B. GFP标记活细胞观察蛋白运动","C. 差速离心与密度梯度离心分离细胞器","D. X射线晶体衍射测定膜脂分子结构"],"a":"D","e":"本页列出的研究方法包括放射自显影与电镜、GFP标记、差速离心与密度梯度离心及亚细胞组分分离。","oe":["放射自显影与电镜技术是研究膜系统的经典方法。","GFP标记活细胞可用于观察膜蛋白的运动与定位。","差速离心与密度梯度离心可分离细胞器以研究膜系统。","X射线晶体衍射主要用于测定蛋白等结构，不属本页所列研究膜系统的方法，故为答案。"]},"cards":[{"front":"研究细胞膜系统的主要方法有哪些？","back":"放射自显影与电镜；GFP标记活细胞观察蛋白运动；差速离心与密度梯度离心；亚细胞组分分离","mnemonic":"自显、荧光、离心、分离","type":"流程","useImg":false,"blank":"差速离心","blank2":"密度梯度离心"}]},{"i":6,"sec":"第一节 分室化","title":"放射自显影与电镜 (p7)","notes":"放射自显影与电镜技术：用放射性标记氨基酸脉冲标记胰腺腺泡细胞，追踪分泌蛋白在ER→Golgi→分泌小泡→细胞外的运输路径。这是研究膜泡运输的经典实验。","page":7,"level":"掌握","img":"assets/img/ch03/p007.jpg","anim":"pulse_chase","fig":null,"points":["Palade 用放射性氨基酸脉冲标记胰腺腺泡细胞，追踪分泌蛋白路径。","3 min 放射性在粗面内质网 → 20 min 到高尔基体 → 120 min 到分泌泡(分泌颗粒)。","结论：分泌蛋白沿 rER→Golgi→分泌泡→胞外 单向运输。"],"check":{"q":"放射自显影追踪分泌蛋白的经典实验中，分泌蛋白的运输路径是？","o":["A. 细胞核→ER→Golgi→细胞外","B. ER→Golgi→分泌小泡→细胞外","C. Golgi→ER→分泌小泡→细胞外","D. ER→溶酶体→分泌小泡→细胞外"],"a":"B","e":"用放射性标记氨基酸脉冲标记胰腺腺泡细胞，追踪到分泌蛋白经ER→Golgi→分泌小泡→细胞外的运输路径。","oe":["分泌蛋白不经过细胞核，该路径错误。","分泌蛋白经ER→Golgi→分泌小泡→细胞外运输，正确。","分泌蛋白是由ER经高尔基体向外运输，方向不能反。","分泌蛋白不经溶酶体途径分泌到细胞外。"]},"cards":[{"front":"放射自显影与电镜实验证明了什么？","back":"用放射性氨基酸脉冲标记胰腺腺泡细胞，追踪分泌蛋白路径：ER→Golgi→分泌小泡→细胞外","mnemonic":"脉冲标记追分泌，ER高泡出细胞","type":"例证","useImg":true,"blank":"分泌蛋白","blank2":"分泌小泡"}]},{"i":7,"sec":"第一节 分室化","title":"GFP标记活细胞 (p8)","notes":"The use of GFP reveals the movement of proteins within a living cell——绿色荧光蛋白(GFP)标记使人们能在活细胞中实时观察蛋白质的运动和定位。\n\n【本页英文讲解】\n本页讲绿色荧光蛋白（GFP，green fluorescent protein）在活细胞成像中的应用。用GFP标记目标蛋白后，可借荧光显微镜在活细胞中实时观察蛋白质的运动与定位。GFP源自水母，成熟发光无需底物和辅因子，是细胞生物学常用报告分子。此为研究方法考点，常用于研究蛋白质分选与膜泡运输（第八章）。","page":8,"level":"理解","img":"assets/img/ch03/p008.jpg","anim":null,"fig":"把 GFP(绿色荧光蛋白)与目标蛋白融合表达，用荧光显微镜实时观察蛋白在活细胞内的运动。图中荧光从 ER 经高尔基体向细胞表面移动，说明膜蛋白/分泌蛋白是经内膜系统逐步运输的。GFP 是“活细胞蛋白定位”的通用标签。","points":null,"check":{"q":"GFP标记技术的主要优势是什么？","o":["A. 可在活细胞中实时观察蛋白质的运动和定位","B. 可提高蛋白质的表达量","C. 可固定细胞后观察蛋白质结构","D. 可分离纯化目标蛋白质"],"a":"A","e":"绿色荧光蛋白(GFP)标记使人们能在活细胞中实时观察蛋白质的运动和定位。","oe":["GFP标记可在活细胞中实时观察蛋白质的运动和定位，正确。","GFP标记用于示踪定位，并不提高蛋白质的表达量。","GFP的优势是活细胞实时观察，而非固定后观察结构。","GFP标记用于观察定位，不能分离纯化目标蛋白质。"]},"cards":null},{"i":8,"sec":"第一节 分室化","title":"差速离心分离 (p9-10)","notes":"差速离心分离细胞器：20,000g 20min→核、线粒体、未破碎细胞；50,000g 2hrs→微粒体(microsome)。In general, the smaller the size, the higher the speed needed。微粒体是破碎ER自我融合形成的囊泡。","page":9,"level":"掌握","img":"assets/img/ch03/p009.jpg","anim":"differential_centrifugation","fig":null,"points":["亚细胞分级分离的基础是差速离心。","先低速(约 20,000g)沉淀核、线粒体、过氧化物酶体、未破碎细胞；","再高速(约 50,000g)沉淀微粒体(ER/Golgi 碎片)，上清为胞质溶胶。"],"check":{"q":"差速离心分离细胞器时，50,000g离心2小时得到的沉淀主要是？","o":["A. 细胞核","B. 线粒体","C. 微粒体","D. 未破碎细胞"],"a":"C","e":"50,000g离心2小时得到微粒体，它是破碎ER自我融合形成的囊泡；20,000g 20min沉淀核、线粒体和未破碎细胞。","oe":["细胞核在较低转速即沉淀，不由50,000g离心2小时得到。","线粒体在约20,000g离心20分钟时即沉淀。","50,000g离心2小时沉淀的主要是微粒体，正确。","未破碎细胞在较低转速与核、线粒体一同沉淀。"]},"cards":[{"front":"差速离心分离细胞器的条件与结果是什么？","back":"20,000g 20min→核、线粒体、未破碎细胞；50,000g 2hrs→微粒体；越小需转速越高","mnemonic":"越大越先沉，越小转速高","type":"流程","useImg":false,"blank":"微粒体","blank2":"线粒体"},{"front":"微粒体是什么？","back":"破碎内质网自我融合形成的囊泡","mnemonic":"碎ER自融合成微粒体","type":"定义","useImg":false,"blank":"囊泡","blank2":"内质网"}]},{"i":9,"sec":"第二节 内质网","title":"内质网(ER)概述 (p11)","notes":"3.1 内质网(endoplasmic reticulum, ER)：粗面内质网(rER)——膜表面分布大量核糖体，多扁囊状排列较整齐，合成分泌蛋白；光面内质网(sER)——表面无核糖体。ER是真核细胞普遍且形态多变的细胞器。","page":11,"level":"掌握","img":"assets/img/ch03/p011.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"粗面内质网与光面内质网的区别是什么？","back":"rER：膜表面有大量核糖体，多扁囊状排列整齐，合成分泌蛋白；sER：表面无核糖体","mnemonic":"粗有核糖合分泌，光无核糖管脂质","type":"对比","useImg":true,"blank":"核糖体","blank2":"分泌蛋白"}]},{"i":10,"sec":"第二节 内质网","title":"电镜下的粗面内质网 (p12)","notes":"透射电镜下的胰腺腺泡细胞中的粗面内质网、扫描电镜下的粗面内质网：显示rER的扁囊状结构和表面核糖体颗粒。","page":12,"level":"理解","img":"assets/img/ch03/p012.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":11,"sec":"第二节 内质网","title":"微粒体与特殊内质网 (p13)","notes":"两种特殊类型的内质网。微粒体(microsomes)：体外实验中细胞匀浆和差速离心得到的、由分离的内质网自我融合形成的近似球形囊泡结构。是研究ER功能的体外模型。","page":13,"level":"掌握","img":"assets/img/ch03/p013.jpg","anim":null,"fig":"微粒体是匀浆时内质网膜破碎后重新封闭成的囊泡，保留了 ER 的酶系。肌质网(SR)是特化的 sER，含 Ca²⁺-ATPase 储存 Ca²⁺。sER 与 rER 功能不同：sER 无核糖体，管脂质合成、解毒、储钙。","points":null,"check":{"q":"关于微粒体（microsomes）的叙述，正确的是：","o":["A. 是细胞内天然存在的球形细胞器","B. 是体外细胞匀浆和差速离心后由分离的内质网自我融合形成的近似球形囊泡","C. 是高尔基体断裂后形成的小泡","D. 只能在完整细胞中观察到，无法用于体外研究"],"a":"B","e":"微粒体是体外实验中由分离的内质网自我融合形成的囊泡，是研究ER功能的体外模型。","oe":["微粒体并非细胞内天然存在的细胞器，而是在体外形成。","微粒体是匀浆差速离心后由分离内质网自我融合成的囊泡，正确。","微粒体来源于内质网而非高尔基体断裂。","微粒体正是体外研究ER功能的模型，可在体外观察。"]},"cards":[{"front":"微粒体(microsomes)是什么？如何获得？","back":"体外细胞匀浆、差速离心后由内质网自我融合形成的球形囊泡；是研究ER功能的体外模型","mnemonic":"匀浆离心，ER自融成球","type":"定义","useImg":false,"blank":"球形囊泡","blank2":"差速离心"}]},{"i":12,"sec":"第二节 内质网","title":"ER的结构 (p14)","notes":"内质网是真核细胞中普遍且形态多变的细胞器之一，由封闭的管状或扁平囊状膜系统及其包被的腔(ER腔/lumen)构成。rER与sER在形态和功能上不同，但膜是连续的。","page":14,"level":"掌握","img":"assets/img/ch03/p014.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"内质网的基本结构由什么构成？","back":"封闭的管状或扁平囊状膜系统及其包被的ER腔(lumen)；rER与sER形态功能不同但膜连续","mnemonic":"管囊成网，腔在其中","type":"组成","useImg":true,"blank":"ER腔","blank2":"rER"}]},{"i":13,"sec":"第二节 内质网","title":"sER功能-解毒与储钙 (p15)","notes":"(1) sER功能：①Detoxification解毒；②Sequestering calcium储钙——参与信号传递，肌细胞肌质网储钙。sER还合成脂类。\n\n【本页英文讲解】\n本页讲滑面内质网（sER，smooth endoplasmic reticulum）的功能：①解毒（detoxification）；②储存钙（sequestering calcium），储存Ca²⁺并参与信号传递，肌细胞中特化为肌质网储存钙以调节收缩。此外sER还合成脂类。考点：sER与粗面内质网（rER）的功能分工，见教材第七章内质网（ER）。","page":15,"level":"掌握","img":"assets/img/ch03/p015.jpg","anim":null,"fig":null,"points":["光面内质网(sER)三大功能：合成脂质、解毒、储存 Ca²⁺。","肝细胞 sER 含细胞色素 P450，氧化分解药物/毒物。","肌细胞 sER(肌质网)储存 Ca²⁺，控制肌肉收缩。"],"check":null,"cards":[{"front":"sER的三大功能是什么？","back":"①解毒；②储钙(参与信号传递)；③合成脂类","mnemonic":"解、钙、脂","type":"功能","useImg":false,"blank":"解毒","blank2":"储钙"}]},{"i":14,"sec":"第二节 内质网","title":"sER解毒作用 (p16)","notes":"解毒作用——肝细胞：肝细胞sER很丰富，含一些酶用以清除脂溶性药物和代谢产生的有害物质。多数解毒反应与氧化作用有关，核心成员是细胞色素P450。","page":16,"level":"掌握","img":"assets/img/ch03/p016.jpg","anim":null,"fig":"P450 催化的羟化反应：把脂溶性药物/毒物加上羟基使其水溶性增加，便于排出。解毒反应依赖 sER 膜上的 P450 和 NADPH。长期服用某些药物会诱导 sER 增生(P450 增多)。","points":null,"check":{"q":"肝细胞滑面内质网（sER）解毒作用的核心酶成员是：","o":["A. Ca2+-ATPase","B. 细胞色素P450","C. 磷脂酰胆碱合成酶","D. 易位子"],"a":"B","e":"sER解毒反应多与氧化作用有关，核心成员是细胞色素P450。","oe":["Ca2+-ATPase负责将钙泵入ER，与解毒无关。","sER解毒多为氧化反应，核心酶是细胞色素P450，正确。","磷脂酰胆碱合成酶参与膜脂合成，不承担解毒功能。","易位子参与蛋白质穿膜转运，与sER解毒无关。"]},"cards":[{"front":"肝细胞sER解毒的核心酶是什么？","back":"细胞色素P450；多数解毒反应与氧化作用有关，清除脂溶性药物和有害物质","mnemonic":"P450，肝里解毒王","type":"例证","useImg":false,"blank":"细胞色素P450","blank2":"氧化作用"}]},{"i":15,"sec":"第二节 内质网","title":"sER储钙 (p17)","notes":"储钙(Ca库)：ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER中储存，使内质网腔钙离子浓度高达3mM。sER通过释放/回收Ca2+调节细胞信号(如肌肉收缩)。","page":17,"level":"掌握","img":"assets/img/ch03/p017.jpg","anim":null,"fig":"肌质网膜上的 Ca²⁺-ATPase 把胞质 Ca²⁺ 泵入 SR 腔储存；神经冲动到达时，Ca²⁺ 通道开放，Ca²⁺ 涌入胞质触发肌丝收缩。图强调“储钙—释放”的开关作用。","points":null,"check":{"q":"内质网作为细胞内Ca2+库，将细胞基质中的钙泵入ER腔所依赖的膜蛋白是：","o":["A. 细胞色素P450","B. 易位子","C. Ca2+-ATPase","D. 脂酰辅酶A合成酶"],"a":"C","e":"ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER中储存，使ER腔钙离子浓度高达3mM。","oe":["细胞色素P450参与解毒，不负责把钙泵入ER。","易位子转运新生肽链，不承担钙的泵入。","ER膜上的Ca2+-ATPase将基质钙泵入ER腔储存，正确。","脂酰辅酶A合成酶参与脂代谢，不负责钙泵入。"]},"cards":[{"front":"ER如何储钙？腔内钙浓度多高？","back":"ER膜上Ca2+-ATPase将基质Ca2+泵入ER储存；腔钙浓度高达3mM，通过释放/回收Ca2+调节信号","mnemonic":"钙泵入腔，三毫摩尔","type":"流程","useImg":true,"blank":"Ca2+-ATPase","blank2":"ER膜"}]},{"i":16,"sec":"第二节 内质网","title":"sER合成膜脂 (p18)","notes":"sER合成构成细胞所需的绝大多数膜脂(甘油磷脂和胆固醇)。磷脂酰胆碱(卵磷脂)的合成：脂酰辅酶A在sER膜上经酶催化合成，膜脂在ER合成后运往其他膜。","page":18,"level":"掌握","img":"assets/img/ch03/p018.jpg","anim":"lipid_synthesis","fig":"膜脂(甘油磷脂、胆固醇)主要在 sER 的胞质面合成。新合成的脂质插入 ER 膜，随后通过囊泡运输或磷脂交换蛋白分配到其他膜。图显示合成部位在 ER 膜上。","points":null,"check":{"q":"关于sER合成膜脂的叙述，正确的是：","o":["A. sER只合成胆固醇，不合成甘油磷脂","B. sER合成构成细胞所需的绝大多数膜脂，包括甘油磷脂和胆固醇","C. 膜脂主要在线粒体合成后运往ER","D. 磷脂酰胆碱的合成发生在细胞质基质中"],"a":"B","e":"sER合成构成细胞所需的绝大多数膜脂（甘油磷脂和胆固醇），磷脂酰胆碱在sER膜上经酶催化合成。","oe":["sER既合成甘油磷脂也合成胆固醇，该选项说法片面。","sER合成细胞所需的绝大多数膜脂，包括甘油磷脂和胆固醇，正确。","膜脂主要在sER合成后运往其他膜，而非在线粒体合成。","磷脂酰胆碱在sER膜上经酶催化合成，不在细胞质基质。"]},"cards":[{"front":"sER合成哪些膜脂？以什么为例？","back":"绝大多数膜脂(甘油磷脂和胆固醇)；如磷脂酰胆碱(卵磷脂)在sER膜上由脂酰辅酶A经酶催化合成","mnemonic":"膜脂工厂在sER","type":"功能","useImg":false,"blank":"磷脂酰胆碱","blank2":"甘油磷脂"}]},{"i":17,"sec":"第二节 内质网","title":"膜脂在ER合成后运输 (p19)","notes":"Most membrane lipids are synthesized entirely within the ER——膜脂在ER合成后，通过运输方式(转运蛋白、膜泡运输、膜接触)运往线粒体、高尔基体、质膜等。","page":19,"level":"理解","img":"assets/img/ch03/p019.jpg","anim":null,"fig":"ER 合成的脂质有三种去向：①经囊泡运输随膜流到 Golgi 及以后；②由磷脂交换蛋白(PITP)在膜之间搬运；③在 ER 与线粒体等接触点直接转移。图说明“脂质不能自由穿水相”，需载体或囊泡。","points":null,"check":{"q":"膜脂在ER合成后运往线粒体、高尔基体、质膜等的方式不包括：","o":["A. 转运蛋白介导的运输","B. 膜泡运输","C. 膜接触位点运输","D. 由核糖体直接合成后扩散"],"a":"D","e":"膜脂在ER合成后通过转运蛋白、膜泡运输、膜接触等方式运往其他膜，而不是由核糖体直接合成。","oe":["转运蛋白介导的运输是膜脂从ER运出的方式之一。","膜泡运输是膜脂从ER运往其他膜的方式之一。","膜接触位点运输是膜脂转运的方式之一。","膜脂不在核糖体合成，核糖体只合成蛋白质，故为答案。"]},"cards":null},{"i":18,"sec":"第二节 内质网","title":"rER功能-蛋白质合成 (p20)","notes":"(2) rER的功能：①蛋白质合成——rER膜上有称作translocon(易位子)的蛋白复合体'通道'，蛋白多肽链边延伸边穿过rER膜入内质网腔，继续折叠修饰。","page":20,"level":"掌握","img":"assets/img/ch03/p020.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"rER合成蛋白质的关键通道是什么？","back":"易位子(translocon)蛋白复合体；多肽链边延伸边穿过rER膜进入ER腔，继续折叠修饰","mnemonic":"边翻译边进腔","type":"流程","useImg":true,"blank":"易位子","blank2":"ER腔"}]},{"i":19,"sec":"第二节 内质网","title":"易位子(translocon) (p21)","notes":"内质网易位子(translocon/translocator)：rER膜上的一种蛋白复合体，中心有一个直径2nm的'孔道'，与新合成的多肽进入ER腔有关。","page":21,"level":"掌握","img":"assets/img/ch03/p021.jpg","anim":"sec61_translocon","fig":null,"points":null,"check":null,"cards":[{"front":"易位子(translocon)的结构与功能？","back":"rER膜上的蛋白复合体，中心有直径2nm的孔道；与新合成多肽进入ER腔有关","mnemonic":"2纳米小孔，多肽进门","type":"组成数字","useImg":true,"blank":"蛋白复合体","blank2":"孔道"}]},{"i":20,"sec":"第二节 内质网","title":"易位子结构 (p22)","notes":"Cross-sectional view of the translocon channel：易位子通道的侧面结构，中心孔道允许新生肽链穿膜进入ER腔。\n\n【本页英文讲解】\n本页讲易位子（translocon）通道的结构。图中为易位子通道的侧面/横截面观，其中央孔道允许新生肽链（nascent polypeptide）穿膜进入内质网腔（ER lumen）。易位子是蛋白质共翻译转运的通道，由Sec61复合体构成。考点：新生肽链经易位子进入ER腔的机制，见翟中和教材第八章蛋白质分选与膜泡运输。","page":22,"level":"理解","img":"assets/img/ch03/p022.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于易位子（translocon）通道结构的叙述，正确的是：","o":["A. 其中心孔道允许新生肽链穿膜进入ER腔","B. 它是位于线粒体外膜的通道","C. 它只允许已完成折叠的蛋白质通过","D. 它负责将钙离子泵入内质网"],"a":"A","e":"易位子通道的侧面结构显示，中心孔道允许新生肽链穿膜进入ER腔。","oe":["易位子中心孔道允许新生肽链穿膜进入ER腔，正确。","易位子位于内质网膜而非线粒体外膜。","易位子转运的是未折叠的新生肽链，不是已折叠蛋白。","把钙泵入内质网的是Ca2+-ATPase，不是易位子。"]},"cards":null},{"i":21,"sec":"第二节 内质网","title":"Sec61复合体 (p23)","notes":"Sec61 complex(Sec61α、Sec61β、Sec61γ)高度保守，从细菌到人都有，构成蛋白质转运通道的核心。\n\n【本页英文讲解】\n本页讲Sec61复合体（Sec61 complex）的组成与保守性。它由Sec61α、Sec61β、Sec61γ三个亚基组成，从细菌到人均高度保守，构成蛋白质转运通道的核心，细菌中对应SecY复合体。Sec61是内质网易位子的核心成分，负责新生肽链穿膜转运。考点：转运通道的进化保守性，见教材第八章共翻译转运。","page":23,"level":"理解","img":"assets/img/ch03/p023.jpg","anim":null,"fig":"易位子是 rER 膜上的蛋白质通道，核心为 Sec61 复合体(α/β/γ 亚基)，中央通道直径约 2 nm。新生肽链被 SRP 送到膜上后经 Sec61 进入 ER 腔；分泌蛋白完全穿入，跨膜蛋白则侧向进入脂双层。图中还可见信号肽酶在腔内切除信号肽。","points":null,"check":null,"cards":null},{"i":22,"sec":"第二节 内质网","title":"游离核糖体与膜结合核糖体 (p24-25)","notes":"细胞内几乎所有蛋白质合成都从胞质溶胶的游离多聚核糖体开始。一部分随肽链延伸(信号肽引导)转移到rER膜上继续翻译——共翻译转移(translocation and translation)。","page":24,"level":"掌握","img":"assets/img/ch03/p024.jpg","anim":null,"fig":"两类核糖体结构相同，只是所合成蛋白不同。合成分泌蛋白/膜蛋白时，信号肽把核糖体带到 rER 膜上(膜结合核糖体)；合成胞质蛋白/核蛋白时核糖体游离在胞质。“游离”与“膜结合”是可逆的，取决于正在翻译的肽链有无信号肽。","points":null,"check":{"q":"关于真核细胞蛋白质合成起始与共翻译转移的叙述，正确的是：","o":["A. 所有蛋白质都在rER膜上的核糖体开始合成","B. 几乎所有蛋白质合成都从胞质溶胶的游离多聚核糖体开始，部分随信号肽引导转移到rER膜上继续翻译","C. 游离核糖体合成的蛋白质都不含信号肽","D. 共翻译转移发生在蛋白质合成完成之后"],"a":"B","e":"细胞内几乎所有蛋白质合成都从胞质溶胶的游离多聚核糖体开始，一部分随肽链延伸由信号肽引导转移到rER膜上继续翻译，即共翻译转移。","oe":["并非所有蛋白质都在rER膜上的核糖体开始合成。","蛋白质多从胞质游离多聚核糖体起始，部分经信号肽转到rER继续翻译，正确。","游离核糖体合成的蛋白质有些也含信号肽，该说法错误。","共翻译转移是边翻译边转移，并非合成完成后发生。"]},"cards":[{"front":"细胞内蛋白质合成最初在哪里开始？","back":"几乎所有蛋白质合成均起始于胞质溶胶的游离多聚核糖体","mnemonic":"一切从游离核糖体起步","type":"定位","useImg":false,"blank":"游离多聚核糖体","blank2":"胞质溶胶"},{"front":"什么是共翻译转移？","back":"肽链延伸中由信号肽引导，核糖体附着到rER膜上边翻译边转移入ER","mnemonic":"边合成边进门","type":"流程","useImg":true,"blank":"信号肽","blank2":"rER膜"}]},{"i":23,"sec":"第二节 内质网","title":"游离与膜结合核糖体 (p26)","notes":"真核细胞质中的核糖体：①游离态；②结合于内质网(粗面内质网)。两者结构相同，区别在于是否附着在ER膜上，取决于所合成蛋白是否含ER信号肽。","page":26,"level":"掌握","img":"assets/img/ch03/p026.jpg","anim":null,"fig":null,"points":null,"check":{"q":"真核细胞质中游离核糖体与结合于粗面内质网的核糖体，其主要区别是：","o":["A. 两者结构完全不同","B. 两者结构相同，区别在于是否附着在ER膜上，取决于所合成蛋白是否含ER信号肽","C. 游离核糖体不能合成蛋白质","D. 膜结合核糖体只合成膜脂"],"a":"B","e":"游离核糖体与膜结合核糖体结构相同，区别在于是否附着在ER膜上，取决于所合成蛋白是否含ER信号肽。","oe":["游离核糖体与膜结合核糖体结构相同，并非结构完全不同。","两者结构相同，区别在是否附着ER膜，取决于所合成蛋白有无ER信号肽，正确。","游离核糖体可合成细胞内众多蛋白质，并非不能合成。","膜结合核糖体合成的是分泌蛋白和膜蛋白，不是膜脂。"]},"cards":[{"front":"真核细胞质中核糖体有哪两种存在状态？","back":"游离态；结合于粗面内质网（rER）膜上","mnemonic":"游离或贴膜","type":"组成数字","useImg":true,"blank":"游离态","blank2":"粗面内质网"},{"front":"游离核糖体与膜结合核糖体结构是否相同？区别何在？","back":"结构相同；区别在于是否附着ER膜，取决于所合成蛋白是否含ER信号肽","mnemonic":"同机器，不同岗位","type":"对比","useImg":false,"blank":"ER信号肽","blank2":"ER膜"}]},{"i":24,"sec":"第二节 蛋白质分选","title":"蛋白质定向转运与分选 (p27)","notes":"蛋白质的定向转运(protein targeting)/蛋白分选(protein sorting)：生物体根据蛋白质自身的信号序列，将蛋白质运送到细胞的特定部位。信号序列是分选的'邮政编码'。","page":27,"level":"掌握","img":"assets/img/ch03/p027.jpg","anim":"protein_sorting_overview","fig":"核编码蛋白在胞质核糖体合成后有三条去向：①共翻译转运进入 ER(信号肽)，再经内膜系统；②翻译后转运进入线粒体、叶绿体、过氧化物酶体(导肽/转运肽)；③核孔运输进入细胞核(NLS)。图的核心是“信号序列决定目的地”。","points":["信号肽→内膜系统(ER)；导肽/转运肽→线粒体/叶绿体/过氧化物酶体；NLS→细胞核。","信号序列决定蛋白质的合成部位和运输方向。"],"check":{"q":"根据第27页内容，蛋白质定向转运（蛋白分选）主要依据什么将蛋白质运送到细胞特定部位？","o":["A. 蛋白质自身的信号序列","B. 蛋白质的分子量大小","C. 蛋白质的等电点","D. 蛋白质的合成速度"],"a":"A","e":"蛋白质分选依据其自身的信号序列，信号序列相当于分选的‘邮政编码’。","oe":["蛋白质分选依据自身信号序列，如同邮政编码，正确。","分子量大小不是决定蛋白质定向转运的依据。","等电点影响电泳行为，不是蛋白质分选的依据。","合成速度与蛋白质被运往的部位无关。"]},"cards":[{"front":"什么是蛋白质定向转运（分选）？","back":"生物体根据蛋白质自身信号序列，将其运送到细胞特定部位的过程","mnemonic":"信号序列=邮政编码","type":"定义","useImg":false,"blank":"信号序列","blank2":"蛋白质自身信号序列"}]},{"i":25,"sec":"第二节 蛋白质分选","title":"主要蛋白分选途径 (p28)","notes":"Overview of major protein-sorting pathways in eukaryotes：核编码蛋白在胞质游离核糖体合成后，经核孔运输(核)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、膜泡运输(ER→Golgi→溶酶体/质膜/分泌)到达目的地。","page":28,"level":"掌握","img":"assets/img/ch03/p028.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列哪条途径属于第28页所述真核细胞中核编码蛋白的膜泡运输途径？","o":["A. 经核孔运输进入细胞核","B. 跨膜运输进入线粒体","C. ER→Golgi→溶酶体/质膜/分泌","D. 跨膜运输进入过氧化物酶体"],"a":"C","e":"膜泡运输途径为ER→Golgi→溶酶体/质膜/分泌；核孔运输和跨膜运输属于其他途径。","oe":["经核孔进入细胞核属于核孔运输，不是膜泡运输途径。","跨膜运输进入线粒体属于跨膜运输，不是膜泡运输。","膜泡运输途径为ER→Golgi→溶酶体/质膜/分泌，正确。","跨膜运输进入过氧化物酶体不是膜泡运输途径。"]},"cards":[{"front":"真核细胞核编码蛋白的主要分选途径有哪些？","back":"核孔运输（核）；跨膜运输（线粒体/叶绿体/过氧化物酶体）；膜泡运输（ER→Golgi→溶酶体/质膜/分泌）","mnemonic":"核孔、跨膜、膜泡三条路","type":"流程","useImg":true,"blank":"膜泡运输","blank2":"核孔运输"}]},{"i":26,"sec":"第二节 蛋白质分选","title":"分选类型-共转移/后转移 (p29-30)","notes":"蛋白质分选类型：蛋白质首先在细胞质基质中合成；①后转移(post-translational)——合成完成后转运；②共转移(co-translational)——边合成边转运(入ER)。","page":30,"level":"掌握","img":"assets/img/ch03/p030.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于共转移与后转移，下列叙述正确的是？","o":["A. 后转移是边合成边转运","B. 共转移是合成完成后转运","C. 共转移是边合成边转运，如进入ER","D. 两者都发生在细胞核内"],"a":"C","e":"共转移指边合成边转运（如入ER），后转移指合成完成后再转运。","oe":["后转移是蛋白质合成完成后再转运，该选项说反。","共转移是边合成边转运，而非合成完成后转运。","共转移是边合成边转运，如进入ER，正确。","共转移与后转移发生在细胞质及细胞器间，不在细胞核内。"]},"cards":[{"front":"蛋白质分选按转运时机分为哪两类？","back":"后转移：合成完成后转运；共转移：边合成边转运（入ER）","mnemonic":"先做完再走 vs 边走边做","type":"对比","useImg":false,"blank":"共转移","blank2":"后转移"}]},{"i":27,"sec":"第二节 蛋白质分选","title":"信号肽与信号斑 (p32)","notes":"Signal peptides and signal patches：信号肽(线性氨基酸序列)和信号斑(由折叠后空间结构形成的信号)是蛋白质分选的两种信号形式。","page":32,"level":"掌握","img":"assets/img/ch03/p032.jpg","anim":null,"fig":"信号斑(信号 patch)是肽链折叠后在表面形成的三维结构，不是一段连续序列。例如溶酶体酶的三维构象形成信号斑，被 GlcNAc 磷酸转移酶识别加上 M6P。图对比了“线性信号序列”与“构象信号斑”。","points":null,"check":{"q":"第32页指出，蛋白质分选的两种信号形式是？","o":["A. 信号肽和信号斑","B. 启动子和增强子","C. 内含子和外显子","D. 受体和配体"],"a":"A","e":"信号肽是线性氨基酸序列，信号斑由折叠后空间结构形成，二者是两种分选信号形式。","oe":["蛋白质分选的两种信号形式是信号肽和信号斑，正确。","启动子和增强子是基因转录调控元件，不是分选信号。","内含子和外显子是RNA剪接相关序列，与分选无关。","受体和配体是分子识别与结合关系，不是分选信号形式。"]},"cards":[{"front":"蛋白质分选的两种信号形式是什么？","back":"信号肽：线性氨基酸序列；信号斑：折叠后空间结构形成的信号","mnemonic":"一线一斑","type":"对比","useImg":true,"blank":"信号肽","blank2":"信号斑"}]},{"i":28,"sec":"第二节 蛋白质分选","title":"信号序列的发现 (p33)","notes":"for the discovery that 'proteins have intrinsic signals that govern their transport and localization in the cell'——发现蛋白质具有决定其运输和定位的内在信号序列，获诺贝尔奖(Blobel)。\n\n【本页英文讲解】\n本页讲信号肽（signal sequence）的发现。Günter Blobel发现蛋白质具有决定其运输与定位的内在信号（intrinsic signals），据此提出信号假说，并获诺贝尔奖。信号序列如同蛋白质的“邮政编码”，决定其运输去向。此为蛋白质分选的核心概念与诺奖考点，见翟中和教材第八章蛋白质分选与膜泡运输。","page":33,"level":"掌握","img":"assets/img/ch03/p033.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"谁因发现蛋白质内在信号序列而获诺贝尔奖？","back":"Blobel；发现蛋白质具有决定其运输和定位的内在信号序列","mnemonic":"Blobel=信号序列之父","type":"例证","useImg":false,"blank":"Blobel","blank2":"内在信号序列"}]},{"i":29,"sec":"第二节 蛋白质分选","title":"新生蛋白的靶向 (p34-35)","notes":"Newly made proteins are targeted to and imported into various organelles。许多遗传病中，蛋白质因分选信号异常而被错误定位。\n\n【本页英文讲解】\n本页讲新生蛋白的靶向（targeting）。新合成的蛋白质被靶向并导入各种细胞器（Newly made proteins are targeted to and imported into various organelles），这依赖其自身的分选信号。若分选信号异常，蛋白质会被错误定位，引起遗传病。考点：分选信号与疾病的关系，见教材第八章。","page":34,"level":"理解","img":"assets/img/ch03/p034.jpg","anim":null,"fig":null,"points":["信号肽位于 N 端，约 16–26 个氨基酸，中部为疏水核心。","N 端有带正电的极性区，C 端有信号肽酶识别位点。","信号肽在蛋白进入 ER 腔后被信号肽酶切除。"],"check":{"q":"根据第34-35页，许多遗传病中蛋白质被错误定位的原因常是？","o":["A. 蛋白质合成速度过快","B. 蛋白质分选信号异常","C. 细胞核孔数量减少","D. 溶酶体酶活性过高"],"a":"B","e":"蛋白质因分选信号异常而被错误定位，是许多遗传病的重要原因。","oe":["合成速度过快不会导致蛋白质被错误定位。","蛋白质因分选信号异常而被错误定位，是许多遗传病的重要原因，正确。","核孔数量减少主要影响核质运输，不是错误定位的常见原因。","溶酶体酶活性过高与蛋白质错误定位无直接因果。"]},"cards":null},{"i":30,"sec":"第二节 蛋白质分选","title":"信号肽假说的提出 (p36)","notes":"1972年C.Milstein等从细胞中提取的免疫球蛋白分子N端比分泌到细胞外的免疫球蛋白N端多一截(信号肽)。1975年提出信号肽假说：N端信号肽引导蛋白进入ER。","page":36,"level":"掌握","img":"assets/img/ch03/p036.jpg","anim":"cotranslational","fig":null,"points":null,"check":{"q":"1972年Milstein等观察到细胞内免疫球蛋白与分泌到细胞外的免疫球蛋白相比，N端有何特点？","o":["A. 少一截序列","B. 多一截信号肽","C. 完全相同","D. 被糖基化修饰"],"a":"B","e":"细胞内免疫球蛋白N端比分泌到胞外的多一截，即后来所称的信号肽。","oe":["细胞内免疫球蛋白N端比分泌到胞外的多一截，而非少一截。","细胞内免疫球蛋白N端多出一截信号肽，正确。","两者N端并不完全相同，胞内多出信号肽。","该差异是N端多出的信号肽，不是糖基化修饰造成的。"]},"cards":[{"front":"信号肽假说的核心内容是什么？","back":"1975年提出：N端信号肽引导蛋白进入ER；依据是分泌型免疫球蛋白N端多一截序列","mnemonic":"N端多一截，带路进ER","type":"定义","useImg":false,"blank":"信号肽","blank2":"N端信号肽"}]},{"i":31,"sec":"第二节 蛋白质分选","title":"信号序列引导蛋白 (p37)","notes":"Signal sequences direct proteins to the correct organelle——信号序列引导后面的蛋白到达正确细胞器。信号序列通常位于N端，完成使命后被切除。","page":37,"level":"掌握","img":"assets/img/ch03/p037.jpg","anim":null,"fig":"同一前体蛋白可含多种信号序列，按顺序被识别：先导肽引导入线粒体后切除，再暴露下一个信号引导到别处。图强调信号序列的“时序性”和“专一性”。","points":null,"check":{"q":"关于信号序列的特点，下列哪项符合第37页内容？","o":["A. 通常位于C端且不被切除","B. 通常位于N端，完成任务后被切除","C. 位于蛋白质内部且永久保留","D. 只存在于细胞核蛋白中"],"a":"B","e":"信号序列通常位于N端，引导蛋白到达正确细胞器后完成使命被切除。","oe":["信号序列通常位于N端而非C端，且完成任务后被切除。","信号序列通常位于N端，引导到位后完成使命被切除，正确。","信号序列一般不在蛋白质内部永久保留。","信号序列并非只见于核蛋白，多种分泌和膜蛋白都含信号肽。"]},"cards":[{"front":"信号序列的功能是什么？","back":"引导蛋白到达正确细胞器；通常位于N端；完成任务后被切除","mnemonic":"N端车票，到站即撕","type":"功能","useImg":false,"blank":"N端","blank2":"细胞器"}]},{"i":32,"sec":"第二节 蛋白质分选","title":"SRP信号识别颗粒 (p38)","notes":"信号识别颗粒(SRP)：由6种多肽和1个300核苷酸(7S)的RNA组成的核糖核蛋白复合物，通常在细胞质基质中。既与新生肽信号序列结合，又与核糖体大亚基结合，暂停翻译。","page":38,"level":"掌握","img":"assets/img/ch03/p038.jpg","anim":"srp_cycle","fig":null,"points":null,"check":null,"cards":[{"front":"SRP由什么组成？","back":"6种多肽 + 1个300核苷酸(7S)RNA；核糖核蛋白复合物；位于细胞质基质","mnemonic":"六肽一RNA，7S记牢","type":"组成数字","useImg":false,"blank":"核糖核蛋白复合物"},{"front":"SRP结合什么并产生什么效应？","back":"结合新生肽信号序列和核糖体大亚基；暂停翻译","mnemonic":"双结合，踩刹车","type":"功能","useImg":false,"blank":"信号序列","blank2":"核糖体大亚基"}]},{"i":33,"sec":"第二节 蛋白质分选","title":"SRP受体(停泊蛋白) (p39)","notes":"信号识别颗粒受体(SRP receptor)，又称停泊蛋白DP(docking protein)：位于内质网膜上，与SRP结合使核糖体停泊到ER膜上。\n\n【本页英文讲解】\n本页讲信号识别颗粒受体（SRP receptor），又称停泊蛋白DP（docking protein）。它位于内质网膜上，能与信号识别颗粒（SRP，signal recognition particle）结合，使携有信号肽的核糖体停泊到ER膜上，进而启动共翻译转运。考点：SRP与SRP受体在蛋白质靶向ER中的作用，见教材第八章。","page":39,"level":"掌握","img":"assets/img/ch03/p039.jpg","anim":null,"fig":"SRP 受体位于 rER 膜上，由 α、β 两个亚基组成。α 亚基结合 SRP，使核糖体停泊到膜上。图中 SRP-核糖体复合体与 SRP 受体结合，是“翻译暂停→停泊→继续翻译”的关键一步。","points":null,"check":{"q":"SRP受体（停泊蛋白DP）的功能是？","o":["A. 位于内质网膜上，与SRP结合使核糖体停泊到ER膜上","B. 位于细胞核内，促进核孔运输","C. 位于线粒体外膜，引导蛋白进入线粒体","D. 位于高尔基体，参与糖基化修饰"],"a":"A","e":"SRP受体又称停泊蛋白，位于内质网膜上，与SRP结合使核糖体停泊到ER膜上。","oe":["SRP受体位于内质网膜上，与SRP结合使核糖体停泊到ER膜，正确。","SRP受体位于内质网膜而非细胞核内，不参与核孔运输。","SRP受体位于内质网膜，不是线粒体外膜的引导蛋白。","SRP受体位于内质网膜，不位于高尔基体参与糖基化。"]},"cards":[{"front":"SRP受体又称什么？位于何处？作用是什么？","back":"又称停泊蛋白DP；位于内质网膜上；与SRP结合使核糖体停泊到ER膜","mnemonic":"ER膜上的码头，接SRP靠岸","type":"定位","useImg":true,"blank":"停泊蛋白DP","blank2":"内质网膜"}]},{"i":34,"sec":"第二节 蛋白质分选","title":"SRP与信号肽结合 (p40)","notes":"As a signal sequence emerges from the ribosome and binds to the SRP：信号肽从核糖体伸出→结合SRP→翻译暂停→SRP-核糖体复合物结合ER膜上的SRP受体→翻译恢复，肽链进入ER腔。","page":40,"level":"掌握","img":"assets/img/ch03/p040.jpg","anim":null,"fig":"SRP 与 SRP 受体都具 GTP 酶活性；GTP 水解后 SRP 从受体和信号肽上释放，翻译恢复，肽链经易位子进入 ER。图展示 SRP 的“结合—停泊—释放”循环，可重复使用。","points":null,"check":{"q":"关于SRP（信号识别颗粒）与信号肽结合后的作用，下列叙述正确的是？","o":["A. SRP结合信号肽后促进翻译持续进行","B. SRP结合信号肽后使翻译暂停，待复合物结合ER膜上的SRP受体后翻译恢复","C. SRP直接催化肽链穿过ER膜","D. SRP结合信号肽后立即将信号肽切除"],"a":"B","e":"SRP结合信号肽后使翻译暂停，SRP-核糖体复合物结合ER膜上的SRP受体后翻译恢复，肽链进入ER腔。","oe":["SRP结合信号肽后使翻译暂停，而非促进翻译持续。","SRP结合信号肽使翻译暂停，复合物结合ER上SRP受体后翻译恢复，正确。","SRP不直接催化肽链穿膜，穿膜由易位子完成。","SRP不切除信号肽，切除由信号肽酶完成。"]},"cards":[{"front":"信号肽引导肽链入ER腔的完整流程？","back":"信号肽伸出核糖体→结合SRP→翻译暂停→复合物结合ER膜SRP受体→翻译恢复→肽链入ER腔","mnemonic":"伸—结—停—泊—复—入","type":"流程","useImg":true,"blank":"信号肽","blank2":"SRP受体"}]},{"i":35,"sec":"第二节 蛋白质分选","title":"信号肽假说内容 (p41)","notes":"信号肽假说：①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽被SRP识别结合→翻译暂停；②SRP-核糖体复合物结合ER膜上SRP受体→核糖体附着ER；③翻译恢复，肽链穿膜入ER腔；④信号肽被信号肽酶切除，蛋白继续折叠。","page":41,"level":"掌握","img":"assets/img/ch03/p041.jpg","anim":null,"fig":null,"points":["Blobel 提出信号肽假说(获诺贝尔奖)：信号肽引导核糖体到 ER，蛋白边翻译边进入 ER(共翻译转运)。","实验证据：Milstein 等发现 IgG 轻链先合成带信号肽的前体，进入 ER 后被切除。","共翻译转运：翻译与穿膜同时进行；翻译后转运：翻译完成后才跨膜。"],"check":null,"cards":[{"front":"信号肽假说的四个要点？","back":"①游离核糖体合成至约80aa，N端信号肽被SRP识别，翻译暂停；②复合物结合ER膜SRP受体，核糖体附着ER；③翻译恢复，肽链穿膜入ER腔；④信号肽被信号肽酶切除，蛋白折叠","mnemonic":"游离起、SRP停、受体泊、切肽折","type":"流程","useImg":false,"blank":"信号肽","blank2":"信号肽酶"}]},{"i":36,"sec":"第二节 蛋白质分选","title":"分泌蛋白的共翻译转移 (p42)","notes":"ER lumen/cytosol：分泌蛋白在游离核糖体起始合成→信号肽引导→附着rER→共翻译转移入ER腔。\n\n【本页英文讲解】\n本页讲分泌蛋白（secretory protein）的共翻译转移（co-translational translocation）。分泌蛋白在游离核糖体上起始合成，信号肽引导核糖体附着到粗面内质网（rER），新生肽链边合成边经易位子转移入内质网腔（ER lumen），而非留在胞质（cytosol）。考点：共翻译转运的步骤，见翟中和教材第八章。","page":42,"level":"掌握","img":"assets/img/ch03/p042.jpg","anim":null,"fig":null,"points":null,"check":{"q":"分泌蛋白的共翻译转移过程是？","o":["A. 在游离核糖体上完成全部合成后再进入ER","B. 在游离核糖体起始合成，信号肽引导附着rER，边翻译边转移入ER腔","C. 在细胞核内合成后直接进入ER","D. 在高尔基体中合成后进入ER"],"a":"B","e":"分泌蛋白在游离核糖体起始合成，经信号肽引导附着到rER，通过共翻译转移进入ER腔。","oe":["分泌蛋白不是游离核糖体合成完毕后再进入ER，属后转移误区。","分泌蛋白在游离核糖体起始，经信号肽引导附着rER，边翻译边转移入ER腔，正确。","分泌蛋白在核糖体上合成，并不在细胞核内合成。","蛋白质在核糖体合成，高尔基体负责加工分选，不在高尔基体合成。"]},"cards":[{"front":"分泌蛋白如何进入ER腔？","back":"游离核糖体起始合成→信号肽引导→附着rER→共翻译转移入ER腔","mnemonic":"边合成边进门","type":"流程","useImg":true,"blank":"共翻译转移","blank2":"游离核糖体"}]},{"i":37,"sec":"第二节 蛋白质分选","title":"起始转移序列 (p43)","notes":"蛋白质跨膜相关概念。开始/起始转移序列(start transfer sequence)：蛋白质的信号序列，除了作为信号被识别外，还能启动肽链穿膜转移。","page":43,"level":"掌握","img":"assets/img/ch03/p043.jpg","anim":null,"fig":"起始转移序列(信号肽)既引导核糖体到膜上，又作为跨膜的“起始”信号，使肽链穿入 ER 腔。若同时还有停止转移序列，则形成单次跨膜蛋白。","points":null,"check":{"q":"起始转移序列（start transfer sequence）的功能是？","o":["A. 仅作为信号被识别，不参与穿膜","B. 既作为信号被识别，又能启动肽链穿膜转移","C. 使肽链停止穿膜并形成跨膜段","D. 将肽链从ER腔运回细胞质"],"a":"B","e":"起始转移序列除作为信号被识别外，还能启动肽链穿膜转移。","oe":["起始转移序列既作为信号又能启动穿膜，不只是被识别。","起始转移序列既作为信号被识别，又能启动肽链穿膜转移，正确。","使肽链停止穿膜并形成跨膜段的是停止转移序列。","将肽链运回细胞质的说法错误，该序列启动穿膜转移。"]},"cards":[{"front":"起始转移序列的定义？","back":"蛋白质的信号序列；除被识别外，还能启动肽链穿膜转移","mnemonic":"信号+启动穿膜，二合一","type":"定义","useImg":false,"blank":"信号序列","blank2":"肽链穿膜转移"}]},{"i":38,"sec":"第二节 蛋白质分选","title":"停止转移序列 (p44)","notes":"停止转移序列(stop transfer sequence)：肽链中某些序列与内质网膜有很强亲和力，紧密结合在膜脂双层中而不转移，使肽链停止穿膜，形成跨膜段。","page":44,"level":"掌握","img":"assets/img/ch03/p044.jpg","anim":null,"fig":"停止转移序列是一段约 20 个氨基酸的疏水序列，能“叫停”穿膜并使肽链锚定在膜上。图中起始转移序列＋停止转移序列 → 单次跨膜蛋白；只有起始序列 → 可溶性蛋白进入腔内。","points":null,"check":{"q":"停止转移序列（stop transfer sequence）的作用是？","o":["A. 启动肽链穿膜转移","B. 与内质网膜紧密结合，使肽链停止穿膜并形成跨膜段","C. 促进翻译暂停","D. 将信号肽从肽链上切除"],"a":"B","e":"停止转移序列与内质网膜有很强亲和力，紧密结合在膜脂双层中使肽链停止穿膜，形成跨膜段。","oe":["启动肽链穿膜转移的是起始转移序列，不是停止转移序列。","停止转移序列与膜紧密结合，使肽链停止穿膜并形成跨膜段，正确。","促进翻译暂停的是SRP，不是停止转移序列。","切除信号肽的是信号肽酶，不是停止转移序列。"]},"cards":[{"front":"停止转移序列的定义与作用？","back":"与内质网膜强亲和力的序列；紧密结合膜脂双层不转移；使肽链停止穿膜，形成跨膜段","mnemonic":"粘住膜，刹车成跨膜段","type":"定义","useImg":true,"blank":"停止转移序列"}]},{"i":39,"sec":"第二节 蛋白质分选","title":"可溶性蛋白的转运 (p45)","notes":"可溶性蛋白(soluble protein)转运穿过ER膜到达ER腔：一种多肽只有N端信号序列(开始转移序列)、无停止序列→此蛋白完全进入ER腔成为可溶性蛋白。","page":45,"level":"掌握","img":"assets/img/ch03/p045.jpg","anim":null,"fig":"可溶性分泌蛋白只有起始转移序列，肽链完全穿过易位子进入 ER 腔，信号肽被切除。图对比可溶性蛋白与膜蛋白在易位子中的走向差异。","points":null,"check":null,"cards":[{"front":"可溶性蛋白如何完全进入ER腔？","back":"只有N端信号序列（开始转移序列）、无停止序列；多肽完全转入ER腔成为可溶性蛋白。","mnemonic":"有头无尾，全进腔","type":"流程","useImg":true,"blank":"可溶性蛋白","blank2":"停止序列"}]},{"i":40,"sec":"第二节 蛋白质分选","title":"跨膜蛋白的形成 (p46)","notes":"蛋白质N端有ER起始信号序列启动转移，中部还含终止转移序列。N端信号序列被切除，停止转移序列使蛋白锚在ER膜上→形成单次跨膜蛋白。","page":46,"level":"掌握","img":"assets/img/ch03/p046.jpg","anim":"transmembrane_topology","fig":null,"points":null,"check":null,"cards":[{"front":"单次跨膜蛋白如何形成？","back":"N端起信号序列启动转移；中部终止转移序列使肽链锚在ER膜上；N端信号被切除。","mnemonic":"头切尾锚，一次穿膜","type":"流程","useImg":true,"blank":"终止转移序列","blank2":"N端起信号序列"}]},{"i":41,"sec":"第二节 蛋白质分选","title":"多次跨膜蛋白 (p47)","notes":"一个内部的起始转移信号起起始转运作用并启动肽链转移；起始序列和停止序列都不被切除，整个多肽链作为穿膜两次的跨膜蛋白——多次跨膜蛋白的形成机制。","page":47,"level":"掌握","img":"assets/img/ch03/p047.jpg","anim":null,"fig":"跨膜蛋白的拓扑(穿膜次数、N/C 端朝向)由肽链中起始转移序列和停止转移序列的数目与位置决定。图给出单次、多次跨膜蛋白的几种拓扑类型，是理解膜蛋白结构的关键。","points":null,"check":{"q":"关于多次跨膜蛋白的形成机制，下列叙述正确的是？","o":["A. 起始序列和停止序列都会被切除","B. 一个内部起始转移信号启动肽链转移，起始序列和停止序列都不被切除，多肽链形成穿膜两次的跨膜蛋白","C. 多次跨膜蛋白只在细胞质中合成","D. 多次跨膜蛋白不需要停止转移序列"],"a":"B","e":"内部起始转移信号启动转运，起始序列和停止序列均不被切除，整个多肽链作为穿膜两次的跨膜蛋白。","oe":["多次跨膜蛋白的起始序列和停止序列均不被切除。","内部起始转移信号启动转运，起始与停止序列均不切除，形成两次跨膜蛋白，正确。","多次跨膜蛋白在ER膜上共翻译转移形成，并非只在细胞质合成。","多次跨膜蛋白的形成需要停止转移序列参与。"]},"cards":[{"front":"多次跨膜蛋白的形成机制是什么？","back":"内部起始转移信号启动转运；起始序列和停止序列均不被切除；肽链穿膜两次形成多次跨膜蛋白。","mnemonic":"内起不切，来回穿梭","type":"流程","useImg":true,"blank":"多次跨膜蛋白","blank2":"内部起始转移信号"}]},{"i":42,"sec":"第二节 蛋白质分选","title":"翻译后加工 (p48)","notes":"翻译完毕的蛋白多肽链必须经过后期蛋白修饰加工才能具备功能：折叠、磷酸化、糖基化修饰等。","page":48,"level":"掌握","img":"assets/img/ch03/p048.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于翻译后加工，下列叙述正确的是？","o":["A. 翻译完毕的肽链无需加工即具备功能","B. 翻译完毕的肽链必须经过折叠、磷酸化、糖基化等后期修饰加工才能具备功能","C. 翻译后加工只发生在细胞核内","D. 翻译后加工仅指肽链的降解"],"a":"B","e":"翻译完毕的蛋白多肽链必须经过折叠、磷酸化、糖基化等后期修饰加工才能具备功能。","oe":["翻译完毕的肽链通常需加工修饰才具功能，并非立即有功能。","肽链必须经折叠、磷酸化、糖基化等翻译后加工才具备功能，正确。","翻译后加工在细胞质及内质网、高尔基体等中进行，不只在细胞核。","翻译后加工包括折叠、修饰等，不只是肽链降解。"]},"cards":[{"front":"翻译后的多肽链为何需要加工？","back":"新生肽链须经折叠、磷酸化、糖基化等翻译后修饰才能具备功能。","mnemonic":"裸链无用，修饰成才","type":"功能","useImg":false,"blank":"翻译后修饰","blank2":"折叠"}]},{"i":43,"sec":"第二节 蛋白质分选","title":"rER的糖基化 (p49)","notes":"rER的功能：蛋白质修饰(post-translational modifications)——糖基化(glycosylation)，主要发生N-连接糖基化。\n\n【本页英文讲解】\n本页讲粗面内质网（rER）的糖基化功能。rER可对蛋白质进行翻译后修饰（post-translational modifications），其中主要是糖基化（glycosylation），且以N-连接糖基化为主，即糖链连接在天冬酰胺残基的酰胺氮上。糖基化有助于蛋白质正确折叠、稳定与分选。考点：N-连接与O-连接糖基化的区别，见教材第七章。","page":49,"level":"掌握","img":"assets/img/ch03/p049.jpg","anim":"n_glycosylation","fig":null,"points":null,"check":null,"cards":[{"front":"rER的主要蛋白修饰功能是什么？","back":"糖基化修饰，主要为N-连接糖基化。","mnemonic":"粗面内质网，N糖加工厂","type":"功能","useImg":false,"blank":"糖基化修饰","blank2":"N-连接糖基化"}]}],"mcq":[{"id":"ch03_mcq_1","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内膜系统不包括下列哪个？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 线粒体"],"a":"D","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成(ER/高尔基/溶酶体/内体/液泡/分泌小泡)；线粒体虽具膜但不属内膜系统。","kp":"ch03_s0_2"},{"id":"ch03_mcq_2","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"粗面内质网(rER)的主要功能是？","o":["A. 合成脂类","B. 合成分泌蛋白和膜蛋白(膜上有核糖体)","C. 解毒","D. 储钙"],"a":"B","e":"rER膜表面有大量核糖体，合成分泌性蛋白和多种膜蛋白；sER无核糖体，合成脂类、解毒、储钙。","kp":"ch03_s0_10"},{"id":"ch03_mcq_3","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"光面内质网(sER)的功能不包括？","o":["A. 解毒","B. 储钙","C. 合成膜脂","D. 合成分泌蛋白"],"a":"D","e":"sER功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。合成分泌蛋白是rER功能。","kp":"ch03_s0_9"},{"id":"ch03_mcq_4","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"易位子(translocon)位于？","o":["A. 高尔基体膜","B. 粗面内质网膜","C. 溶酶体膜","D. 线粒体外膜"],"a":"B","e":"易位子是rER膜上的蛋白复合体(核心为Sec61复合体)，中心有2nm孔道，新生肽链由此进入ER腔。","kp":"ch03_s0_19"},{"id":"ch03_mcq_5","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号识别颗粒(SRP)的组成是？","o":["A. 6种多肽+1个7S RNA","B. 仅蛋白质","C. 仅RNA","D. 糖蛋白"],"a":"A","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，既结合信号肽又结合核糖体大亚基，暂停翻译。","kp":"ch03_s0_32"},{"id":"ch03_mcq_6","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号肽假说中,肽链转移进入ER腔的机制是？","o":["A. 翻译后转移","B. 边翻译边转移(共翻译转移)","C. 胞吞","D. 自由扩散"],"a":"B","e":"分泌蛋白在游离核糖体起始合成→信号肽被SRP识别→附着ER→共翻译转移入ER腔，信号肽被切除。","kp":"ch03_s0_35"},{"id":"ch03_mcq_7","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"可溶性蛋白进入ER腔的条件是？","o":["A. 只有N端信号序列,无停止转移序列","B. 含停止转移序列","C. 无信号序列","D. 含多个起始序列"],"a":"A","e":"只含N端信号序列(开始转移序列)、无停止序列→蛋白完全进入ER腔成可溶性蛋白；有停止序列则锚在膜上成跨膜蛋白。","kp":"ch03_s0_39"},{"id":"ch03_mcq_8","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"N-连接糖基化与O-连接糖基化的区别,错误的是？","o":["A. N-连接起始于rER,O-连接在高尔基体","B. N-连接结合Asn,O-连接结合Ser/Thr","C. N-连接来自同一寡糖前体","D. O-连接起始于内质网"],"a":"D","e":"O-连接糖基化在高尔基体进行，单糖逐个加到Ser/Thr羟基上；N-连接起始于rER，结合Asn，来自同一寡糖前体。","kp":"ch03_s0_43"},{"id":"ch03_mcq_9","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"催化ER腔内二硫键形成的酶是？","o":["A. PDI","B. Bip","C. SRP","D. Hsp70"],"a":"A","e":"PDI(蛋白二硫键异构酶)是ER驻留蛋白，催化二硫键形成与重排。Bip是分子伴侣识别错误折叠蛋白。","kp":"ch03_s0_12"},{"id":"ch03_mcq_10","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"Bip蛋白的功能是？","o":["A. 催化二硫键","B. 识别未正确折叠/未组装的蛋白,帮助折叠","C. 合成脂类","D. 切除信号肽"],"a":"B","e":"Bip(binding protein)是ER驻留分子伴侣，识别不正确折叠或未组装的蛋白，防止聚集并帮助折叠。","kp":"ch03_s0_18"},{"id":"ch03_mcq_11","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内质网驻留蛋白的驻留信号是？","o":["A. KDEL序列","B. M6P","C. NLS","D. NES"],"a":"A","e":"Bip、PDI等ER驻留蛋白含C端KDEL(内质网驻留信号)，被保留在ER中。M6P是溶酶体分选信号。","kp":"ch03_s0_9"},{"id":"ch03_mcq_12","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"2004年诺贝尔化学奖授予的发现是？","o":["A. 泛素介导的蛋白质降解","B. 水通道","C. RNAi","D. 端粒酶"],"a":"A","e":"2004年诺贝尔化学奖授予Ciechanover、Hershko、Rose，发现泛素介导的蛋白质降解。","kp":"ch03_s0_28"}],"judge":[{"id":"ch03_judge_1","modI":0,"q":"内膜系统包括内质网、高尔基体、溶酶体，但不包括线粒体和叶绿体。","a":"对","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成；线粒体、叶绿体不属内膜系统。","kp":"ch03_s0_2"},{"id":"ch03_judge_2","modI":0,"q":"粗面内质网表面附着大量核糖体，主要合成分泌蛋白和膜蛋白。","a":"对","e":"rER膜上有核糖体与易位子，合成分泌蛋白和膜蛋白；sER无核糖体。","kp":"ch03_s0_9"},{"id":"ch03_judge_3","modI":0,"q":"光面内质网的功能包括解毒、储钙和合成膜脂。","a":"对","e":"sER三大功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。","kp":"ch03_s0_13"},{"id":"ch03_judge_4","modI":0,"q":"易位子(translocon)位于高尔基体膜上，介导蛋白质进入高尔基体腔。","a":"错","e":"易位子位于粗面内质网(rER)膜上，核心为Sec61复合体，介导新生肽链进入ER腔。","kp":"ch03_s0_19"}],"fill":[{"id":"ch03_fill_1","modI":0,"q":"内膜系统是在结构、功能乃至发生上相关的、由________膜围绕成的细胞器,包括内质网、________、溶酶体等。","a":"单层,高尔基体","kp":"ch03_s0_2"},{"id":"ch03_fill_2","modI":0,"q":"粗面内质网表面分布大量________,主要合成分泌蛋白；光面内质网的功能有解毒、储钙和________。","a":"核糖体,合成膜脂","kp":"ch03_s0_9"},{"id":"ch03_fill_3","modI":0,"q":"rER膜上的蛋白复合体________(核心为Sec61)中心有直径2nm孔道,使新生肽链进入ER腔。","a":"易位子(translocon)","kp":"ch03_s0_21"},{"id":"ch03_fill_12","modI":0,"q":"内质网驻留蛋白Bip和PDI属于________,其中PDI催化________的形成。","a":"分子伴侣(ER驻留蛋白),二硫键","kp":"ch03_s0_40"}],"short":[{"id":"ch03_short_2","modI":0,"q":"简述内质网的功能。","a":"内质网分粗面内质网(rER)和光面内质网(sER)：\n\n【rER功能】\n①蛋白质合成——膜上有易位子，新生肽链共翻译转移入ER腔；\n②蛋白质的N-连接糖基化修饰；\n③新生多肽的折叠与装配(二硫键形成，PDI催化)；\n④蛋白质质量监控(只有正确折叠的蛋白才能离开ER)；\n⑤错误折叠蛋白经ERAD途径降解。\n\n【sER功能】\n①解毒(肝细胞，细胞色素P450)；\n②储钙(Ca库，Ca2+-ATPase泵入Ca2+，参与信号传递)；\n③合成膜脂(甘油磷脂和胆固醇)。\n\n【其他】\nER是内膜系统的重要组分，膜脂在ER合成后运往其他膜；ER驻留蛋白含KDEL信号。","kp":"ch03_s0_11"}],"calc":[{"id":"ch03_calc_1","modI":0,"q":"论述内膜系统的组成、膜泡运输途径及其生物学意义。","a":"内膜系统是真核细胞分室化的结构基础,膜泡运输实现区室间物质交流","steps":"【组成】\n由单层膜围绕、结构功能发生上相关的细胞器：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)。\n\n【膜泡运输途径】\n①分泌途径(向外)：ER→高尔基体(CGN→中间→TGN)→分泌小泡→质膜/胞外或溶酶体；\n②胞吞途径(向内)：质膜→早期胞内体→晚期胞内体→溶酶体；\n③回收途径：逃逸蛋白经COPI小泡返回ER。\n\n【意义】\n①实现细胞分室化，各细胞器功能专一、效率高；\n②完成蛋白质的合成、加工、分选和运输(分泌蛋白、膜蛋白、溶酶体酶)；\n③实现物质的摄取(胞吞)与降解(溶酶体)；\n④维持细胞器膜的特性和动态平衡；\n⑤是真核细胞比原核细胞复杂高效的根本原因。","kp":"ch03_s0_0"},{"id":"ch03_calc_2","modI":0,"q":"论述内质网的蛋白质质量监控体系及其意义。","a":"ER质量监控确保只有正确折叠的蛋白才能离开ER,错误蛋白被降解","steps":"【监控体系组成】\n①分子伴侣：Bip(识别错误折叠/未组装蛋白)、Hsp70家族；\n②折叠酶：PDI(催化二硫键形成与重排)；\n③糖基化系统：N-连接糖基化参与折叠监控；\n④ER驻留信号KDEL使Bip/PDI留在ER。\n\n【监控机制】\n①新生肽链进入ER腔→分子伴侣帮助折叠；\n②正确折叠和装配的蛋白→允许离开ER运往高尔基体；\n③错误折叠蛋白→被Bip滞留→反复尝试折叠；\n④长期不能正确折叠→逆向转运至胞质(ERAD)→泛素化→26S蛋白酶体降解。\n\n【意义】\n①保证分泌蛋白和膜蛋白的质量；\n②防止错误折叠蛋白聚集造成细胞损伤；\n③与多种疾病相关(如囊性纤维化CFTR突变、α1-抗胰蛋白酶缺乏症等折叠病)；\n④维持细胞稳态。","kp":"ch03_s0_18"}],"term":[{"id":"ch03_term_1","modI":0,"term":"内膜系统(Endomembrane System)","def":"①在结构、功能乃至发生上相关的、由单层膜围绕成的细胞器或细胞结构（定义）。②组成：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)（组成）。③特点：膜相互流动、可相互转化（特点）。④意义：是真核细胞分室化的基础（意义）。","kps":"踩分点:①定义(1分)②组成(2分)③意义(1分)","kp":"ch03_s0_2"},{"id":"ch03_term_2","modI":0,"term":"粗面内质网(rER)","def":"①膜表面分布大量核糖体的内质网，多呈扁囊状（定义）。②功能：合成分泌性蛋白和膜蛋白；蛋白质N-连接糖基化；新生肽折叠与装配；蛋白质质量监控（功能）。③膜上有易位子(translocon)介导肽链进入ER腔（结构）。","kps":"踩分点:①定义(1分)②功能(2分)③易位子(1分)","kp":"ch03_s0_10"},{"id":"ch03_term_3","modI":0,"term":"光面内质网(sER)","def":"①表面无核糖体的内质网（定义）。②功能：解毒(肝细胞细胞色素P450)；储钙(Ca库，Ca2+-ATPase泵入，参与信号传递)；合成膜脂(甘油磷脂和胆固醇)（功能）。","kps":"踩分点:①定义(1分)②三大功能(3分)","kp":"ch03_s0_9"},{"id":"ch03_term_4","modI":0,"term":"易位子(Translocon)","def":"①rER膜上的蛋白复合体，中心有直径2nm的孔道（定义）。②核心为Sec61复合体(Sec61α/β/γ)，高度保守（结构）。③功能：介导新生肽链进入ER腔（功能）。","kps":"踩分点:①定义(1分)②Sec61(1分)③功能(1分)","kp":"ch03_s0_19"},{"id":"ch03_term_7","modI":0,"term":"分子伴侣(Molecular Chaperone)","def":"①能识别并结合正在合成或部分折叠的多肽、帮助其折叠装配的蛋白（定义）。②特点：不构成最终产物的一部分；高度保守(如Hsp70)（特点）。③举例：Bip、Hsp70、伴侣蛋白GroEL/GroES（举例）。④意义：帮助蛋白正确折叠、防止聚集（意义）。","kps":"踩分点:①定义(1分)②特点(1分)③举例(1分)④意义(1分)","kp":"ch03_s0_4"},{"id":"ch03_term_8","modI":0,"term":"Bip蛋白","def":"①内质网驻留的分子伴侣(binding protein)（定义）。②功能：识别不正确折叠或未组装的蛋白，防止聚集，帮助折叠（功能）。③含KDEL内质网驻留信号，被保留在ER中（特点）。","kps":"踩分点:①定义(1分)②功能(2分)③KDEL(1分)","kp":"ch03_s0_0"},{"id":"ch03_term_15","modI":0,"term":"分子伴侣介导的蛋白折叠","def":"①分子伴侣通过反复结合与释放，帮助新生多肽折叠的机制（定义）。②与伴侣蛋白(GroEL/GroES)的隔离腔室折叠方式不同（区别）。③最终三维构象仍由氨基酸序列决定（特点）。","kps":"踩分点:①定义(1分)②与伴侣蛋白区别(2分)③序列决定构象(1分)","kp":"ch03_s0_18"}]},{"i":1,"name":"模块二：蛋白质分选与降解","slides":[{"i":0,"sec":"第二节 蛋白质分选","title":"N-糖基化过程 (p50)","notes":"内质网腔面，寡糖链连在插入膜内的磷酸多萜醇(dolichol)上，当与糖基化有关的氨基酸残基天冬酰胺(Asn)出现后，通过膜上的糖基转移酶将寡糖链转移到Asn残基上。","page":50,"level":"掌握","img":"assets/img/ch03/p050.jpg","anim":"glycosylation","fig":"图显示 N-连接糖基化：磷酸多萜醇(dolichol)先在内质网膜上组装寡糖前体，再整体转移给新生肽链的 Asn 残基。这是 ER 内最主要的糖基化方式。","points":["N-连接糖基化起始于 rER：糖链连到 Asn 的酰胺氮上，供体是磷酸多萜醇。","O-连接糖基化发生在高尔基体：糖链连到 Ser/Thr 的羟基氧上。","N-糖基化在 ER 先加核心糖链，到 Golgi 再加工修饰。"],"check":{"q":"关于N-糖基化过程，下列叙述正确的是？","o":["A. 寡糖链直接连在肽链的丝氨酸残基上","B. 在内质网腔面，寡糖链连在磷酸多萜醇上，通过糖基转移酶转移到Asn残基上","C. N-糖基化发生在细胞质中","D. 寡糖链通过核糖体直接转移到肽链上"],"a":"B","e":"在内质网腔面，寡糖链连在磷酸多萜醇上，当Asn残基出现后由糖基转移酶将寡糖链转移到Asn残基上。","oe":["连在丝氨酸残基上的是O-糖基化，不是N-糖基化。","在ER腔面寡糖链连在磷酸多萜醇上，经糖基转移酶转到Asn残基，正确。","N-糖基化发生在内质网腔面，而非细胞质中。","寡糖链不是由核糖体直接转移到肽链上的。"]},"cards":[{"front":"N-糖基化过程中寡糖链如何转移？","back":"ER腔面寡糖链连在磷酸多萜醇上；Asn残基出现后，糖基转移酶将寡糖链转移到Asn上。","mnemonic":"多萜醇载糖，酶转给Asn","type":"流程","useImg":true,"blank":"磷酸多萜醇","blank2":"糖基转移酶"}]},{"i":1,"sec":"第二节 蛋白质分选","title":"N-连接糖基化位点 (p51)","notes":"一旦新生肽链上的天冬酰胺残基(Asn-X-Ser/Thr)进入rER腔，在糖基转移酶作用下进行蛋白N-糖基化修饰。N-连接寡糖的核心糖链结构保守。","page":51,"level":"掌握","img":"assets/img/ch03/p051.jpg","anim":null,"fig":null,"points":null,"check":{"q":"N-连接糖基化位点的序列特征是？","o":["A. Asn-X-Ser/Thr","B. Ser-X-Asn/Thr","C. Thr-X-Ser/Asn","D. Asn-X-Thr/Ser"],"a":"A","e":"N-连接糖基化位点为Asn-X-Ser/Thr，新生肽链上的该序列进入rER腔后在糖基转移酶作用下进行N-糖基化修饰。","oe":["标准N-连接糖基化位点为Asn-X-Ser/Thr，正确。","该位点以Asn起始，不是以Ser起始，顺序错误。","该位点首位为Asn而非Thr，顺序不符合。","标准表述为Asn-X-Ser/Thr，该选项残基顺序与规范写法不符。"]},"cards":[{"front":"N-连接糖基化的识别位点是什么？","back":"Asn-X-Ser/Thr；进入rER腔后由糖基转移酶催化，核心糖链结构保守。","mnemonic":"天冬酰胺，X后带丝苏","type":"定位","useImg":false,"blank":"Asn-X-Ser/Thr","blank2":"糖基转移酶"}]},{"i":2,"sec":"第二节 蛋白质分选","title":"N-连接vs O-连接糖基化 (p52)","notes":"N-连接 vs O-连接糖基化：①合成部位——N-连接起始于粗面内质网，O-连接在高尔基体；②合成方式——N-连接来自同一个寡糖前体，O-连接一个个单糖加上去；③结合的氨基酸残基——N-连接为Asn，O-连接为Ser/Thr。","page":52,"level":"掌握","img":"assets/img/ch03/p052.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"N-连接与O-连接糖基化的三大区别？","back":"部位：N在rER，O在高尔基；方式：N用同一寡糖前体，O逐个加单糖；残基：N为Asn，O为Ser/Thr。","mnemonic":"N内O高，N整O零，N天O丝","type":"对比","useImg":false,"blank":"寡糖前体","blank2":"高尔基"}]},{"i":3,"sec":"第二节 蛋白质分选","title":"糖基化的生物学功能 (p53)","notes":"蛋白质糖基化的生物学功能：细胞内负责糖链合成与加工的酶类均为管家基因编码。①促进蛋白质折叠(如抗体IgG或质膜糖蛋白血凝素)；②影响蛋白稳定性、半衰期；③参与细胞识别、免疫；④溶酶体酶的M6P分选信号。","page":53,"level":"掌握","img":"assets/img/ch03/p053.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"蛋白质糖基化有哪些生物学功能？","back":"①促进蛋白质折叠；②影响蛋白稳定性与半衰期；③参与细胞识别与免疫；④提供溶酶体酶M6P分选信号","mnemonic":"折、稳、识、分（分选）","type":"功能","useImg":false,"blank":"M6P分选信号","blank2":"细胞识别与免疫"}]},{"i":4,"sec":"第二节 蛋白质分选","title":"新生肽的折叠与装配 (p54)","notes":"ER的功能：新生多肽的折叠(folding)与装配(assembly)——分子间/分子内的二硫键(2Cys-SH→Cys-S-S-Cys)在ER腔形成。\n\n【本页英文讲解】\n本页讲内质网（ER）对新生多肽的折叠（folding）与装配（assembly）功能。在ER腔中，多肽链折叠并装配成有功能的构象，同时形成分子间或分子内的二硫键（disulfide bond），即由两个半胱氨酸巯基2Cys-SH氧化为Cys-S-S-Cys。这是ER作为蛋白质加工与质量控制细胞器的重要功能，联系教材第七章。","page":54,"level":"掌握","img":"assets/img/ch03/p054.jpg","anim":"chaperone_folding","fig":null,"points":null,"check":null,"cards":[{"front":"内质网在新生肽加工中的核心功能是什么？","back":"新生多肽的折叠与装配；分子内/间二硫键在ER腔内形成","mnemonic":"ER=折叠车间+装配线","type":"功能","useImg":true,"blank":"折叠与装配","blank2":"二硫键"}]},{"i":5,"sec":"第二节 蛋白质分选","title":"二硫键在ER腔形成 (p55)","notes":"In eukaryotic cells, disulfide bonds are formed only in the lumen of the ER——真核细胞中二硫键只在ER腔内形成，由二硫键异构酶(PDI)催化。\n\n【本页英文讲解】\n本页讲二硫键（disulfide bond）在真核细胞中的形成场所。二硫键只在ER腔内形成（disulfide bonds form only in the ER lumen），由二硫键异构酶（PDI，protein disulfide isomerase）催化。PDI既能催化二硫键形成，也能纠正错误配对。考点：ER腔的氧化环境及PDI功能，见教材第七章。","page":55,"level":"掌握","img":"assets/img/ch03/p055.jpg","anim":null,"fig":"二硫键(S–S)在 ER 腔内形成，连接两个 Cys，稳定蛋白质三维结构。图说明 ER 腔的氧化环境有利于二硫键形成，这是胞质(还原环境)中难以进行的。","points":null,"check":{"q":"关于真核细胞中二硫键形成的叙述，正确的是？","o":["A. 二硫键可在细胞质基质中自发形成","B. 二硫键只在ER腔内形成，由PDI催化","C. 二硫键在线粒体基质中形成","D. 二硫键由核糖体直接催化形成"],"a":"B","e":"真核细胞中二硫键只在ER腔内形成，由二硫键异构酶(PDI)催化。","oe":["细胞质为还原性环境，二硫键不能在细胞质基质中自发形成。","真核细胞中二硫键只在ER腔内形成，由PDI催化，正确。","二硫键不在线粒体基质中形成，而在ER腔内形成。","二硫键由PDI催化形成，核糖体不催化二硫键形成。"]},"cards":[{"front":"真核细胞中二硫键在何处形成？由什么酶催化？","back":"只在ER腔内形成；由二硫键异构酶（PDI）催化","mnemonic":"二硫键只认ER腔","type":"定位","useImg":true,"blank":"二硫键异构酶","blank2":"ER腔内"}]},{"i":6,"sec":"第二节 蛋白质分选","title":"PDI蛋白 (p56)","notes":"PDI(蛋白二硫键异构酶)是ER驻留蛋白，存在于所有真核细胞，尤其丰富于分泌细胞，催化二硫键的形成与重排。","page":56,"level":"掌握","img":"assets/img/ch03/p056.jpg","anim":null,"fig":"蛋白二硫键异构酶(PDI)催化二硫键的形成、重排和还原，帮助蛋白折叠到正确构象。图显示 PDI 在 ER 腔中反复作用，是 ER 驻留蛋白(含 KDEL)。","points":null,"check":{"q":"关于PDI(蛋白二硫键异构酶)的叙述，错误的是？","o":["A. 是ER驻留蛋白","B. 存在于所有真核细胞","C. 在分泌细胞中尤其丰富","D. 只能催化二硫键形成，不能重排"],"a":"D","e":"PDI催化二硫键的形成与重排，而非仅形成。","oe":["PDI是ER驻留蛋白，该叙述正确。","PDI存在于所有真核细胞中，该叙述正确。","PDI在分泌细胞中尤其丰富，该叙述正确。","该说法错误，PDI既催化二硫键形成，也催化其重排，故为答案。"]},"cards":[{"front":"PDI是什么？分布有何特点？","back":"蛋白二硫键异构酶；ER驻留蛋白，存在于所有真核细胞，分泌细胞中尤其丰富；催化二硫键形成与重排","mnemonic":"PDI=二硫键的裁缝","type":"定义","useImg":false,"blank":"蛋白二硫键异构酶","blank2":"ER驻留蛋白"}]},{"i":7,"sec":"第二节 蛋白质分选","title":"Bip蛋白 (p57)","notes":"Bip(binding protein)：ER驻留蛋白，识别不正确折叠的蛋白或未组装的蛋白，防止其聚集，帮助其正确折叠。属于分子伴侣。","page":57,"level":"掌握","img":"assets/img/ch03/p057.jpg","anim":null,"fig":"Bip 是 ER 腔中的分子伴侣(Hsp70 家族)，结合新生肽链的疏水区，防止错误聚集并帮助折叠。图说明 Bip 也参与未折叠蛋白反应(UPR)和 ERAD 的识别。","points":null,"check":{"q":"Bip蛋白的主要功能是？","o":["A. 催化二硫键形成","B. 识别错误折叠或未组装蛋白，防止聚集并帮助折叠","C. 降解错误折叠蛋白","D. 将蛋白从ER运往高尔基体"],"a":"B","e":"Bip是ER驻留的分子伴侣，识别不正确折叠或未组装的蛋白，防止聚集并帮助其正确折叠。","oe":["催化二硫键形成的是PDI，不是Bip。","Bip识别错误折叠或未组装蛋白，防止聚集并帮助折叠，正确。","降解错误折叠蛋白主要靠泛素-蛋白酶体系统，不是Bip。","将蛋白从ER运往高尔基体的是膜泡运输，不是Bip。"]},"cards":[{"front":"Bip蛋白的功能是什么？属于哪类蛋白？","back":"ER驻留分子伴侣；识别错误折叠或未组装蛋白，防止其聚集，帮助正确折叠","back2":"","mnemonic":"Bip=ER里的纠错员","type":"功能","useImg":false,"blank":"分子伴侣","blank2":"错误折叠或未组装蛋白"}]},{"i":8,"sec":"第二节 蛋白质分选","title":"分子伴侣 (p58)","notes":"分子伴侣(Molecular chaperones)：细胞中一些蛋白分子可识别并结合正在合成、部分折叠的多肽，帮助新生多肽折叠、装配，但不构成最终产物的一部分。","page":58,"level":"掌握","img":"assets/img/ch03/p058.jpg","anim":null,"fig":null,"points":["分子伴侣帮助蛋白折叠/组装，但不构成最终产物。","ER 腔中的伴侣：Bip、钙联蛋白、钙网蛋白等。","分子伴侣还负责识别错误折叠蛋白，送交 ERAD 降解。"],"check":{"q":"关于分子伴侣的叙述，正确的是？","o":["A. 是最终产物的一部分","B. 只识别完全折叠的蛋白","C. 帮助新生多肽折叠、装配，但不构成最终产物的一部分","D. 只在原核细胞中存在"],"a":"C","e":"分子伴侣帮助新生多肽折叠和装配，但不构成最终产物的一部分。","oe":["分子伴侣仅辅助折叠，折叠后即释放，不构成最终产物。","分子伴侣识别未折叠或部分折叠肽段的疏水区，而非完全折叠蛋白。","分子伴侣与新生多肽结合帮助其正确折叠装配，本身不构成产物。","分子伴侣在原核和真核细胞中均广泛存在，并非原核特有。"]},"cards":[{"front":"什么是分子伴侣？","back":"能识别并结合正在合成或部分折叠的多肽，帮助其折叠、装配，但不构成最终产物一部分的蛋白","mnemonic":"帮忙不入职（不成为产物）","type":"定义","useImg":false,"blank":"帮助其折叠、装配","blank2":"正在合成或部分折叠的多肽"}]},{"i":9,"sec":"第二节 蛋白质分选","title":"分子伴侣的结构特点 (p59)","notes":"分子伴侣结构特点：高度保守性——Hsp70广泛存在于真核、原核生物中(细菌、果蝇、酵母、哺乳动物)，同源性高。Hsp70家族成员协助蛋白折叠。","page":59,"level":"掌握","img":"assets/img/ch03/p059.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于分子伴侣结构特点的叙述，正确的是？","o":["A. Hsp70只存在于真核生物","B. Hsp70高度保守，广泛存在于真核和原核生物中","C. Hsp70家族不参与蛋白折叠","D. 分子伴侣在不同物种间同源性很低"],"a":"B","e":"Hsp70高度保守，广泛存在于细菌、果蝇、酵母、哺乳动物等真核和原核生物中，同源性高。","oe":["Hsp70也广泛存在于细菌等原核生物中，并非只存在于真核生物。","Hsp70高度保守、同源性高，广泛分布于真核和原核生物中。","Hsp70家族是重要分子伴侣，直接参与帮助蛋白质折叠。","分子伴侣在不同物种间同源性很高，而非很低。"]},"cards":[{"front":"分子伴侣的结构特点是什么？举例说明。","back":"高度保守；如Hsp70广泛存在于真核、原核生物（细菌、果蝇、酵母、哺乳动物），同源性高，协助蛋白折叠","mnemonic":"Hsp70=进化保守的折叠助手","type":"组成/例证","useImg":false,"blank":"Hsp70","blank2":"协助蛋白折叠"}]},{"i":10,"sec":"第二节 蛋白质分选","title":"伴侣蛋白介导的折叠 (p60)","notes":"Chaperonin-mediated protein folding vs Chaperone-mediated protein folding：伴侣蛋白(如GroEL/GroES)形成隔离腔室帮助折叠；分子伴侣(如Hsp70)反复结合释放。\n\n【本页英文讲解】\n本页对比伴侣蛋白与分子伴侣介导的蛋白质折叠。伴侣蛋白（chaperonin，如GroEL/GroES）形成隔离腔室，将底物蛋白与胞质隔离后帮助其折叠；分子伴侣（chaperone，如Hsp70）则通过反复结合与释放底物来防止错误聚集、帮助折叠。二者均不改变最终构象信息。考点：两类折叠辅助蛋白的区别，见教材第七章。","page":60,"level":"理解","img":"assets/img/ch03/p060.jpg","anim":null,"fig":"伴侣介导的折叠：新生肽链先与伴侣结合，逐步折叠并释放；若多次尝试仍不能正确折叠，则被识别并降解(质量控制)。图强调“折叠—监控—降解”的平衡。","points":null,"check":{"q":"伴侣蛋白(chaperonin)介导的折叠与分子伴侣(chaperone)介导的折叠的主要区别是？","o":["A. 伴侣蛋白形成隔离腔室帮助折叠，分子伴侣反复结合释放","B. 两者机制完全相同","C. 分子伴侣形成隔离腔室，伴侣蛋白反复结合释放","D. 伴侣蛋白不消耗ATP，分子伴侣消耗ATP"],"a":"A","e":"伴侣蛋白(如GroEL/GroES)形成隔离腔室帮助折叠；分子伴侣(如Hsp70)通过反复结合释放帮助折叠。","oe":["伴侣蛋白形成隔离腔室供折叠，分子伴侣则反复结合与释放底物。","两者机制不同：伴侣蛋白靠隔离腔室，分子伴侣靠反复结合释放。","恰好相反，是伴侣蛋白形成隔离腔室，分子伴侣反复结合释放。","两者帮助折叠时通常都消耗ATP，该说法不成立。"]},"cards":null},{"i":11,"sec":"第二节 蛋白质分选","title":"折叠信息由序列决定 (p61)","notes":"However, the final 3-D shape of the protein is still specified by its amino acid sequence——分子伴侣帮助折叠，但最终三维构象仍由氨基酸序列决定。\n\n【本页英文讲解】\n本页强调蛋白质折叠的信息来源。分子伴侣虽能帮助折叠，但蛋白质最终的三维构象（final 3-D shape）仍由其氨基酸序列（amino acid sequence）决定，即一级结构决定高级结构。分子伴侣只提供折叠环境、防止错误聚集，不提供构象信息。考点：“序列决定构象”与分子伴侣作用的本质，见教材第七章。","page":61,"level":"理解","img":"assets/img/ch03/p061.jpg","anim":null,"fig":null,"points":["蛋白质折叠靠非共价键：氢键、离子键、疏水作用(范德华力)。","疏水核心是折叠的主要驱动力：疏水残基埋在内，亲水残基露在外。","折叠信息由一级结构(氨基酸序列)决定(Anfinsen 实验)。"],"check":{"q":"尽管有分子伴侣帮助，蛋白质最终三维构象由什么决定？","o":["A. 分子伴侣的种类","B. 氨基酸序列","C. ER腔内的pH值","D. 二硫键的数量"],"a":"B","e":"分子伴侣帮助折叠，但最终三维构象仍由蛋白质的氨基酸序列决定。","oe":["分子伴侣只辅助折叠，不能决定蛋白质的最终三维构象。","蛋白质最终三维构象由一级结构即氨基酸序列决定。","ER腔内pH不是决定蛋白质三维构象的主要因素。","二硫键是稳定构象的因素，而非决定构象的根本原因。"]},"cards":null},{"i":12,"sec":"第二节 蛋白质分选","title":"蛋白质质量监控 (p62)","notes":"The process that monitors protein quality following protein synthesis——ER的质量监控系统：只有正确折叠和装配的蛋白才能离开ER，错误折叠蛋白被滞留并降解。","page":62,"level":"掌握","img":"assets/img/ch03/p062.jpg","anim":"er_quality","fig":"内质网的质量监控系统检查蛋白是否折叠正确：正确折叠的才能进入高尔基体；错误折叠的被滞留、反复折叠或送交 ERAD 降解。图是“质检—放行/销毁”的分支。","points":null,"check":{"q":"ER蛋白质质量监控系统的作用是？","o":["A. 所有蛋白合成后均可离开ER","B. 只有正确折叠和装配的蛋白才能离开ER，错误折叠蛋白被滞留并降解","C. 错误折叠蛋白被直接运往高尔基体","D. 质量监控只发生在细胞质中"],"a":"B","e":"ER质量监控系统确保只有正确折叠和装配的蛋白才能离开ER，错误折叠蛋白被滞留并降解。","oe":["并非所有蛋白都能离开ER，只有正确折叠装配者才可离开。","只有正确折叠装配的蛋白才能离开ER，错误折叠者被滞留降解。","错误折叠蛋白被滞留并降解，不会直接运往高尔基体。","ER质量监控发生在内质网中，而非只发生在细胞质中。"]},"cards":[{"front":"ER蛋白质质量监控系统的核心规则是什么？","back":"只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被滞留并降解","mnemonic":"折对才放行，折错就销毁","type":"流程","useImg":false,"blank":"正确折叠和装配","blank2":"错误折叠蛋白"}]},{"i":13,"sec":"第二节 蛋白质分选","title":"ER驻留信号 (p63)","notes":"Bip & PDI属于内质网驻留蛋白(ER-resident protein)：具内质网驻留信号序列(ER retention signal，如KDEL)，使其被保留在ER中而不被分泌。\n\n【本页英文讲解】\n本页讲内质网驻留蛋白（ER-resident protein）与驻留信号。Bip、PDI等属于ER驻留蛋白，它们含内质网驻留信号序列（ER retention signal），如KDEL序列，使其被保留在ER中而不被分泌到细胞外。考点：KDEL等驻留/回收信号的种类与作用，见教材第八章。","page":63,"level":"掌握","img":"assets/img/ch03/p063.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"内质网驻留蛋白（如Bip、PDI）为什么不被分泌出ER？","back":"因其带有内质网驻留信号序列（如KDEL），使其被保留在ER中而不被分泌。","mnemonic":"KDEL——Keep in ER","type":"功能","useImg":false,"blank":"内质网驻留信号序列","blank2":"KDEL"}]},{"i":14,"sec":"第二节 蛋白质分选","title":"ER质量监控体制 (p64)","notes":"内质网蛋白质的质量监控体制：Only proteins that are properly folded and assembled can leave the ER——只有正确折叠和装配的蛋白才能离开ER，保证蛋白质量。","page":64,"level":"掌握","img":"assets/img/ch03/p064.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"内质网蛋白质质量监控体制的核心原则是什么？","back":"只有正确折叠和装配的蛋白才能离开ER，从而保证蛋白质质量。","mnemonic":"折好才放行，ER是质检关卡","type":"功能","useImg":false,"blank":"正确折叠和装配","blank2":"蛋白质质量"}]},{"i":15,"sec":"第二节 蛋白质分选","title":"错误折叠蛋白的降解 (p65)","notes":"The export and degradation of misfolded ER proteins：错误折叠的ER蛋白被逆向转运到胞质，经泛素-蛋白酶体系统降解(ERAD途径)。\n\n【本页英文讲解】\n本页讲错误折叠蛋白的降解（ERAD，ER-associated degradation）。错误折叠的内质网蛋白被逆向转运（retrotranslocation）到胞质，经泛素化后被泛素-蛋白酶体系统（ubiquitin-proteasome system）降解。这是内质网的质量控制机制，可防止错误蛋白堆积。考点：ERAD途径的步骤，见教材第八章。","page":65,"level":"掌握","img":"assets/img/ch03/p065.jpg","anim":"erad","fig":"错误折叠蛋白的降解途径(ERAD)：蛋白经 Sec61 易位子从 ER 腔/膜逆向转运到胞质 → N-聚糖酶切除糖链 → 泛素化 → 26S 蛋白酶体降解。图的关键是“逆向易位”和“泛素-蛋白酶体”。","points":null,"check":{"q":"错误折叠的ER蛋白主要通过下列哪条途径被降解？","o":["A. 在高尔基体中直接被水解酶降解","B. 逆向转运到胞质，经泛素-蛋白酶体系统降解","C. 通过溶酶体自噬途径降解","D. 在ER腔内由分子伴侣直接降解"],"a":"B","e":"错误折叠的ER蛋白经ERAD途径逆向转运至胞质，由泛素-蛋白酶体系统降解。","oe":["错误折叠的ER蛋白不在高尔基体被水解酶降解。","错误折叠蛋白经ERAD逆向转运到胞质，由泛素-蛋白酶体降解。","该降解主要经泛素-蛋白酶体系统，而非溶酶体自噬途径。","分子伴侣无降解活性，只能在ER腔内帮助折叠或滞留蛋白。"]},"cards":[{"front":"错误折叠的ER蛋白通过什么途径被降解？","back":"逆向转运到胞质，经泛素-蛋白酶体系统降解，即ERAD途径。","mnemonic":"折错就退货：出ER→泛素化→蛋白酶体","type":"流程","useImg":false,"blank":"ERAD途径","blank2":"泛素-蛋白酶体系统"}]},{"i":16,"sec":"第二节 蛋白质分选","title":"2004年诺贝尔化学奖 (p66)","notes":"2004年诺贝尔化学奖授予Aaron Ciechanover、Avram Hershko、Irwin Rose——发现泛素介导的蛋白质降解。\n\n【本页英文讲解】\n本页讲2004年诺贝尔化学奖。该奖授予Aaron Ciechanover、Avram Hershko与Irwin Rose，表彰他们发现泛素（ubiquitin）介导的蛋白质降解（ubiquitin-mediated）。泛素标签引导靶蛋白被蛋白酶体（proteasome）降解。此为蛋白质降解与质量控制的经典考点，与ERAD途径相联系，见教材第八章。","page":66,"level":"掌握","img":"assets/img/ch03/p066.jpg","anim":null,"fig":null,"points":null,"check":{"q":"2004年诺贝尔化学奖授予Ciechanover、Hershko和Rose，表彰他们发现了什么？","o":["A. 溶酶体的结构与功能","B. 泛素介导的蛋白质降解","C. 高尔基体的糖基化功能","D. 蛋白质的跨膜转运机制"],"a":"B","e":"2004年诺贝尔化学奖表彰三人发现泛素介导的蛋白质降解。","oe":["溶酶体结构与功能的相关研究并非2004年诺贝尔化学奖内容。","2004年诺奖授予三人，表彰其发现泛素介导的蛋白质降解。","高尔基体糖基化功能不是2004年诺贝尔化学奖的表彰内容。","蛋白质跨膜转运机制并非2004年该奖项的表彰内容。"]},"cards":[{"front":"2004年诺贝尔化学奖表彰了什么发现？获奖者是谁？","back":"发现泛素介导的蛋白质降解；获奖者为Ciechanover、Hershko、Rose。","mnemonic":"","type":"例证","useImg":false,"blank":"泛素介导的蛋白质降解","blank2":"Ciechanover、Hershko、Rose"}]},{"i":17,"sec":"第二节 蛋白质分选","title":"泛素 (p67)","notes":"泛素(ubiquitin)：由76个氨基酸组成的多肽，8.5×10³小分子球蛋白，高度保守，普遍存在于真核细胞，故名泛素。作为降解标签。","page":67,"level":"掌握","img":"assets/img/ch03/p067.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"泛素（ubiquitin）的组成与特点是什么？","back":"由76个氨基酸组成的多肽，约8.5×10³小分子球蛋白；高度保守，普遍存在于真核细胞，作为降解标签。","mnemonic":"76个氨基酸，无处不在故称泛素","type":"组成数字","useImg":false,"blank":"降解标签","blank2":"76个氨基酸"}]},{"i":18,"sec":"第二节 蛋白质分选","title":"泛素化过程 (p68)","notes":"靶蛋白泛素化过程：泛素分子共价结合到靶蛋白的赖氨酸残基上。三种酶：泛素活化酶(E1)、泛素结合酶(E2)、泛素连接酶(E3)。多聚泛素链是降解信号。","page":68,"level":"掌握","img":"assets/img/ch03/p068.jpg","anim":"ubiquitin_proteasome","fig":"泛素化级联：E1(泛素活化酶，耗 ATP)活化泛素 → E2(结合酶) → E3(连接酶)把泛素连到靶蛋白的 Lys 上；多轮反应形成多聚泛素链。泛素由 76 个氨基酸组成，多聚泛素链是降解信号。","points":null,"check":null,"cards":[{"front":"靶蛋白泛素化涉及哪三种酶？泛素结合在何处？","back":"E1泛素活化酶、E2泛素结合酶、E3泛素连接酶；泛素共价结合到靶蛋白的赖氨酸残基上，多聚泛素链为降解信号。","mnemonic":"E1活化、E2结合、E3连接；挂链即判死刑","type":"流程","useImg":false,"blank":"赖氨酸残基","blank2":"多聚泛素链"}]},{"i":19,"sec":"第二节 蛋白质分选","title":"26S蛋白酶体 (p69)","notes":"26S蛋白酶体是大型蛋白酶复合体，可将泛素化的蛋白质分解成短肽。需要待降解底物蛋白、多个泛素分子、2个ATP，经三种酶催化。","page":69,"level":"掌握","img":"assets/img/ch03/p069.jpg","anim":"proteasome","fig":"26S 蛋白酶体由 20S 催化核心(α7β7β7α7 圆筒)和两个 19S 调节帽组成。19S 帽识别多聚泛素链、去泛素化并解析叠底物，底物进入 20S 腔被切成短肽。图强调“识别—解析叠—降解”三步。","points":null,"check":null,"cards":[{"front":"26S蛋白酶体降解泛素化蛋白需要哪些条件？","back":"需待降解底物蛋白、多个泛素分子、2个ATP，经三种酶催化，将泛素化蛋白分解成短肽。","mnemonic":"底物+泛素+2ATP，三酶催化","type":"流程","useImg":false,"blank":"泛素化蛋白","blank2":"三种酶催化"}]},{"i":20,"sec":"第二节 蛋白质分选","title":"蛋白酶体 (p70-71)","notes":"蛋白酶体(proteasome)：细胞内降解蛋白质的大分子复合体，由约50种亚基组成，具有蛋白酶活性。26S蛋白酶体包含一个20S催化核心和两个19S调节帽。相对分子量2×10⁶-2.4×10⁶。","page":70,"level":"掌握","img":"assets/img/ch03/p070.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"26S蛋白酶体的结构组成是什么？","back":"由一个20S催化核心和两个19S调节帽组成；蛋白酶体由约50种亚基组成，具蛋白酶活性，相对分子量2×10⁶-2.4×10⁶。","mnemonic":"1个20S芯+2个19S帽","type":"组成数字","useImg":true,"blank":"20S催化核心","blank2":"19S调节帽"}]},{"i":21,"sec":"第二节 蛋白质分选","title":"ER功能小结 (p72)","notes":"Summary: ER功能——蛋白质合成、脂类合成。rER合成分泌性蛋白和多种膜蛋白，膜上有易位子与多肽进入内质网有关；sER合成脂类、解毒、储钙。ER还负责蛋白折叠、修饰、质量监控。","page":72,"level":"掌握","img":"assets/img/ch03/p072.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"内质网的两大合成功能分别由哪种ER承担？","back":"rER：合成分泌性蛋白和多种膜蛋白；sER：合成脂类、解毒、储钙","mnemonic":"粗网出蛋白，滑网管脂毒钙","type":"功能","useImg":false,"blank":"rER","blank2":"sER"},{"front":"内质网在蛋白质合成后还承担哪些加工任务？","back":"蛋白折叠、修饰、质量监控；膜上有易位子，与多肽进入内质网有关","mnemonic":"折叠修饰加质检，易位子来把门开","type":"功能","useImg":false,"blank":"易位子","blank2":"蛋白折叠、修饰、质量监控"}]},{"i":22,"sec":"第三节 高尔基体","title":"高尔基体形态结构 (p73)","notes":"3.2 高尔基体的形态结构与功能。高尔基体(Golgi body)又称高尔基器(Golgi apparatus)或高尔基复合体(Golgi complex)，由一系列扁平膜囊和囊泡组成。","page":73,"level":"掌握","img":"assets/img/ch03/p073.jpg","anim":null,"fig":null,"points":null,"check":{"q":"高尔基体（高尔基复合体）的形态结构主要由什么组成？","o":["A. 管状网络和核糖体","B. 一系列扁平膜囊和囊泡","C. 双层膜包被的囊泡","D. 单层膜围成的球形小体"],"a":"B","e":"高尔基体由一系列扁平膜囊和囊泡组成。","oe":["高尔基体不含核糖体，也不以管状网络为主要形态。","高尔基体由一系列扁平膜囊和囊泡组成。","高尔基体为单层膜，不存在双层膜包被的囊泡。","高尔基体由扁平膜囊堆叠而成，而非单层膜球形小体。"]},"cards":[{"front":"高尔基体的别名和基本组成是什么？","back":"又称高尔基器或高尔基复合体；由一系列扁平膜囊和囊泡组成","mnemonic":"高尔基，膜囊堆，囊泡围着转","type":"组成数字","useImg":true,"blank":"高尔基复合体","blank2":"扁平膜囊和囊泡"}]},{"i":23,"sec":"第三节 高尔基体","title":"高尔基体结构 (p74)","notes":"The structure and functions of Golgi complex：由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性。动物细胞高尔基体通常位于核附近。","page":74,"level":"掌握","img":"assets/img/ch03/p074.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于高尔基体结构极性的描述，正确的是？","o":["A. 由顺面、中间膜囊、反面组成，无极性","B. 由顺面、中间膜囊、反面组成，具极性","C. 仅由顺面和反面两个膜囊组成","D. 动物细胞高尔基体通常位于细胞膜下"],"a":"B","e":"高尔基体由顺面、中间膜囊、反面堆叠而成，具极性，动物细胞中通常位于核附近。","oe":["高尔基体具明显极性，该说法称其无极性是错误的。","高尔基体由顺面、中间膜囊、反面组成，具明显极性。","高尔基体除顺面、反面外还有中间膜囊，并非仅两层。","动物细胞高尔基体通常位于核附近，而非细胞膜下。"]},"cards":[{"front":"高尔基体由哪三个区室组成？其极性如何？","back":"顺面(cis)、中间膜囊(medial)、反面(trans)；具极性","mnemonic":"顺中反，一条龙","type":"组成数字","useImg":true,"blank":"极性","blank2":"顺面(cis)"},{"front":"动物细胞高尔基体通常位于何处？","back":"通常位于细胞核附近","mnemonic":"核边安家","type":"定位","useImg":false,"blank":"细胞核附近"}]},{"i":24,"sec":"第三节 高尔基体","title":"动植细胞高尔基体 (p75)","notes":"The Golgi apparatus in animal and plant cells：动物细胞高尔基体多为单个，植物细胞有多个分散的高尔基体(参与细胞壁合成)。\n\n【本页英文讲解】\n本页讲动物细胞与植物细胞高尔基体（Golgi apparatus）的差异。动物细胞高尔基体通常为单个或少数，位于核附近；植物细胞则含多个分散的高尔基体，参与细胞壁成分的合成与分泌。考点：动植物高尔基体在数量、分布与功能上的差异，见教材第七章内膜系统。","page":75,"level":"理解","img":"assets/img/ch03/p075.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":null},{"i":25,"sec":"第三节 高尔基体","title":"高尔基体的极性区室 (p76)","notes":"高尔基体顺面膜囊(cis Golgi)/顺面网状结构(CGN)——顺面最外侧，接收内质网合成的新物质；中间膜囊；反面膜囊(trans Golgi)/反面网状结构(TGN)——输出端，分选运往溶酶体、质膜、胞外。","page":76,"level":"掌握","img":"assets/img/ch03/p076.jpg","anim":"golgi_polarity","fig":"高尔基体的“极性”：从顺面到反面，酶的种类和膜脂组成逐渐变化。图显示不同膜囊含不同的糖基转移酶，货物依次经过并逐步加工；TGN 处有分选信号识别。","points":["高尔基体分顺面(CGN)、中间膜囊、反面(TGN)三个区。","CGN 接收 ER 来的小泡并回收 ER 驻留蛋白(KDEL/HDEL 受体)。","中间膜囊进行糖基化修饰；TGN 是分选中心，决定货物去溶酶体/分泌泡/质膜。"],"check":null,"cards":[{"front":"高尔基体顺面(CGN)和反面(TGN)的功能分别是什么？","back":"CGN：接收内质网合成的新物质；TGN：输出端，分选运往溶酶体、质膜、胞外","mnemonic":"顺面收货，反面发货","type":"功能","useImg":true,"blank":"TGN","blank2":"CGN"}]},{"i":26,"sec":"第三节 高尔基体","title":"高尔基体功能1-糖基化 (p77)","notes":"高尔基体的功能1：蛋白质的糖基化——O-连接糖基化(O-linked glycosylation)在高尔基体进行：单糖逐个加到Ser/Thr羟基上。","page":77,"level":"掌握","img":"assets/img/ch03/p077.jpg","anim":null,"fig":"高尔基体的主要功能之一是糖基化：N-连接糖链在 ER 加上核心后，到高尔基体被修剪和延伸；O-连接糖链则在高尔基体直接连到 Ser/Thr。图对比 N-与 O-糖基化的部位和糖基。","points":null,"check":{"q":"O-连接糖基化发生在哪个细胞器？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 线粒体"],"a":"B","e":"O-连接糖基化在高尔基体进行，单糖逐个加到Ser/Thr羟基上。","oe":["内质网主要进行N-连接糖基化，O-连接糖基化不在ER。","O-连接糖基化发生在高尔基体，单糖逐个加到Ser/Thr上。","溶酶体负责降解，不进行O-连接糖基化。","线粒体不参与糖基化过程，与O-连接糖基化无关。"]},"cards":[{"front":"O-连接糖基化在哪里进行？糖基加到什么氨基酸上？","back":"在高尔基体进行；单糖逐个加到Ser/Thr羟基上","mnemonic":"O连高尔基，丝苏挂糖衣","type":"定位","useImg":false,"blank":"Ser/Thr","blank2":"Ser/Thr羟基"}]},{"i":27,"sec":"第三节 高尔基体","title":"N-连接糖基化完成于高尔基体 (p78)","notes":"ER Golgi：N-连接的糖基化起始于内质网，最终完成于高尔基体。糖链在高尔基体被进一步加工、修饰。","page":78,"level":"掌握","img":"assets/img/ch03/p078.jpg","anim":null,"fig":"糖蛋白从 ER 到高尔基体的加工流程：ER 加核心 N-糖链 → 高尔基体顺面切除部分甘露糖 → 中间膜囊加 GlcNAc/半乳糖 → 反面加唾液酸。图强调糖链是“逐步加工”的。","points":null,"check":null,"cards":[{"front":"N-连接糖基化的起始和完成部位分别在哪里？","back":"起始于内质网，最终完成于高尔基体；糖链在高尔基体进一步加工修饰","mnemonic":"N糖起于ER，成于高尔基","type":"流程","useImg":false,"blank":"内质网","blank2":"高尔基体"}]},{"i":28,"sec":"第三节 高尔基体","title":"糖胺聚糖合成 (p79)","notes":"由一个或多个糖胺聚糖(glycosaminoglycan)结合到核心蛋白的丝氨酸(Ser)残基上，直接与Ser羟基结合的是N-乙酰半乳糖胺等。形成蛋白聚糖。","page":79,"level":"理解","img":"assets/img/ch03/p079.jpg","anim":null,"fig":"蛋白聚糖(proteoglycan)在高尔基体中组装：核心蛋白上连接多条糖胺聚糖(GAG)链。图显示糖链的硫酸化修饰在高尔基体完成，产物分泌到细胞外基质。","points":null,"check":null,"cards":null}],"mcq":[{"id":"ch03_mcq_13","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素由多少个氨基酸组成？","o":["A. 76个","B. 100个","C. 50个","D. 200个"],"a":"A","e":"泛素由76个氨基酸组成，8.5×10³小分子球蛋白，高度保守，普遍存在于真核细胞。","kp":"ch03_s1_17"},{"id":"ch03_mcq_14","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素化需要哪三种酶？","o":["A. E1、E2、E3","B. 激酶、磷酸酶、连接酶","C. PDI、Bip、SRP","D. 蛋白酶、核酸酶、脂肪酶"],"a":"A","e":"泛素活化酶(E1)、泛素结合酶(E2)、泛素连接酶(E3)。多聚泛素链是降解信号。","kp":"ch03_s1_18"},{"id":"ch03_mcq_15","mod":"模块二：蛋白质分选与降解","modI":1,"q":"26S蛋白酶体的结构是？","o":["A. 一个20S催化核心+两个19S调节帽","B. 仅20S","C. 仅19S","D. 单链蛋白"],"a":"A","e":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，由约50种亚基构成，降解泛素化蛋白。","kp":"ch03_s1_19"},{"id":"ch03_mcq_16","mod":"模块二：蛋白质分选与降解","modI":1,"q":"高尔基体的极性区室中,接收内质网物质的是？","o":["A. 顺面(CGN)","B. 反面(TGN)","C. 中间膜囊","D. 溶酶体"],"a":"A","e":"顺面网状结构(CGN)接收内质网新物质；反面膜囊(TGN)是输出端，分选运往溶酶体/质膜/胞外。","kp":"ch03_s1_25"},{"id":"ch03_mcq_17","mod":"模块二：蛋白质分选与降解","modI":1,"q":"O-连接糖基化发生在？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 细胞核"],"a":"B","e":"O-连接糖基化在高尔基体进行(单糖逐个加到Ser/Thr)；N-连接起始于ER、完成于高尔基体。","kp":"ch03_s1_2"},{"id":"ch03_mcq_18","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体内部维持酸性环境(pH≈5)依靠？","o":["A. H+泵(质子泵)","B. Na+/K+泵","C. Ca2+泵","D. 水通道"],"a":"A","e":"溶酶体膜上的H+-pumps将H+泵入，维持内部pH≈5，使酸性水解酶活性最高。","kp":"ch03_s1_19"},{"id":"ch03_mcq_19","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体酶的靶向分选信号是？","o":["A. 6-磷酸甘露糖(M6P)","B. KDEL","C. NLS","D. 信号肽"],"a":"A","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别分选到溶酶体。","kp":"ch03_s1_3"},{"id":"ch03_mcq_20","mod":"模块二：蛋白质分选与降解","modI":1,"q":"细胞自噬(autophagy)是指？","o":["A. 吞噬外源细菌","B. 降解细胞自身老化废弃的细胞器和大分子","C. 分泌蛋白","D. 细胞分裂"],"a":"B","e":"自噬是细胞在自噬相关基因调控下，对自身受损或需淘汰更新的物质(线粒体、过氧化物酶体等)进行降解再利用。","kp":"ch03_s1_24"},{"id":"ch03_mcq_21","mod":"模块二：蛋白质分选与降解","modI":1,"q":"N-连接糖基化连接的氨基酸残基是？","o":["A. 天冬酰胺(Asn)","B. 丝氨酸(Ser)","C. 苏氨酸(Thr)","D. 赖氨酸(Lys)"],"a":"A","e":"N-连接糖基化连接Asn(序列Asn-X-Ser/Thr)；O-连接连接Ser/Thr羟基。","kp":"ch03_s1_2"},{"id":"ch03_mcq_22","mod":"模块二：蛋白质分选与降解","modI":1,"q":"膜脂(甘油磷脂和胆固醇)主要在何处合成？","o":["A. 光面内质网","B. 高尔基体","C. 线粒体","D. 细胞核"],"a":"A","e":"sER合成构成细胞所需的绝大多数膜脂(甘油磷脂和胆固醇)，再运往其他膜。","kp":"ch03_s1_28"},{"id":"ch03_mcq_23","mod":"模块二：蛋白质分选与降解","modI":1,"q":"微粒体(microsome)是？","o":["A. 完整线粒体","B. 破碎内质网自我融合形成的囊泡","C. 溶酶体","D. 高尔基体"],"a":"B","e":"微粒体是体外实验中细胞匀浆和差速离心得到的、由分离的内质网自我融合形成的球形囊泡，是研究ER的模型。","kp":"ch03_s1_20"},{"id":"ch03_mcq_24","mod":"模块二：蛋白质分选与降解","modI":1,"q":"sER的储钙功能依靠？","o":["A. Ca2+-ATPase将钙泵入ER","B. 钙通道外流","C. Na+/K+泵","D. 质子泵"],"a":"A","e":"ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER储存，使ER腔钙浓度高达3mM，参与信号传递。","kp":"ch03_s1_21"},{"id":"ch03_mcq_25","mod":"模块二：蛋白质分选与降解","modI":1,"q":"ER质量监控的意义是？","o":["A. 所有蛋白都能离开ER","B. 只有正确折叠和装配的蛋白才能离开ER","C. 错误折叠蛋白直接分泌","D. 阻止所有蛋白合成"],"a":"B","e":"ER质量监控：只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被逆向转运至胞质经泛素-蛋白酶体降解(ERAD)。","kp":"ch03_s1_14"}],"judge":[{"id":"ch03_judge_5","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个7S RNA组成。","a":"对","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，识别信号肽并使翻译暂停。","kp":"ch03_s1_13"},{"id":"ch03_judge_6","modI":1,"q":"N-连接糖基化起始于内质网，O-连接糖基化发生在高尔基体。","a":"对","e":"N-连接起始于rER、结合Asn；O-连接在高尔基体进行、结合Ser/Thr。","kp":"ch03_s1_27"},{"id":"ch03_judge_7","modI":1,"q":"泛素由76个氨基酸组成，泛素化需要E1、E2、E3三种酶。","a":"对","e":"泛素由76个氨基酸组成；E1活化酶、E2结合酶、E3连接酶共同完成泛素化。","kp":"ch03_s1_18"},{"id":"ch03_judge_8","modI":1,"q":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，降解泛素化蛋白。","a":"对","e":"26S蛋白酶体=20S催化核心+两个19S调节帽，识别多聚泛素链并降解蛋白。","kp":"ch03_s1_20"}],"fill":[{"id":"ch03_fill_4","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个________组成,识别新生肽的________并使翻译暂停。","a":"7S RNA,信号肽","kp":"ch03_s1_4"},{"id":"ch03_fill_5","modI":1,"q":"N-连接糖基化连接________残基,起始于________；O-连接糖基化连接________残基,发生在________。","a":"天冬酰胺(Asn),内质网,丝氨酸/苏氨酸(Ser/Thr),高尔基体","kp":"ch03_s1_2"},{"id":"ch03_fill_6","modI":1,"q":"ER驻留蛋白的驻留信号是________；溶酶体酶的分选信号是________。","a":"KDEL序列,6-磷酸甘露糖(M6P)","kp":"ch03_s1_13"},{"id":"ch03_fill_7","modI":1,"q":"泛素由________个氨基酸组成；泛素化需要________、________、________三种酶。","a":"76,E1(活化酶),E2(结合酶),E3(连接酶)","kp":"ch03_s1_18"},{"id":"ch03_fill_8","modI":1,"q":"26S蛋白酶体由20S________和两个19S________组成,降解泛素化的蛋白质。","a":"催化核心,调节帽","kp":"ch03_s1_19"}],"short":[{"id":"ch03_short_1","modI":1,"q":"简述信号肽假说及分泌蛋白共翻译转移的过程。","a":"信号肽假说(1975年提出)：\n\n【过程】\n①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽(signal peptide)伸出；\n②信号识别颗粒(SRP，6种多肽+7S RNA)识别并结合信号肽及核糖体大亚基→翻译暂停；\n③SRP-核糖体复合物结合内质网膜上的SRP受体(停泊蛋白DP)；\n④核糖体附着到rER膜上，SRP释放，翻译恢复；\n⑤肽链边延伸边穿过易位子(translocon，核心Sec61)进入ER腔；\n⑥信号肽被信号肽酶切除，蛋白在ER腔折叠、修饰。\n\n【证据】1972年Milstein发现细胞内的免疫球蛋白N端比分泌到胞外的多一截(信号肽)。\n\n【意义】解释了分泌蛋白、膜蛋白如何定向进入ER。","kp":"ch03_s1_13"},{"id":"ch03_short_3","modI":1,"q":"简述蛋白质糖基化的类型、部位和生物学功能。","a":"蛋白质糖基化类型：\n\n【N-连接糖基化】\n• 合成部位：起始于粗面内质网；\n• 结合残基：天冬酰胺(Asn)，序列Asn-X-Ser/Thr；\n• 方式：来自同一个寡糖前体(连在磷酸多萜醇上)整体转移。\n\n【O-连接糖基化】\n• 合成部位：高尔基体；\n• 结合残基：丝氨酸/苏氨酸(Ser/Thr)羟基；\n• 方式：一个个单糖加上去。\n\n【生物学功能】\n①促进蛋白质折叠(如抗体IgG、质膜糖蛋白血凝素)；\n②影响蛋白稳定性、半衰期和运输；\n③参与细胞识别与免疫(如血型抗原)；\n④溶酶体酶的M6P分选信号；\n⑤负责糖链合成加工的酶均为管家基因编码。","kp":"ch03_s1_3"},{"id":"ch03_short_4","modI":1,"q":"简述泛素-蛋白酶体系统降解蛋白质的机制。","a":"泛素-蛋白酶体系统(2004年诺贝尔化学奖)：\n\n【泛素】\n由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞。\n\n【泛素化过程】\n①E1(泛素活化酶)消耗ATP激活泛素；\n②E2(泛素结合酶)接受活化泛素；\n③E3(泛素连接酶)识别靶蛋白并将泛素转移至靶蛋白的赖氨酸残基；\n④多轮循环形成多聚泛素链(降解信号)。\n\n【蛋白酶体降解】\n26S蛋白酶体=20S催化核心+两个19S调节帽，由约50种亚基组成。\n①19S帽识别多聚泛素链；\n②去折叠、去泛素化；\n③20S核心催化降解为短肽；\n④泛素可回收再利用。\n\n【意义】\n调控细胞周期、凋亡、信号转导等；错误折叠蛋白(ERAD)也经此降解。","kp":"ch03_s1_20"},{"id":"ch03_short_5","modI":1,"q":"比较N-连接和O-连接糖基化。","a":"N-连接 vs O-连接糖基化：\n\n| 特征 | N-连接 | O-连接 |\n|---|---|---|\n| 合成部位 | 起始于粗面内质网(完成于高尔基体) | 高尔基体 |\n| 合成方式 | 来自同一个寡糖前体整体转移 | 一个个单糖加上去 |\n| 结合残基 | 天冬酰胺Asn(Asn-X-Ser/Thr) | 丝氨酸/苏氨酸Ser/Thr羟基 |\n| 前体 | 磷酸多萜醇(dolichol)连接的寡糖 | 单糖核苷酸 |\n\n【共同点】\n①都属于蛋白质翻译后修饰；\n②都由糖基转移酶催化；\n③糖链都位于细胞外侧/ER腔侧。\n\n【生物学功能】\n促进折叠、影响稳定性与半衰期、参与细胞识别与免疫、M6P分选信号等。","kp":"ch03_s1_2"}],"calc":[],"term":[{"id":"ch03_term_5","modI":1,"term":"信号肽(Signal Peptide)","def":"①位于分泌蛋白N端、引导蛋白进入ER的短肽序列（定义）。②特点：通常位于N端，完成使命后被信号肽酶切除（特点）。③机制：被SRP识别→核糖体停泊到ER膜→共翻译转移（机制）。④证据：1972年Milstein发现细胞内免疫球蛋白N端比胞外多一截（证据）。","kps":"踩分点:①定义(1分)②特点(1分)③机制(1分)④证据(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_6","modI":1,"term":"信号识别颗粒(SRP)","def":"①由6种多肽和1个300核苷酸(7S)RNA组成的核糖核蛋白复合物（定义）。②功能：既结合新生肽信号序列，又结合核糖体大亚基，使翻译暂停（功能）。③作用：将核糖体引导到ER膜的SRP受体(停泊蛋白DP)上（作用）。","kps":"踩分点:①组成(1分)②功能(2分)③与SRP受体(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_9","modI":1,"term":"泛素(Ubiquitin)","def":"①由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞（定义）。②功能：作为蛋白质降解的标签，共价结合到靶蛋白赖氨酸残基上（功能）。③泛素化需E1/E2/E3三种酶，多聚泛素链是降解信号（机制）。④发现获2004年诺贝尔化学奖（意义）。","kps":"踩分点:①定义(1分)②功能(1分)③三种酶(1分)④诺贝尔奖(1分)","kp":"ch03_s1_17"},{"id":"ch03_term_10","modI":1,"term":"蛋白酶体(Proteasome)","def":"①细胞内降解蛋白质的大分子复合体，由约50种亚基组成（定义）。②结构：26S蛋白酶体=20S催化核心+两个19S调节帽（结构）。③功能：识别多聚泛素链，将泛素化蛋白降解为短肽（功能）。","kps":"踩分点:①定义(1分)②结构(2分)③功能(1分)","kp":"ch03_s1_20"},{"id":"ch03_term_16","modI":1,"term":"ER驻留信号(KDEL)","def":"①内质网驻留蛋白C端的一段回收信号序列(KDEL)（定义）。②功能：使Bip、PDI等驻留蛋白被保留在ER中而不被分泌（功能）。③机制：逃逸到高尔基体的驻留蛋白经KDEL受体识别，由COPI小泡回收回ER（机制）。","kps":"踩分点:①定义(1分)②功能(1分)③回收机制(2分)","kp":"ch03_s1_13"}]},{"i":2,"name":"模块三：高尔基体与溶酶体","slides":[{"i":0,"sec":"第三节 高尔基体","title":"高尔基体功能2-分选枢纽 (p80)","notes":"高尔基体功能2：蛋白质加工、修饰、分类装载运输的分选站(枢纽作用)。通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖蛋白的信号序列和受体之间的相互作用。","page":80,"level":"掌握","img":"assets/img/ch03/p080.jpg","anim":null,"fig":"TGN 是细胞内蛋白质分选的“交通枢纽”：根据货物携带的信号，把它们分装到不同小泡——去溶酶体(M6P 信号)、去分泌泡(调节性分泌)、去质膜(组成性分泌)。图是分选的“多岔路口”。","points":null,"check":null,"cards":[{"front":"高尔基体作为分选枢纽的功能是什么？","back":"蛋白质加工、修饰、分类装载运输；通过膜泡运往溶酶体、质膜或胞外","mnemonic":"加工分类再装车，信号受体来配对","type":"功能","useImg":false,"blank":"分类装载运输","blank2":"溶酶体"}]},{"i":1,"sec":"第四节 溶酶体","title":"溶酶体概述 (p81)","notes":"3.3 溶酶体(Lysosomes)：存在于几乎所有动物细胞中，植物细胞对应液泡。单层膜，内含多种酸性水解酶类(酶活性最适pH为5左右)。是细胞的'消化系统'。","page":81,"level":"掌握","img":"assets/img/ch03/p081.jpg","anim":null,"fig":null,"points":null,"check":null,"cards":[{"front":"溶酶体的结构特点和酶的最适pH是多少？","back":"单层膜；含多种酸性水解酶，最适pH约5","mnemonic":"单膜酸酶pH五","type":"组成数字","useImg":false,"blank":"酸性水解酶","blank2":"单层膜"},{"front":"溶酶体存在于哪些细胞？植物细胞对应什么结构？","back":"几乎存在于所有动物细胞；植物细胞对应液泡","mnemonic":"动物溶酶体，植物用液泡","type":"对比","useImg":false,"blank":"液泡","blank2":"动物细胞"}]},{"i":2,"sec":"第四节 溶酶体","title":"溶酶体的异质性 (p82)","notes":"溶酶体是异质性细胞器：不同来源、不同发育阶段的溶酶体形态大小、所含水解酶类都可能不同。根据生理阶段分为：初级溶酶体(刚形成)、次级溶酶体(正在消化)、残余小体。","page":82,"level":"掌握","img":"assets/img/ch03/p082.jpg","anim":null,"fig":"溶酶体的三种状态：初级溶酶体(新形成、未消化)→次级溶酶体(正在消化胞吞物或自噬物)→残余体(消化后残渣)。图强调溶酶体是“动态变化”的细胞器。","points":["溶酶体是异质性细胞器：不同来源/发育阶段形态大小、酶种类不同。","初级溶酶体：只含酸性水解酶，无消化作用。","次级溶酶体：正在消化(含底物)；分自噬溶酶体、异噬溶酶体。"],"check":{"q":"根据生理阶段，溶酶体可分为哪几类？","o":["A. 初级溶酶体、次级溶酶体、残余小体","B. 顺面溶酶体、中间溶酶体、反面溶酶体","C. 早期内体、晚期内体、自噬体","D. 分泌溶酶体、储存溶酶体、消化溶酶体"],"a":"A","e":"溶酶体具异质性，按生理阶段分为初级溶酶体、次级溶酶体和残余小体。","oe":["按生理阶段溶酶体分为初级溶酶体、次级溶酶体和残余小体。","顺面、中间、反面是高尔基体的分区，不是溶酶体分类。","早期内体、晚期内体、自噬体是内体或自噬结构，非溶酶体分类。","分泌、储存、消化溶酶体不是按生理阶段的分类法。"]},"cards":[{"front":"溶酶体按生理阶段分为哪三类？","back":"初级溶酶体（刚形成）；次级溶酶体（正在消化）；残余小体","mnemonic":"初生→消化→残渣","type":"流程","useImg":false,"blank":"初级溶酶体","blank2":"次级溶酶体"},{"front":"为什么说溶酶体是异质性细胞器？","back":"来源、发育阶段不同，其形态大小和所含水解酶类均可不同","mnemonic":"","type":"定义","useImg":false,"blank":"水解酶类","blank2":"发育阶段"}]},{"i":3,"sec":"第四节 溶酶体","title":"溶酶体电镜图 (p83)","notes":"小鼠膀胱上皮细胞中的溶酶体——电镜显示其单层膜包围的、含水解酶的囊泡结构。","page":83,"level":"理解","img":"assets/img/ch03/p083.jpg","anim":null,"fig":null,"points":null,"check":{"q":"电镜显示溶酶体的典型结构特征是？","o":["A. 双层膜包围的囊泡","B. 单层膜包围的、含水解酶的囊泡","C. 无膜包被的酶聚集体","D. 由扁平膜囊堆叠而成"],"a":"B","e":"溶酶体为单层膜包围、含水解酶的囊泡结构。","oe":["溶酶体是单层膜囊泡，不是双层膜包围的囊泡。","溶酶体为单层膜包围、内含多种水解酶的囊泡结构。","溶酶体有膜包被，并非无膜的酶聚集体。","由扁平膜囊堆叠而成是高尔基体的特征，不是溶酶体。"]},"cards":null},{"i":4,"sec":"第四节 溶酶体","title":"溶酶体的消化类型 (p84)","notes":"溶酶体的消化类型：phagocytosis(吞噬)——细菌、微小生物、衰老红细胞；autophagy(自噬)——细胞本身老化废弃的部分，如线粒体、过氧化物酶体、生物大分子。","page":84,"level":"掌握","img":"assets/img/ch03/p084.jpg","anim":"lysosome_formation","fig":"溶酶体的形成有两条途径：①内体途径——胞吞物经早期/晚期内体与溶酶体融合；②自噬途径——细胞内结构被自噬体包裹后与溶酶体融合。图显示两条来源最终都汇入溶酶体。","points":null,"check":null,"cards":[{"front":"溶酶体的两种消化类型及其对象分别是什么？","back":"吞噬：细菌、微小生物、衰老红细胞；自噬：老化细胞器（线粒体、过氧化物酶体）、生物大分子","mnemonic":"外来叫吞噬，内耗叫自噬","type":"对比","useImg":false,"blank":"自噬","blank2":"吞噬"}]},{"i":5,"sec":"第四节 溶酶体","title":"溶酶体的特点 (p85)","notes":"特点② Lysosomes contain plenty of acid hydrolases(酸性水解酶)，可消化各种生物大分子。酶在酸性环境(pH≈5)下活性最高。\n\n【本页英文讲解】\n本页讲溶酶体（lysosome）的特点。溶酶体含有大量酸性水解酶（acid hydrolases），可消化蛋白质、核酸、多糖、脂类等各种生物大分子；这些酶在酸性环境（pH≈5）下活性最高，而溶酶体膜上的质子泵维持腔内酸性。考点：溶酶体酶的最适pH及其与细胞质（pH≈7.2）的差异，见教材第七章。","page":85,"level":"掌握","img":"assets/img/ch03/p085.jpg","anim":null,"fig":"溶酶体含酸性水解酶(如酸性磷酸酶)，最适 pH≈5。图显示溶酶体膜上的 H⁺ 泵维持腔内酸性；酸性磷酸酶是溶酶体的标志酶。水解酶可分解蛋白质、核酸、脂类、糖类等。","points":null,"check":null,"cards":[{"front":"溶酶体为什么能消化各种生物大分子？","back":"含大量酸性水解酶；在酸性环境（pH≈5）下活性最高","mnemonic":"酸酶酸中才干活","type":"功能","useImg":false,"blank":"酸性水解酶","blank2":"酸性环境"}]},{"i":6,"sec":"第四节 溶酶体","title":"溶酶体膜的质子泵 (p86)","notes":"③溶酶体膜：H+-pumps(质子泵)将H+泵入溶酶体，维持内部质子浓度(pH≈5)；膜蛋白高度糖基化保护膜不被自身水解酶消化。","page":86,"level":"掌握","img":"assets/img/ch03/p086.jpg","anim":"lysosome_proton_pump","fig":null,"points":null,"check":{"q":"溶酶体膜维持内部酸性环境（pH≈5）主要依靠什么？","o":["A. Na+-K+ ATP酶","B. 质子泵将H+泵入溶酶体","C. 钙泵将Ca2+泵出","D. 水通道蛋白"],"a":"B","e":"溶酶体膜上的H+泵将H+泵入，维持内部质子浓度使pH≈5。","oe":["Na+-K+ ATP酶维持细胞内外离子梯度，不负责溶酶体酸化。","溶酶体膜上的质子泵将H+泵入，维持腔内pH约5。","钙泵负责钙离子转运，与溶酶体酸性环境维持无关。","水通道蛋白只转运水，不参与溶酶体酸化。"]},"cards":[{"front":"溶酶体膜如何维持内部酸性并自我保护？","back":"H+泵泵入H+维持pH≈5；膜蛋白高度糖基化，防止被自身水解酶消化","mnemonic":"泵酸护糖衣","type":"组成数字","useImg":true,"blank":"H+泵","blank2":"膜蛋白高度糖基化"}]},{"i":7,"sec":"第四节 溶酶体","title":"溶酶体的功能 (p87)","notes":"The Functions of Lysosomes——消化：'清道夫'，清除无用的生物大分子、衰老的细胞器、凋亡细胞及吞噬的营养大分子颗粒等。","page":87,"level":"掌握","img":"assets/img/ch03/p087.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于溶酶体功能的描述，下列哪项最符合其作为细胞'清道夫'的角色？","o":["A. 合成并分泌消化酶到细胞外","B. 清除无用的生物大分子、衰老的细胞器及凋亡细胞等","C. 主要负责蛋白质的泛素化降解","D. 将营养物质合成并储存于细胞内"],"a":"B","e":"溶酶体作为'清道夫'，可清除无用的生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子颗粒等。","oe":["溶酶体在细胞内消化，不合成并分泌消化酶到细胞外。","溶酶体可清除无用生物大分子、衰老细胞器及凋亡细胞。","泛素化降解由蛋白酶体负责，不是溶酶体的主要角色。","溶酶体负责分解而非合成储存营养物质。"]},"cards":[{"front":"溶酶体作为'清道夫'主要清除哪些物质？","back":"无用生物大分子；衰老细胞器；凋亡细胞；吞噬的营养大分子颗粒","mnemonic":"废料、旧件、死细胞、外来货","type":"功能","useImg":false,"blank":"衰老细胞器","blank2":"凋亡细胞"}]},{"i":8,"sec":"第四节 溶酶体","title":"中性粒细胞吞噬 (p88)","notes":"A phagocytic white blood cell(a neutrophil) ingesting a bacterium——中性粒细胞吞噬细菌，溶酶体参与杀菌消化。\n\n【本页英文讲解】\n本页讲中性粒细胞（neutrophil）的吞噬作用。吞噬性白细胞（中性粒细胞）摄入细菌（ingesting a bacterium），形成吞噬体后与溶酶体融合，由溶酶体酶将细菌杀死并消化。这体现了溶酶体的消化与防御功能。考点：吞噬（phagocytosis）过程及溶酶体在其中的作用，见教材第七章。","page":88,"level":"理解","img":"assets/img/ch03/p088.jpg","anim":null,"fig":null,"points":null,"check":{"q":"中性粒细胞吞噬细菌后，主要依靠什么结构完成对细菌的杀菌消化？","o":["A. 线粒体","B. 高尔基体","C. 溶酶体","D. 内质网"],"a":"C","e":"中性粒细胞吞噬细菌后，由溶酶体参与杀菌和消化过程。","oe":["线粒体主要供能，不直接完成对细菌的杀菌消化。","高尔基体负责加工分选，不直接消化吞噬的细菌。","中性粒细胞吞噬细菌后由溶酶体完成杀菌和消化。","内质网负责合成加工，不直接参与杀菌消化。"]},"cards":null},{"i":9,"sec":"第四节 溶酶体","title":"溶酶体与蛋白存量调节 (p89)","notes":"细胞处于不同分化阶段、不同生理状态下需要特定蛋白维持生命活动。真核细胞对蛋白质存量的调节，除泛素降解途径外，溶酶体是另一个重要途径。","page":89,"level":"掌握","img":"assets/img/ch03/p089.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于真核细胞蛋白质存量调节的途径，下列叙述正确的是？","o":["A. 仅依靠泛素降解途径","B. 仅依靠溶酶体途径","C. 除泛素降解途径外，溶酶体也是重要途径","D. 与溶酶体无关，仅由蛋白酶体完成"],"a":"C","e":"真核细胞对蛋白质存量的调节除泛素降解途径外，溶酶体是另一个重要途径。","oe":["蛋白质存量调节并非仅依靠泛素降解途径。","也非仅依靠溶酶体途径，两个系统均参与调节。","除泛素降解途径外，溶酶体也是蛋白质存量调节的重要途径。","溶酶体参与蛋白质降解，不能说与溶酶体无关。"]},"cards":[{"front":"真核细胞调节蛋白质存量的两条降解途径是什么？","back":"泛素降解途径；溶酶体途径","mnemonic":"泛素+溶酶体，双保险","type":"对比","useImg":false,"blank":"泛素降解途径","blank2":"溶酶体途径"}]},{"i":10,"sec":"第四节 溶酶体","title":"细胞自噬 (p90)","notes":"细胞自噬与生物大分子、细胞器的降解：自噬相关基因调控下，对细胞内受损或需要淘汰更新的物质进行再利用。在自噬信号刺激下形成自噬体，与溶酶体融合降解。","page":90,"level":"掌握","img":"assets/img/ch03/p090.jpg","anim":"autophagy","fig":null,"points":null,"check":{"q":"关于细胞自噬的叙述，下列哪项正确？","o":["A. 自噬体直接与细胞膜融合将物质排出胞外","B. 自噬相关基因调控下形成自噬体，与溶酶体融合降解物质","C. 自噬仅降解生物大分子，不涉及细胞器","D. 自噬过程不依赖溶酶体"],"a":"B","e":"在自噬信号刺激下形成自噬体，自噬体与溶酶体融合后降解受损或需淘汰更新的物质。","oe":["自噬体与溶酶体融合降解，并非与细胞膜融合排出胞外。","自噬相关基因调控下形成自噬体，与溶酶体融合降解物质。","自噬不仅降解大分子，也降解细胞器等结构。","自噬依赖溶酶体提供水解酶才能完成降解。"]},"cards":[{"front":"细胞自噬的基本过程是什么？","back":"自噬信号刺激下形成自噬体；自噬体与溶酶体融合降解；受自噬相关基因调控，实现物质再利用","mnemonic":"包起来→送溶酶体→回收","type":"流程","useImg":true,"blank":"自噬体","blank2":"溶酶体"}]},{"i":11,"sec":"第四节 溶酶体","title":"M6P分选信号 (p91)","notes":"Mannose 6-phosphate(6-磷酸甘露糖,M6P)残基把蛋白靶向到溶酶体：溶酶体酶在rER合成并N-糖基化后，在高尔基体CGN被磷酸化形成M6P标志，被M6P受体识别并分选到溶酶体。","page":91,"level":"掌握","img":"assets/img/ch03/p091.jpg","anim":"m6p_sorting","fig":null,"points":null,"check":null,"cards":[{"front":"M6P标志如何把溶酶体酶靶向到溶酶体？","back":"酶在rER合成并N-糖基化；在高尔基体CGN磷酸化形成M6P；被M6P受体识别并分选至溶酶体","mnemonic":"合成→糖基化→打M6P标签→受体签收","type":"流程","useImg":true,"blank":"M6P受体","blank2":"高尔基体"}]},{"i":12,"sec":"第四节 溶酶体","title":"M6P分选机制 (p92)","notes":"溶酶体蛋白除其特有的分选信号斑(signal patch)外，还有M6P标志。Phosphorylation of mannose residues——甘露糖残基磷酸化形成M6P。\n\n【本页英文讲解】\n本页讲溶酶体酶的分选机制与M6P标志。溶酶体蛋白除具有特有的分选信号斑（signal patch）外，还带有甘露糖-6-磷酸（M6P，mannose-6-phosphate）标志，由甘露糖残基磷酸化（phosphorylation）形成。M6P标志被高尔基体膜的M6P受体识别，从而分选运送至溶酶体。考点：M6P途径，见教材第八章。","page":92,"level":"掌握","img":"assets/img/ch03/p092.jpg","anim":null,"fig":"溶酶体酶在 ER 进行 N-糖基化后，在高尔基体顺面由 GlcNAc 磷酸转移酶识别其三维“信号斑”，把甘露糖磷酸化成 M6P。图强调识别的是构象信号斑，而非线性序列。","points":null,"check":{"q":"溶酶体蛋白除具有特有的分选信号斑外，还具有的标志是？","o":["A. 泛素标志","B. M6P标志","C. 信号肽","D. 磷酸化酪氨酸标志"],"a":"B","e":"溶酶体蛋白除分选信号斑外，还有M6P标志，由甘露糖残基磷酸化形成。","oe":["泛素化是蛋白质降解信号，不是溶酶体蛋白的分选标志。","溶酶体蛋白除分选信号斑外，还具有M6P标志。","信号肽引导蛋白进入ER，不是溶酶体蛋白的特有标志。","磷酸化酪氨酸是信号转导标志，与溶酶体蛋白标志无关。"]},"cards":[{"front":"溶酶体蛋白分选除信号斑外还有什么标志？","back":"M6P标志；由甘露糖残基磷酸化形成。","mnemonic":"溶酶体酶贴M6P邮票，寄往溶酶体。","type":"定义","useImg":false,"blank":"M6P标志","blank2":"甘露糖残基磷酸化"}]},{"i":13,"sec":"第四节 溶酶体","title":"M6P途径 (p93)","notes":"依赖于M6P途径的溶酶体产生：溶酶体酶在rER合成/N-连接糖基化修饰→Golgi(CTN)由N-乙酰葡萄糖胺磷酸转移酶催化加上M6P→M6P受体识别→包装入运输小泡→运往溶酶体。","page":93,"level":"掌握","img":"assets/img/ch03/p093.jpg","anim":null,"fig":"依赖 M6P 途径的溶酶体酶产生：ER 加 N-糖链 → 高尔基体加 M6P 标志 → M6P 受体在 TGN 结合 → 衣被小泡运到内体 → 酸性环境下受体释放酶 → 酶去磷酸化成成熟溶酶体酶，受体回收。","points":null,"check":{"q":"在M6P途径中，催化溶酶体酶加上M6P的酶及场所是？","o":["A. rER中的N-乙酰葡萄糖胺磷酸转移酶","B. Golgi(CTN)中的N-乙酰葡萄糖胺磷酸转移酶","C. 溶酶体中的磷酸酶","D. 细胞质中的激酶"],"a":"B","e":"溶酶体酶在rER合成并N-连接糖基化后，在Golgi(CTN)由N-乙酰葡萄糖胺磷酸转移酶催化加上M6P。","oe":["rER只完成N-连接糖基化，加M6P不在rER进行。","在Golgi(CTN)由N-乙酰葡萄糖胺磷酸转移酶催化加上M6P。","溶酶体中的磷酸酶不负责添加M6P标志。","细胞质中的激酶不参与M6P标志的形成。"]},"cards":[{"front":"M6P途径产生溶酶体酶的主要步骤是什么？","back":"rER合成并N-连接糖基化；Golgi中N-乙酰葡萄糖胺磷酸转移酶催化加M6P；M6P受体识别；包装入运输小泡；运往溶酶体。","mnemonic":"合成→加签→识别→打包→送达。","type":"流程","useImg":true,"blank":"N-乙酰葡萄糖胺磷酸转移酶","blank2":"M6P受体"},{"front":"M6P标志在哪个细胞器、由什么酶催化形成？","back":"高尔基体；N-乙酰葡萄糖胺磷酸转移酶催化。","mnemonic":"高尔基贴签，磷酸转移酶执笔。","type":"定位","useImg":false,"blank":"高尔基体","blank2":"N-乙酰葡萄糖胺磷酸转移酶"}]},{"i":14,"sec":"第四节 溶酶体","title":"溶酶体酶分选多样化 (p94)","notes":"溶酶体酶分选途径多样化：依赖于M6P的分选途径效率不高，部分带M6P标志的溶酶体酶会通过运输小泡直接分泌到胞外，再由细胞重新摄取(旁路)。","page":94,"level":"理解","img":"assets/img/ch03/p094.jpg","anim":null,"fig":"部分溶酶体酶不依赖 M6P 分选，而是靠其他信号或与其他蛋白结合被运到溶酶体。图说明分选途径的多样性：M6P 是主要途径但非唯一。","points":null,"check":{"q":"关于溶酶体酶分选途径多样化的叙述，正确的是？","o":["A. M6P分选途径效率极高，无酶分泌到胞外","B. 部分带M6P标志的酶可分泌到胞外，再由细胞重新摄取","C. 溶酶体酶只能通过M6P途径分选","D. 分泌到胞外的溶酶体酶不能再被细胞摄取"],"a":"B","e":"M6P分选途径效率不高，部分带M6P标志的溶酶体酶可通过运输小泡分泌到胞外，再由细胞重新摄取（旁路）。","oe":["M6P分选途径效率并不高，会有酶被分泌到胞外。","部分带M6P标志的酶可分泌到胞外，再由细胞重新摄取。","溶酶体酶并非只能经M6P途径分选，还存在其他途径。","分泌到胞外的溶酶体酶可被细胞重新摄取，该说法错误。"]},"cards":null},{"i":15,"sec":"第四节 溶酶体","title":"M6P分选途径图 (p95)","notes":"溶酶体酶的M6P分选途径示意图：展示从rER合成、Golgi修饰加M6P、M6P受体分选、运输小泡、到溶酶体的完整路径。","page":95,"level":"理解","img":"assets/img/ch03/p095.jpg","anim":null,"fig":"综合图：溶酶体酶在 ER 合成并糖基化，在高尔基体获得 M6P，由 M6P 受体在 TGN 分选，经内体转运到溶酶体，受体可循环使用。图是 M6P 分选途径的完整流程图。","points":null,"check":{"q":"在溶酶体酶的M6P分选途径中，M6P受体识别M6P后，酶被包装入什么结构运往溶酶体？","o":["A. 核糖体","B. 运输小泡","C. 自噬体","D. 过氧化物酶体"],"a":"B","e":"M6P受体识别M6P后，将溶酶体酶包装入运输小泡，运往溶酶体。","oe":["核糖体是合成蛋白质的场所，不负责运输溶酶体酶。","M6P受体识别M6P后，将酶包装入运输小泡运往溶酶体。","自噬体运送待降解物质，不运输溶酶体酶。","过氧化物酶体是独立细胞器，与溶酶体酶运输无关。"]},"cards":null},{"i":16,"sec":"第五节 液泡","title":"植物液泡 (p96)","notes":"Plant cell vacuoles植物液泡：Plant vacuoles have some of the same acid hydrolases——植物液泡含一些与溶酶体相同的酸性水解酶，功能类似溶酶体；还参与储存、膨压维持、色素积累。","page":96,"level":"掌握","img":"assets/img/ch03/p096.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于植物液泡的叙述，下列哪项最符合其功能特点？","o":["A. 只储存水分，不含任何水解酶","B. 含与溶酶体相同的酸性水解酶，兼具储存、维持膨压和积累色素等功能","C. 主要功能是合成ATP，为细胞供能","D. 是植物细胞特有的光合作用场所"],"a":"B","e":"植物液泡含与溶酶体相同的酸性水解酶，功能类似溶酶体，同时参与储存、膨压维持和色素积累。","oe":["液泡含酸性水解酶，并非只储存水分而不含酶。","液泡含与溶酶体相同的酸性水解酶，兼具储存、膨压和色素积累功能。","液泡不合成ATP，能量主要由线粒体和叶绿体提供。","光合作用在叶绿体进行，液泡不是光合作用场所。"]},"cards":[{"front":"植物液泡与溶酶体有何相似之处？","back":"含相同的酸性水解酶；功能类似溶酶体。","mnemonic":"植物液泡是植物版溶酶体。","type":"对比","useImg":false,"blank":"酸性水解酶","blank2":"溶酶体"},{"front":"植物液泡除类似溶酶体功能外还参与哪些功能？","back":"储存；维持膨压；色素积累。","mnemonic":"存、压、色三件事。","type":"功能","useImg":false,"blank":"维持膨压","blank2":"色素积累"}]}],"mcq":[],"judge":[{"id":"ch03_judge_9","modI":2,"q":"溶酶体内部呈碱性(pH≈8)，其水解酶在碱性条件下活性最高。","a":"错","e":"溶酶体内部呈酸性(pH≈5)，由H+泵维持，酸性水解酶在此条件下活性最高。","kp":"ch03_s2_5"},{"id":"ch03_judge_10","modI":2,"q":"溶酶体酶的分选信号是6-磷酸甘露糖(M6P)。","a":"对","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别并分选到溶酶体。","kp":"ch03_s2_11"}],"fill":[{"id":"ch03_fill_9","modI":2,"q":"高尔基体顺面网状结构(CGN)接收________合成的物质,反面膜囊(TGN)将物质分选运往________、质膜或胞外。","a":"内质网,溶酶体","kp":"ch03_s2_0"},{"id":"ch03_fill_10","modI":2,"q":"溶酶体含多种________水解酶(最适pH约为________),膜上的________维持其酸性环境。","a":"酸性,5,H+泵(质子泵)","kp":"ch03_s2_1"},{"id":"ch03_fill_11","modI":2,"q":"溶酶体的消化类型包括________(吞噬外源物质)和________(降解自身老化细胞器)。","a":"phagocytosis(吞噬),autophagy(自噬)","kp":"ch03_s2_4"}],"short":[{"id":"ch03_short_6","modI":2,"q":"简述高尔基体的结构和功能。","a":"高尔基体(Golgi complex)结构：\n由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性：\n①顺面网状结构(CGN)——接收内质网合成的新物质；\n②中间膜囊——加工修饰；\n③反面网状结构(TGN)——输出端，分选运往溶酶体、质膜或胞外。\n\n高尔基体功能：\n①蛋白质的糖基化——O-连接糖基化在此进行；N-连接糖基化在此完成加工；\n②糖胺聚糖/蛋白聚糖的合成；\n③蛋白质加工、修饰；\n④分类装载运输的分选站(枢纽作用)——通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖信号序列与受体的相互作用；\n⑤植物细胞高尔基体参与细胞壁合成。\n\n【意义】高尔基体是内膜系统的'分拣中心'。","kp":"ch03_s2_0"}],"calc":[{"id":"ch03_calc_3","modI":2,"q":"论述溶酶体的形成、功能及其与疾病的关系。","a":"溶酶体是细胞的消化系统,其酶经M6P途径分选形成,功能异常导致溶酶体贮积症","steps":"【形成(M6P途径)】\n①溶酶体酶在rER合成并进行N-连接糖基化；\n②在高尔基体CGN，由N-乙酰葡萄糖胺磷酸转移酶催化加上6-磷酸甘露糖(M6P)标志；\n③M6P受体识别并结合溶酶体酶；\n④包装入网格蛋白有被小泡→运往胞内体→溶酶体。\n(部分经M6P非依赖途径)\n\n【功能】\n①消化：'清道夫'，清除无用生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子；\n②吞噬(phagocytosis)：消化细菌等外源物质；\n③自噬(autophagy)：降解自身老化废弃的细胞器和蛋白；\n④参与蛋白质存量调节(除泛素途径外的另一途径)；\n⑤维持内部酸性环境(H+泵，pH≈5)。\n\n【疾病】\n溶酶体酶缺陷→底物不能被降解→溶酶体贮积症(如泰-萨克斯病、戈谢病、I细胞病等)，表现为神经退行、肝脾肿大等。","kp":"ch03_s2_2"}],"term":[{"id":"ch03_term_11","modI":2,"term":"高尔基体(Golgi Complex)","def":"①由扁平膜囊和囊泡组成的细胞器，具极性(cis/medial/trans)（定义）。②功能：蛋白质O-连接糖基化、N-连接糖基化加工；蛋白质分选装载运输的枢纽；糖胺聚糖合成（功能）。③CGN接收ER物质，TGN输出到溶酶体/质膜/胞外（极性）。","kps":"踩分点:①定义(1分)②功能(2分)③极性区室(1分)","kp":"ch03_s2_0"},{"id":"ch03_term_12","modI":2,"term":"溶酶体(Lysosome)","def":"①单层膜包围、含多种酸性水解酶的细胞器，是细胞的消化系统（定义）。②特点：内部酸性(pH≈5，H+泵维持)；膜高度糖基化保护；异质性（特点）。③功能：吞噬消化外源物质、自噬降解自身老化细胞器、参与蛋白存量调节（功能）。④酶经M6P途径分选（分选）。","kps":"踩分点:①定义(1分)②特点(1分)③功能(2分)④M6P(1分)","kp":"ch03_s2_1"},{"id":"ch03_term_13","modI":2,"term":"M6P分选途径","def":"①通过6-磷酸甘露糖(M6P)标志将溶酶体酶靶向到溶酶体的途径（定义）。②过程：溶酶体酶在rER合成/N-糖基化→高尔基体CGN由N-乙酰葡萄糖胺磷酸转移酶加上M6P→M6P受体识别→包装入运输小泡→溶酶体（过程）。③意义：保证溶酶体酶正确分选（意义）。","kps":"踩分点:①定义(1分)②过程(2分)③意义(1分)","kp":"ch03_s2_15"},{"id":"ch03_term_14","modI":2,"term":"细胞自噬(Autophagy)","def":"①细胞在自噬相关基因调控下，降解自身受损或需淘汰更新的物质(细胞器、大分子)并再利用的过程（定义）。②过程：形成自噬体→与溶酶体融合→降解（过程）。③意义：清除受损细胞器、维持稳态、应对饥饿（意义）。","kps":"踩分点:①定义(1分)②过程(1分)③意义(2分)","kp":"ch03_s2_10"}]}],"mcq":[{"id":"ch03_mcq_1","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内膜系统不包括下列哪个？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 线粒体"],"a":"D","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成(ER/高尔基/溶酶体/内体/液泡/分泌小泡)；线粒体虽具膜但不属内膜系统。","kp":"ch03_s0_2","oe":["内质网是内膜系统的核心成员，属于内膜系统。","高尔基体由单层膜构成且起源上与ER相关，属于内膜系统。","溶酶体由单层膜包被且起源于高尔基体，属于内膜系统。","线粒体虽具膜，但不属于内膜系统，故为答案。"]},{"id":"ch03_mcq_2","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"粗面内质网(rER)的主要功能是？","o":["A. 合成脂类","B. 合成分泌蛋白和膜蛋白(膜上有核糖体)","C. 解毒","D. 储钙"],"a":"B","e":"rER膜表面有大量核糖体，合成分泌性蛋白和多种膜蛋白；sER无核糖体，合成脂类、解毒、储钙。","kp":"ch03_s0_10","oe":["合成脂类主要是光面内质网的功能，不是rER。","rER膜上附有核糖体，合成分泌蛋白和膜蛋白。","解毒是sER的功能，不是rER的主要功能。","储钙是sER的功能，不属于rER。"]},{"id":"ch03_mcq_3","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"光面内质网(sER)的功能不包括？","o":["A. 解毒","B. 储钙","C. 合成膜脂","D. 合成分泌蛋白"],"a":"D","e":"sER功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。合成分泌蛋白是rER功能。","kp":"ch03_s0_9","oe":["解毒是sER的功能，如在肝细胞中。","储钙是sER的功能，ER是细胞内重要钙库。","合成膜脂(甘油磷脂、胆固醇)是sER的功能。","合成分泌蛋白是rER的功能，不属于sER，故为答案。"]},{"id":"ch03_mcq_4","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"易位子(translocon)位于？","o":["A. 高尔基体膜","B. 粗面内质网膜","C. 溶酶体膜","D. 线粒体外膜"],"a":"B","e":"易位子是rER膜上的蛋白复合体(核心为Sec61复合体)，中心有2nm孔道，新生肽链由此进入ER腔。","kp":"ch03_s0_19","oe":["易位子位于内质网膜，不在高尔基体膜上。","易位子位于粗面内质网膜，核心为Sec61复合体。","易位子不在溶酶体膜，溶酶体蛋白由运输小泡送入。","线粒体外膜蛋白靠TOM等复合体转运，不是易位子。"]},{"id":"ch03_mcq_5","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号识别颗粒(SRP)的组成是？","o":["A. 6种多肽+1个7S RNA","B. 仅蛋白质","C. 仅RNA","D. 糖蛋白"],"a":"A","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，既结合信号肽又结合核糖体大亚基，暂停翻译。","kp":"ch03_s0_32","oe":["SRP由6种多肽和1个7S RNA组成。","SRP含有RNA，并非仅由蛋白质组成。","SRP含有蛋白质，并非仅由RNA组成。","SRP是核糖核蛋白，不是糖蛋白。"]},{"id":"ch03_mcq_6","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号肽假说中,肽链转移进入ER腔的机制是？","o":["A. 翻译后转移","B. 边翻译边转移(共翻译转移)","C. 胞吞","D. 自由扩散"],"a":"B","e":"分泌蛋白在游离核糖体起始合成→信号肽被SRP识别→附着ER→共翻译转移入ER腔，信号肽被切除。","kp":"ch03_s0_35","oe":["分泌蛋白入ER是边翻译边转移，不是翻译后转移。","肽链进入ER腔为共翻译转移，即边翻译边转移。","胞吞是摄取外源物质的方式，与肽链入ER无关。","自由扩散是小分子运输方式，不适用于肽链入ER。"]},{"id":"ch03_mcq_7","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"可溶性蛋白进入ER腔的条件是？","o":["A. 只有N端信号序列,无停止转移序列","B. 含停止转移序列","C. 无信号序列","D. 含多个起始序列"],"a":"A","e":"只含N端信号序列(开始转移序列)、无停止序列→蛋白完全进入ER腔成可溶性蛋白；有停止序列则锚在膜上成跨膜蛋白。","kp":"ch03_s0_39","oe":["只有N端信号序列而无停止转移序列，蛋白完全进入ER腔。","含停止转移序列的蛋白会锚定在膜上，成为跨膜蛋白。","无信号序列的蛋白不能进入ER腔。","含多个起始序列的说法与可溶性蛋白入腔机理不符。"]},{"id":"ch03_mcq_8","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"N-连接糖基化与O-连接糖基化的区别,错误的是？","o":["A. N-连接起始于rER,O-连接在高尔基体","B. N-连接结合Asn,O-连接结合Ser/Thr","C. N-连接来自同一寡糖前体","D. O-连接起始于内质网"],"a":"D","e":"O-连接糖基化在高尔基体进行，单糖逐个加到Ser/Thr羟基上；N-连接起始于rER，结合Asn，来自同一寡糖前体。","kp":"ch03_s0_43","oe":["N-连接起始于rER，O-连接在高尔基体，该说法正确。","N-连接结合Asn，O-连接结合Ser/Thr，该说法正确。","N-连接糖链来自同一寡糖前体，该说法正确。","O-连接糖基化在高尔基体起始，而非起始于内质网，故错误。"]},{"id":"ch03_mcq_9","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"催化ER腔内二硫键形成的酶是？","o":["A. PDI","B. Bip","C. SRP","D. Hsp70"],"a":"A","e":"PDI(蛋白二硫键异构酶)是ER驻留蛋白，催化二硫键形成与重排。Bip是分子伴侣识别错误折叠蛋白。","kp":"ch03_s0_12","oe":["PDI是ER驻留蛋白，催化二硫键的形成与重排。","Bip是分子伴侣，识别错误折叠蛋白，不催化二硫键。","SRP负责识别信号肽并暂停翻译，不催化二硫键。","Hsp70是分子伴侣，无二硫键异构酶活性。"]},{"id":"ch03_mcq_10","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"Bip蛋白的功能是？","o":["A. 催化二硫键","B. 识别未正确折叠/未组装的蛋白,帮助折叠","C. 合成脂类","D. 切除信号肽"],"a":"B","e":"Bip(binding protein)是ER驻留分子伴侣，识别不正确折叠或未组装的蛋白，防止聚集并帮助折叠。","kp":"ch03_s0_18","oe":["催化二硫键形成的是PDI，不是Bip。","Bip是ER驻留分子伴侣，识别未正确折叠或未组装的蛋白并帮助折叠。","合成脂类由sER完成，不是Bip的功能。","切除信号肽由信号肽酶完成，不是Bip。"]},{"id":"ch03_mcq_11","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内质网驻留蛋白的驻留信号是？","o":["A. KDEL序列","B. M6P","C. NLS","D. NES"],"a":"A","e":"Bip、PDI等ER驻留蛋白含C端KDEL(内质网驻留信号)，被保留在ER中。M6P是溶酶体分选信号。","kp":"ch03_s0_9","oe":["ER驻留蛋白C端的KDEL序列是其内质网驻留信号。","M6P是溶酶体酶的分选信号，不是ER驻留信号。","NLS是核定位信号，引导蛋白进入细胞核。","NES是核输出信号，与ER驻留无关。"]},{"id":"ch03_mcq_12","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"2004年诺贝尔化学奖授予的发现是？","o":["A. 泛素介导的蛋白质降解","B. 水通道","C. RNAi","D. 端粒酶"],"a":"A","e":"2004年诺贝尔化学奖授予Ciechanover、Hershko、Rose，发现泛素介导的蛋白质降解。","kp":"ch03_s0_28","oe":["2004年诺贝尔化学奖表彰发现泛素介导的蛋白质降解。","水通道研究获2003年诺贝尔化学奖，年份不符。","RNAi研究获2006年诺贝尔生理学或医学奖，非化学奖。","端粒酶研究获2009年诺贝尔生理学或医学奖，非化学奖。"]},{"id":"ch03_mcq_13","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素由多少个氨基酸组成？","o":["A. 76个","B. 100个","C. 50个","D. 200个"],"a":"A","e":"泛素由76个氨基酸组成，8.5×10³小分子球蛋白，高度保守，普遍存在于真核细胞。","kp":"ch03_s1_17","oe":["泛素由76个氨基酸组成，是高度保守的小分子球蛋白。","泛素并非由100个氨基酸组成，数目不对。","泛素并非由50个氨基酸组成，数目不对。","泛素并非由200个氨基酸组成，数目不对。"]},{"id":"ch03_mcq_14","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素化需要哪三种酶？","o":["A. E1、E2、E3","B. 激酶、磷酸酶、连接酶","C. PDI、Bip、SRP","D. 蛋白酶、核酸酶、脂肪酶"],"a":"A","e":"泛素活化酶(E1)、泛素结合酶(E2)、泛素连接酶(E3)。多聚泛素链是降解信号。","kp":"ch03_s1_18","oe":["泛素化需泛素活化酶E1、泛素结合酶E2和泛素连接酶E3。","激酶、磷酸酶、连接酶不是泛素化的三种酶。","PDI、Bip、SRP与泛素化过程无关。","蛋白酶、核酸酶、脂肪酶是水解酶，不参与泛素化。"]},{"id":"ch03_mcq_15","mod":"模块二：蛋白质分选与降解","modI":1,"q":"26S蛋白酶体的结构是？","o":["A. 一个20S催化核心+两个19S调节帽","B. 仅20S","C. 仅19S","D. 单链蛋白"],"a":"A","e":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，由约50种亚基构成，降解泛素化蛋白。","kp":"ch03_s1_19","oe":["26S蛋白酶体由20S催化核心和两个19S调节帽组成。","26S蛋白酶体不只含20S，还含19S调节帽。","26S蛋白酶体并非仅由19S组成。","26S蛋白酶体是多亚基复合体，不是单链蛋白。"]},{"id":"ch03_mcq_16","mod":"模块二：蛋白质分选与降解","modI":1,"q":"高尔基体的极性区室中,接收内质网物质的是？","o":["A. 顺面(CGN)","B. 反面(TGN)","C. 中间膜囊","D. 溶酶体"],"a":"A","e":"顺面网状结构(CGN)接收内质网新物质；反面膜囊(TGN)是输出端，分选运往溶酶体/质膜/胞外。","kp":"ch03_s1_25","oe":["顺面网状结构(CGN)接收内质网运来的新物质。","反面(TGN)是输出端，分选运往溶酶体、质膜或胞外。","中间膜囊负责加工修饰，不接收ER来向物质。","溶酶体不是高尔基体的极性区室。"]},{"id":"ch03_mcq_17","mod":"模块二：蛋白质分选与降解","modI":1,"q":"O-连接糖基化发生在？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 细胞核"],"a":"B","e":"O-连接糖基化在高尔基体进行(单糖逐个加到Ser/Thr)；N-连接起始于ER、完成于高尔基体。","kp":"ch03_s1_2","oe":["内质网主要进行N-连接糖基化，不是O-连接。","O-连接糖基化在高尔基体进行，单糖加到Ser/Thr上。","溶酶体负责分解，不进行O-连接糖基化。","细胞核不是糖基化场所，糖基化在内质网和高尔基体。"]},{"id":"ch03_mcq_18","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体内部维持酸性环境(pH≈5)依靠？","o":["A. H+泵(质子泵)","B. Na+/K+泵","C. Ca2+泵","D. 水通道"],"a":"A","e":"溶酶体膜上的H+-pumps将H+泵入，维持内部pH≈5，使酸性水解酶活性最高。","kp":"ch03_s1_19","oe":["溶酶体膜上的H+泵将H+泵入，维持腔内pH约5。","Na+/K+泵维持细胞内外钠钾梯度，不使溶酶体酸化。","Ca2+泵与溶酶体酸性环境的维持无关。","水通道只转运水，不参与溶酶体酸化。"]},{"id":"ch03_mcq_19","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体酶的靶向分选信号是？","o":["A. 6-磷酸甘露糖(M6P)","B. KDEL","C. NLS","D. 信号肽"],"a":"A","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别分选到溶酶体。","kp":"ch03_s1_3","oe":["溶酶体酶的靶向分选信号是6-磷酸甘露糖(M6P)。","KDEL是ER驻留信号，使蛋白滞留在内质网。","NLS是核定位信号，引导蛋白进入细胞核。","信号肽引导蛋白进入内质网，不是溶酶体靶向信号。"]},{"id":"ch03_mcq_20","mod":"模块二：蛋白质分选与降解","modI":1,"q":"细胞自噬(autophagy)是指？","o":["A. 吞噬外源细菌","B. 降解细胞自身老化废弃的细胞器和大分子","C. 分泌蛋白","D. 细胞分裂"],"a":"B","e":"自噬是细胞在自噬相关基因调控下，对自身受损或需淘汰更新的物质(线粒体、过氧化物酶体等)进行降解再利用。","kp":"ch03_s1_24","oe":["吞噬外源细菌是吞噬作用，不属于自噬。","自噬是降解细胞自身老化废弃的细胞器和大分子。","分泌蛋白属于分泌途径，与自噬不同。","细胞分裂属于增殖过程，与自噬的降解功能无关。"]},{"id":"ch03_mcq_21","mod":"模块二：蛋白质分选与降解","modI":1,"q":"N-连接糖基化连接的氨基酸残基是？","o":["A. 天冬酰胺(Asn)","B. 丝氨酸(Ser)","C. 苏氨酸(Thr)","D. 赖氨酸(Lys)"],"a":"A","e":"N-连接糖基化连接Asn(序列Asn-X-Ser/Thr)；O-连接连接Ser/Thr羟基。","kp":"ch03_s1_2","oe":["N-连接糖基化连接的氨基酸残基是天冬酰胺(Asn)。","丝氨酸是O-连接糖基化的连接位点。","苏氨酸也是O-连接糖基化的连接位点。","赖氨酸不参与N-连接糖基化，N-连接位点是天冬酰胺。"]},{"id":"ch03_mcq_22","mod":"模块二：蛋白质分选与降解","modI":1,"q":"膜脂(甘油磷脂和胆固醇)主要在何处合成？","o":["A. 光面内质网","B. 高尔基体","C. 线粒体","D. 细胞核"],"a":"A","e":"sER合成构成细胞所需的绝大多数膜脂(甘油磷脂和胆固醇)，再运往其他膜。","kp":"ch03_s1_28","oe":["光面内质网合成甘油磷脂和胆固醇等膜脂。","高尔基体主要加工分选，不主要负责合成膜脂。","线粒体主要供能，膜脂合成主要在内质网。","细胞核不合成膜脂，膜脂合成主要在内质网。"]},{"id":"ch03_mcq_23","mod":"模块二：蛋白质分选与降解","modI":1,"q":"微粒体(microsome)是？","o":["A. 完整线粒体","B. 破碎内质网自我融合形成的囊泡","C. 溶酶体","D. 高尔基体"],"a":"B","e":"微粒体是体外实验中细胞匀浆和差速离心得到的、由分离的内质网自我融合形成的球形囊泡，是研究ER的模型。","kp":"ch03_s1_20","oe":["微粒体是由内质网形成的囊泡，不是完整线粒体。","微粒体是破碎内质网自我融合形成的囊泡。","微粒体来源于内质网，不是溶酶体。","微粒体来源于破碎的内质网，不是高尔基体。"]},{"id":"ch03_mcq_24","mod":"模块二：蛋白质分选与降解","modI":1,"q":"sER的储钙功能依靠？","o":["A. Ca2+-ATPase将钙泵入ER","B. 钙通道外流","C. Na+/K+泵","D. 质子泵"],"a":"A","e":"ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER储存，使ER腔钙浓度高达3mM，参与信号传递。","kp":"ch03_s1_21","oe":["ER膜上的Ca2+-ATPase将钙泵入ER储存。","钙通道外流会释放钙，与储钙作用相反。","Na+/K+泵与ER的储钙功能无关。","质子泵维持溶酶体酸性，不负责ER储钙。"]},{"id":"ch03_mcq_25","mod":"模块二：蛋白质分选与降解","modI":1,"q":"ER质量监控的意义是？","o":["A. 所有蛋白都能离开ER","B. 只有正确折叠和装配的蛋白才能离开ER","C. 错误折叠蛋白直接分泌","D. 阻止所有蛋白合成"],"a":"B","e":"ER质量监控：只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被逆向转运至胞质经泛素-蛋白酶体降解(ERAD)。","kp":"ch03_s1_14","oe":["并非所有蛋白都能离开ER，只有正确折叠装配者可以。","ER质量监控确保只有正确折叠和装配的蛋白才能离开ER。","错误折叠蛋白被滞留降解，不会直接分泌。","质量监控是筛选而非阻止所有蛋白质的合成。"]}],"judge":[{"id":"ch03_judge_1","modI":0,"q":"内膜系统包括内质网、高尔基体、溶酶体，但不包括线粒体和叶绿体。","a":"对","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成；线粒体、叶绿体不属内膜系统。","kp":"ch03_s0_2"},{"id":"ch03_judge_2","modI":0,"q":"粗面内质网表面附着大量核糖体，主要合成分泌蛋白和膜蛋白。","a":"对","e":"rER膜上有核糖体与易位子，合成分泌蛋白和膜蛋白；sER无核糖体。","kp":"ch03_s0_9"},{"id":"ch03_judge_3","modI":0,"q":"光面内质网的功能包括解毒、储钙和合成膜脂。","a":"对","e":"sER三大功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。","kp":"ch03_s0_13"},{"id":"ch03_judge_4","modI":0,"q":"易位子(translocon)位于高尔基体膜上，介导蛋白质进入高尔基体腔。","a":"错","e":"易位子位于粗面内质网(rER)膜上，核心为Sec61复合体，介导新生肽链进入ER腔。","kp":"ch03_s0_19"},{"id":"ch03_judge_5","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个7S RNA组成。","a":"对","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，识别信号肽并使翻译暂停。","kp":"ch03_s1_13"},{"id":"ch03_judge_6","modI":1,"q":"N-连接糖基化起始于内质网，O-连接糖基化发生在高尔基体。","a":"对","e":"N-连接起始于rER、结合Asn；O-连接在高尔基体进行、结合Ser/Thr。","kp":"ch03_s1_27"},{"id":"ch03_judge_7","modI":1,"q":"泛素由76个氨基酸组成，泛素化需要E1、E2、E3三种酶。","a":"对","e":"泛素由76个氨基酸组成；E1活化酶、E2结合酶、E3连接酶共同完成泛素化。","kp":"ch03_s1_18"},{"id":"ch03_judge_8","modI":1,"q":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，降解泛素化蛋白。","a":"对","e":"26S蛋白酶体=20S催化核心+两个19S调节帽，识别多聚泛素链并降解蛋白。","kp":"ch03_s1_20"},{"id":"ch03_judge_9","modI":2,"q":"溶酶体内部呈碱性(pH≈8)，其水解酶在碱性条件下活性最高。","a":"错","e":"溶酶体内部呈酸性(pH≈5)，由H+泵维持，酸性水解酶在此条件下活性最高。","kp":"ch03_s2_5"},{"id":"ch03_judge_10","modI":2,"q":"溶酶体酶的分选信号是6-磷酸甘露糖(M6P)。","a":"对","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别并分选到溶酶体。","kp":"ch03_s2_11"}],"fill":[{"id":"ch03_fill_1","modI":0,"q":"内膜系统是在结构、功能乃至发生上相关的、由________膜围绕成的细胞器,包括内质网、________、溶酶体等。","a":"单层,高尔基体","kp":"ch03_s0_2"},{"id":"ch03_fill_2","modI":0,"q":"粗面内质网表面分布大量________,主要合成分泌蛋白；光面内质网的功能有解毒、储钙和________。","a":"核糖体,合成膜脂","kp":"ch03_s0_9"},{"id":"ch03_fill_3","modI":0,"q":"rER膜上的蛋白复合体________(核心为Sec61)中心有直径2nm孔道,使新生肽链进入ER腔。","a":"易位子(translocon)","kp":"ch03_s0_21"},{"id":"ch03_fill_4","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个________组成,识别新生肽的________并使翻译暂停。","a":"7S RNA,信号肽","kp":"ch03_s1_4"},{"id":"ch03_fill_5","modI":1,"q":"N-连接糖基化连接________残基,起始于________；O-连接糖基化连接________残基,发生在________。","a":"天冬酰胺(Asn),内质网,丝氨酸/苏氨酸(Ser/Thr),高尔基体","kp":"ch03_s1_2"},{"id":"ch03_fill_6","modI":1,"q":"ER驻留蛋白的驻留信号是________；溶酶体酶的分选信号是________。","a":"KDEL序列,6-磷酸甘露糖(M6P)","kp":"ch03_s1_13"},{"id":"ch03_fill_7","modI":1,"q":"泛素由________个氨基酸组成；泛素化需要________、________、________三种酶。","a":"76,E1(活化酶),E2(结合酶),E3(连接酶)","kp":"ch03_s1_18"},{"id":"ch03_fill_8","modI":1,"q":"26S蛋白酶体由20S________和两个19S________组成,降解泛素化的蛋白质。","a":"催化核心,调节帽","kp":"ch03_s1_19"},{"id":"ch03_fill_9","modI":2,"q":"高尔基体顺面网状结构(CGN)接收________合成的物质,反面膜囊(TGN)将物质分选运往________、质膜或胞外。","a":"内质网,溶酶体","kp":"ch03_s2_0"},{"id":"ch03_fill_10","modI":2,"q":"溶酶体含多种________水解酶(最适pH约为________),膜上的________维持其酸性环境。","a":"酸性,5,H+泵(质子泵)","kp":"ch03_s2_1"},{"id":"ch03_fill_11","modI":2,"q":"溶酶体的消化类型包括________(吞噬外源物质)和________(降解自身老化细胞器)。","a":"phagocytosis(吞噬),autophagy(自噬)","kp":"ch03_s2_4"},{"id":"ch03_fill_12","modI":0,"q":"内质网驻留蛋白Bip和PDI属于________,其中PDI催化________的形成。","a":"分子伴侣(ER驻留蛋白),二硫键","kp":"ch03_s0_40"}],"short":[{"id":"ch03_short_1","modI":1,"q":"简述信号肽假说及分泌蛋白共翻译转移的过程。","a":"信号肽假说(1975年提出)：\n\n【过程】\n①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽(signal peptide)伸出；\n②信号识别颗粒(SRP，6种多肽+7S RNA)识别并结合信号肽及核糖体大亚基→翻译暂停；\n③SRP-核糖体复合物结合内质网膜上的SRP受体(停泊蛋白DP)；\n④核糖体附着到rER膜上，SRP释放，翻译恢复；\n⑤肽链边延伸边穿过易位子(translocon，核心Sec61)进入ER腔；\n⑥信号肽被信号肽酶切除，蛋白在ER腔折叠、修饰。\n\n【证据】1972年Milstein发现细胞内的免疫球蛋白N端比分泌到胞外的多一截(信号肽)。\n\n【意义】解释了分泌蛋白、膜蛋白如何定向进入ER。","kp":"ch03_s1_13"},{"id":"ch03_short_2","modI":0,"q":"简述内质网的功能。","a":"内质网分粗面内质网(rER)和光面内质网(sER)：\n\n【rER功能】\n①蛋白质合成——膜上有易位子，新生肽链共翻译转移入ER腔；\n②蛋白质的N-连接糖基化修饰；\n③新生多肽的折叠与装配(二硫键形成，PDI催化)；\n④蛋白质质量监控(只有正确折叠的蛋白才能离开ER)；\n⑤错误折叠蛋白经ERAD途径降解。\n\n【sER功能】\n①解毒(肝细胞，细胞色素P450)；\n②储钙(Ca库，Ca2+-ATPase泵入Ca2+，参与信号传递)；\n③合成膜脂(甘油磷脂和胆固醇)。\n\n【其他】\nER是内膜系统的重要组分，膜脂在ER合成后运往其他膜；ER驻留蛋白含KDEL信号。","kp":"ch03_s0_11"},{"id":"ch03_short_3","modI":1,"q":"简述蛋白质糖基化的类型、部位和生物学功能。","a":"蛋白质糖基化类型：\n\n【N-连接糖基化】\n• 合成部位：起始于粗面内质网；\n• 结合残基：天冬酰胺(Asn)，序列Asn-X-Ser/Thr；\n• 方式：来自同一个寡糖前体(连在磷酸多萜醇上)整体转移。\n\n【O-连接糖基化】\n• 合成部位：高尔基体；\n• 结合残基：丝氨酸/苏氨酸(Ser/Thr)羟基；\n• 方式：一个个单糖加上去。\n\n【生物学功能】\n①促进蛋白质折叠(如抗体IgG、质膜糖蛋白血凝素)；\n②影响蛋白稳定性、半衰期和运输；\n③参与细胞识别与免疫(如血型抗原)；\n④溶酶体酶的M6P分选信号；\n⑤负责糖链合成加工的酶均为管家基因编码。","kp":"ch03_s1_3"},{"id":"ch03_short_4","modI":1,"q":"简述泛素-蛋白酶体系统降解蛋白质的机制。","a":"泛素-蛋白酶体系统(2004年诺贝尔化学奖)：\n\n【泛素】\n由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞。\n\n【泛素化过程】\n①E1(泛素活化酶)消耗ATP激活泛素；\n②E2(泛素结合酶)接受活化泛素；\n③E3(泛素连接酶)识别靶蛋白并将泛素转移至靶蛋白的赖氨酸残基；\n④多轮循环形成多聚泛素链(降解信号)。\n\n【蛋白酶体降解】\n26S蛋白酶体=20S催化核心+两个19S调节帽，由约50种亚基组成。\n①19S帽识别多聚泛素链；\n②去折叠、去泛素化；\n③20S核心催化降解为短肽；\n④泛素可回收再利用。\n\n【意义】\n调控细胞周期、凋亡、信号转导等；错误折叠蛋白(ERAD)也经此降解。","kp":"ch03_s1_20"},{"id":"ch03_short_5","modI":1,"q":"比较N-连接和O-连接糖基化。","a":"N-连接 vs O-连接糖基化：\n\n| 特征 | N-连接 | O-连接 |\n|---|---|---|\n| 合成部位 | 起始于粗面内质网(完成于高尔基体) | 高尔基体 |\n| 合成方式 | 来自同一个寡糖前体整体转移 | 一个个单糖加上去 |\n| 结合残基 | 天冬酰胺Asn(Asn-X-Ser/Thr) | 丝氨酸/苏氨酸Ser/Thr羟基 |\n| 前体 | 磷酸多萜醇(dolichol)连接的寡糖 | 单糖核苷酸 |\n\n【共同点】\n①都属于蛋白质翻译后修饰；\n②都由糖基转移酶催化；\n③糖链都位于细胞外侧/ER腔侧。\n\n【生物学功能】\n促进折叠、影响稳定性与半衰期、参与细胞识别与免疫、M6P分选信号等。","kp":"ch03_s1_2"},{"id":"ch03_short_6","modI":2,"q":"简述高尔基体的结构和功能。","a":"高尔基体(Golgi complex)结构：\n由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性：\n①顺面网状结构(CGN)——接收内质网合成的新物质；\n②中间膜囊——加工修饰；\n③反面网状结构(TGN)——输出端，分选运往溶酶体、质膜或胞外。\n\n高尔基体功能：\n①蛋白质的糖基化——O-连接糖基化在此进行；N-连接糖基化在此完成加工；\n②糖胺聚糖/蛋白聚糖的合成；\n③蛋白质加工、修饰；\n④分类装载运输的分选站(枢纽作用)——通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖信号序列与受体的相互作用；\n⑤植物细胞高尔基体参与细胞壁合成。\n\n【意义】高尔基体是内膜系统的'分拣中心'。","kp":"ch03_s2_0"}],"calc":[{"id":"ch03_calc_1","modI":0,"q":"论述内膜系统的组成、膜泡运输途径及其生物学意义。","a":"内膜系统是真核细胞分室化的结构基础,膜泡运输实现区室间物质交流","steps":"【组成】\n由单层膜围绕、结构功能发生上相关的细胞器：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)。\n\n【膜泡运输途径】\n①分泌途径(向外)：ER→高尔基体(CGN→中间→TGN)→分泌小泡→质膜/胞外或溶酶体；\n②胞吞途径(向内)：质膜→早期胞内体→晚期胞内体→溶酶体；\n③回收途径：逃逸蛋白经COPI小泡返回ER。\n\n【意义】\n①实现细胞分室化，各细胞器功能专一、效率高；\n②完成蛋白质的合成、加工、分选和运输(分泌蛋白、膜蛋白、溶酶体酶)；\n③实现物质的摄取(胞吞)与降解(溶酶体)；\n④维持细胞器膜的特性和动态平衡；\n⑤是真核细胞比原核细胞复杂高效的根本原因。","kp":"ch03_s0_0"},{"id":"ch03_calc_2","modI":0,"q":"论述内质网的蛋白质质量监控体系及其意义。","a":"ER质量监控确保只有正确折叠的蛋白才能离开ER,错误蛋白被降解","steps":"【监控体系组成】\n①分子伴侣：Bip(识别错误折叠/未组装蛋白)、Hsp70家族；\n②折叠酶：PDI(催化二硫键形成与重排)；\n③糖基化系统：N-连接糖基化参与折叠监控；\n④ER驻留信号KDEL使Bip/PDI留在ER。\n\n【监控机制】\n①新生肽链进入ER腔→分子伴侣帮助折叠；\n②正确折叠和装配的蛋白→允许离开ER运往高尔基体；\n③错误折叠蛋白→被Bip滞留→反复尝试折叠；\n④长期不能正确折叠→逆向转运至胞质(ERAD)→泛素化→26S蛋白酶体降解。\n\n【意义】\n①保证分泌蛋白和膜蛋白的质量；\n②防止错误折叠蛋白聚集造成细胞损伤；\n③与多种疾病相关(如囊性纤维化CFTR突变、α1-抗胰蛋白酶缺乏症等折叠病)；\n④维持细胞稳态。","kp":"ch03_s0_18"},{"id":"ch03_calc_3","modI":2,"q":"论述溶酶体的形成、功能及其与疾病的关系。","a":"溶酶体是细胞的消化系统,其酶经M6P途径分选形成,功能异常导致溶酶体贮积症","steps":"【形成(M6P途径)】\n①溶酶体酶在rER合成并进行N-连接糖基化；\n②在高尔基体CGN，由N-乙酰葡萄糖胺磷酸转移酶催化加上6-磷酸甘露糖(M6P)标志；\n③M6P受体识别并结合溶酶体酶；\n④包装入网格蛋白有被小泡→运往胞内体→溶酶体。\n(部分经M6P非依赖途径)\n\n【功能】\n①消化：'清道夫'，清除无用生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子；\n②吞噬(phagocytosis)：消化细菌等外源物质；\n③自噬(autophagy)：降解自身老化废弃的细胞器和蛋白；\n④参与蛋白质存量调节(除泛素途径外的另一途径)；\n⑤维持内部酸性环境(H+泵，pH≈5)。\n\n【疾病】\n溶酶体酶缺陷→底物不能被降解→溶酶体贮积症(如泰-萨克斯病、戈谢病、I细胞病等)，表现为神经退行、肝脾肿大等。","kp":"ch03_s2_2"}],"term":[{"id":"ch03_term_1","modI":0,"term":"内膜系统(Endomembrane System)","def":"①在结构、功能乃至发生上相关的、由单层膜围绕成的细胞器或细胞结构（定义）。②组成：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)（组成）。③特点：膜相互流动、可相互转化（特点）。④意义：是真核细胞分室化的基础（意义）。","kps":"踩分点:①定义(1分)②组成(2分)③意义(1分)","kp":"ch03_s0_2"},{"id":"ch03_term_2","modI":0,"term":"粗面内质网(rER)","def":"①膜表面分布大量核糖体的内质网，多呈扁囊状（定义）。②功能：合成分泌性蛋白和膜蛋白；蛋白质N-连接糖基化；新生肽折叠与装配；蛋白质质量监控（功能）。③膜上有易位子(translocon)介导肽链进入ER腔（结构）。","kps":"踩分点:①定义(1分)②功能(2分)③易位子(1分)","kp":"ch03_s0_10"},{"id":"ch03_term_3","modI":0,"term":"光面内质网(sER)","def":"①表面无核糖体的内质网（定义）。②功能：解毒(肝细胞细胞色素P450)；储钙(Ca库，Ca2+-ATPase泵入，参与信号传递)；合成膜脂(甘油磷脂和胆固醇)（功能）。","kps":"踩分点:①定义(1分)②三大功能(3分)","kp":"ch03_s0_9"},{"id":"ch03_term_4","modI":0,"term":"易位子(Translocon)","def":"①rER膜上的蛋白复合体，中心有直径2nm的孔道（定义）。②核心为Sec61复合体(Sec61α/β/γ)，高度保守（结构）。③功能：介导新生肽链进入ER腔（功能）。","kps":"踩分点:①定义(1分)②Sec61(1分)③功能(1分)","kp":"ch03_s0_19"},{"id":"ch03_term_5","modI":1,"term":"信号肽(Signal Peptide)","def":"①位于分泌蛋白N端、引导蛋白进入ER的短肽序列（定义）。②特点：通常位于N端，完成使命后被信号肽酶切除（特点）。③机制：被SRP识别→核糖体停泊到ER膜→共翻译转移（机制）。④证据：1972年Milstein发现细胞内免疫球蛋白N端比胞外多一截（证据）。","kps":"踩分点:①定义(1分)②特点(1分)③机制(1分)④证据(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_6","modI":1,"term":"信号识别颗粒(SRP)","def":"①由6种多肽和1个300核苷酸(7S)RNA组成的核糖核蛋白复合物（定义）。②功能：既结合新生肽信号序列，又结合核糖体大亚基，使翻译暂停（功能）。③作用：将核糖体引导到ER膜的SRP受体(停泊蛋白DP)上（作用）。","kps":"踩分点:①组成(1分)②功能(2分)③与SRP受体(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_7","modI":0,"term":"分子伴侣(Molecular Chaperone)","def":"①能识别并结合正在合成或部分折叠的多肽、帮助其折叠装配的蛋白（定义）。②特点：不构成最终产物的一部分；高度保守(如Hsp70)（特点）。③举例：Bip、Hsp70、伴侣蛋白GroEL/GroES（举例）。④意义：帮助蛋白正确折叠、防止聚集（意义）。","kps":"踩分点:①定义(1分)②特点(1分)③举例(1分)④意义(1分)","kp":"ch03_s0_4"},{"id":"ch03_term_8","modI":0,"term":"Bip蛋白","def":"①内质网驻留的分子伴侣(binding protein)（定义）。②功能：识别不正确折叠或未组装的蛋白，防止聚集，帮助折叠（功能）。③含KDEL内质网驻留信号，被保留在ER中（特点）。","kps":"踩分点:①定义(1分)②功能(2分)③KDEL(1分)","kp":"ch03_s0_0"},{"id":"ch03_term_9","modI":1,"term":"泛素(Ubiquitin)","def":"①由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞（定义）。②功能：作为蛋白质降解的标签，共价结合到靶蛋白赖氨酸残基上（功能）。③泛素化需E1/E2/E3三种酶，多聚泛素链是降解信号（机制）。④发现获2004年诺贝尔化学奖（意义）。","kps":"踩分点:①定义(1分)②功能(1分)③三种酶(1分)④诺贝尔奖(1分)","kp":"ch03_s1_17"},{"id":"ch03_term_10","modI":1,"term":"蛋白酶体(Proteasome)","def":"①细胞内降解蛋白质的大分子复合体，由约50种亚基组成（定义）。②结构：26S蛋白酶体=20S催化核心+两个19S调节帽（结构）。③功能：识别多聚泛素链，将泛素化蛋白降解为短肽（功能）。","kps":"踩分点:①定义(1分)②结构(2分)③功能(1分)","kp":"ch03_s1_20"},{"id":"ch03_term_11","modI":2,"term":"高尔基体(Golgi Complex)","def":"①由扁平膜囊和囊泡组成的细胞器，具极性(cis/medial/trans)（定义）。②功能：蛋白质O-连接糖基化、N-连接糖基化加工；蛋白质分选装载运输的枢纽；糖胺聚糖合成（功能）。③CGN接收ER物质，TGN输出到溶酶体/质膜/胞外（极性）。","kps":"踩分点:①定义(1分)②功能(2分)③极性区室(1分)","kp":"ch03_s2_0"},{"id":"ch03_term_12","modI":2,"term":"溶酶体(Lysosome)","def":"①单层膜包围、含多种酸性水解酶的细胞器，是细胞的消化系统（定义）。②特点：内部酸性(pH≈5，H+泵维持)；膜高度糖基化保护；异质性（特点）。③功能：吞噬消化外源物质、自噬降解自身老化细胞器、参与蛋白存量调节（功能）。④酶经M6P途径分选（分选）。","kps":"踩分点:①定义(1分)②特点(1分)③功能(2分)④M6P(1分)","kp":"ch03_s2_1"},{"id":"ch03_term_13","modI":2,"term":"M6P分选途径","def":"①通过6-磷酸甘露糖(M6P)标志将溶酶体酶靶向到溶酶体的途径（定义）。②过程：溶酶体酶在rER合成/N-糖基化→高尔基体CGN由N-乙酰葡萄糖胺磷酸转移酶加上M6P→M6P受体识别→包装入运输小泡→溶酶体（过程）。③意义：保证溶酶体酶正确分选（意义）。","kps":"踩分点:①定义(1分)②过程(2分)③意义(1分)","kp":"ch03_s2_15"},{"id":"ch03_term_14","modI":2,"term":"细胞自噬(Autophagy)","def":"①细胞在自噬相关基因调控下，降解自身受损或需淘汰更新的物质(细胞器、大分子)并再利用的过程（定义）。②过程：形成自噬体→与溶酶体融合→降解（过程）。③意义：清除受损细胞器、维持稳态、应对饥饿（意义）。","kps":"踩分点:①定义(1分)②过程(1分)③意义(2分)","kp":"ch03_s2_10"},{"id":"ch03_term_15","modI":0,"term":"分子伴侣介导的蛋白折叠","def":"①分子伴侣通过反复结合与释放，帮助新生多肽折叠的机制（定义）。②与伴侣蛋白(GroEL/GroES)的隔离腔室折叠方式不同（区别）。③最终三维构象仍由氨基酸序列决定（特点）。","kps":"踩分点:①定义(1分)②与伴侣蛋白区别(2分)③序列决定构象(1分)","kp":"ch03_s0_18"},{"id":"ch03_term_16","modI":1,"term":"ER驻留信号(KDEL)","def":"①内质网驻留蛋白C端的一段回收信号序列(KDEL)（定义）。②功能：使Bip、PDI等驻留蛋白被保留在ER中而不被分泌（功能）。③机制：逃逸到高尔基体的驻留蛋白经KDEL受体识别，由COPI小泡回收回ER（机制）。","kps":"踩分点:①定义(1分)②功能(1分)③回收机制(2分)","kp":"ch03_s1_13"}],"preview":{"main":"本章围绕真核细胞的内膜系统，讲解细胞如何通过分室化实现蛋白质的合成、加工、分选与运输。核心内容包括内质网和高尔基体的结构与功能、信号肽假说与共翻译转运、糖基化与分子伴侣、以及溶酶体和液泡的形成与分选机制，是理解细胞器间物质流与信息流的关键一章。","questions":["真核细胞为什么要进行分室化？内膜系统由哪些细胞器组成，它们之间如何相互联系？","分泌蛋白是如何被定向转运到内质网的？信号肽、SRP、SRP受体和易位子各自发挥什么作用？","可溶性蛋白、跨膜蛋白和多次跨膜蛋白在ER膜上的转运方式有何不同？起始转移序列和停止转移序列如何决定膜蛋白的拓扑结构？","内质网中的N-连接糖基化、二硫键形成和分子伴侣如何保证蛋白质正确折叠？错误折叠的蛋白最终如何被降解？","高尔基体在蛋白质加工和分选中扮演什么角色？M6P分选信号是如何把溶酶体酶准确送到溶酶体的？","溶酶体有哪些消化类型和功能？细胞自噬与溶酶体在蛋白质存量调节中有何意义？"]},"appcards":[{"front":"简述信号肽假说及分泌蛋白共翻译转移的过程。","back":"信号肽假说(1975年提出)：\n\n【过程】\n①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽(signal peptide)伸出；\n②信号识别颗粒(SRP，6种多肽+7S RNA)识别并结合信号肽及核糖体大亚基→翻译暂停；\n③SRP-核糖体复合物结合内质网膜上的SRP受体(停泊蛋白DP)；\n④核糖体附着到rER膜上，SRP释放，翻译恢复；\n⑤肽链边延伸边穿过易位子(translocon，核心Sec61)进入ER腔；\n⑥信号肽被信号肽酶切除，蛋白在ER腔折叠、修饰。\n\n【证据】1972年Milstein发现细胞内的免疫球蛋白N端比分泌到胞外的多一截(信号肽)。\n\n【意义】解释了分泌蛋白、膜蛋白如何定向进入ER。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"简述内质网的功能。","back":"内质网分粗面内质网(rER)和光面内质网(sER)：\n\n【rER功能】\n①蛋白质合成——膜上有易位子，新生肽链共翻译转移入ER腔；\n②蛋白质的N-连接糖基化修饰；\n③新生多肽的折叠与装配(二硫键形成，PDI催化)；\n④蛋白质质量监控(只有正确折叠的蛋白才能离开ER)；\n⑤错误折叠蛋白经ERAD途径降解。\n\n【sER功能】\n①解毒(肝细胞，细胞色素P450)；\n②储钙(Ca库，Ca2+-ATPase泵入Ca2+，参与信号传递)；\n③合成膜脂(甘油磷脂和胆固醇)。\n\n【其他】\nER是内膜系统的重要组分，膜脂在ER合成后运往其他膜；ER驻留蛋白含KDEL信号。","points":"","mod":0,"modName":"模块一：真核细胞分室化与内质网","level":"掌握","src":"题库"},{"front":"简述蛋白质糖基化的类型、部位和生物学功能。","back":"蛋白质糖基化类型：\n\n【N-连接糖基化】\n• 合成部位：起始于粗面内质网；\n• 结合残基：天冬酰胺(Asn)，序列Asn-X-Ser/Thr；\n• 方式：来自同一个寡糖前体(连在磷酸多萜醇上)整体转移。\n\n【O-连接糖基化】\n• 合成部位：高尔基体；\n• 结合残基：丝氨酸/苏氨酸(Ser/Thr)羟基；\n• 方式：一个个单糖加上去。\n\n【生物学功能】\n①促进蛋白质折叠(如抗体IgG、质膜糖蛋白血凝素)；\n②影响蛋白稳定性、半衰期和运输；\n③参与细胞识别与免疫(如血型抗原)；\n④溶酶体酶的M6P分选信号；\n⑤负责糖链合成加工的酶均为管家基因编码。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"简述泛素-蛋白酶体系统降解蛋白质的机制。","back":"泛素-蛋白酶体系统(2004年诺贝尔化学奖)：\n\n【泛素】\n由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞。\n\n【泛素化过程】\n①E1(泛素活化酶)消耗ATP激活泛素；\n②E2(泛素结合酶)接受活化泛素；\n③E3(泛素连接酶)识别靶蛋白并将泛素转移至靶蛋白的赖氨酸残基；\n④多轮循环形成多聚泛素链(降解信号)。\n\n【蛋白酶体降解】\n26S蛋白酶体=20S催化核心+两个19S调节帽，由约50种亚基组成。\n①19S帽识别多聚泛素链；\n②去折叠、去泛素化；\n③20S核心催化降解为短肽；\n④泛素可回收再利用。\n\n【意义】\n调控细胞周期、凋亡、信号转导等；错误折叠蛋白(ERAD)也经此降解。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"比较N-连接和O-连接糖基化。","back":"N-连接 vs O-连接糖基化：\n\n| 特征 | N-连接 | O-连接 |\n|---|---|---|\n| 合成部位 | 起始于粗面内质网(完成于高尔基体) | 高尔基体 |\n| 合成方式 | 来自同一个寡糖前体整体转移 | 一个个单糖加上去 |\n| 结合残基 | 天冬酰胺Asn(Asn-X-Ser/Thr) | 丝氨酸/苏氨酸Ser/Thr羟基 |\n| 前体 | 磷酸多萜醇(dolichol)连接的寡糖 | 单糖核苷酸 |\n\n【共同点】\n①都属于蛋白质翻译后修饰；\n②都由糖基转移酶催化；\n③糖链都位于细胞外侧/ER腔侧。\n\n【生物学功能】\n促进折叠、影响稳定性与半衰期、参与细胞识别与免疫、M6P分选信号等。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"简述高尔基体的结构和功能。","back":"高尔基体(Golgi complex)结构：\n由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性：\n①顺面网状结构(CGN)——接收内质网合成的新物质；\n②中间膜囊——加工修饰；\n③反面网状结构(TGN)——输出端，分选运往溶酶体、质膜或胞外。\n\n高尔基体功能：\n①蛋白质的糖基化——O-连接糖基化在此进行；N-连接糖基化在此完成加工；\n②糖胺聚糖/蛋白聚糖的合成；\n③蛋白质加工、修饰；\n④分类装载运输的分选站(枢纽作用)——通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖信号序列与受体的相互作用；\n⑤植物细胞高尔基体参与细胞壁合成。\n\n【意义】高尔基体是内膜系统的'分拣中心'。","points":"","mod":2,"modName":"模块三：高尔基体与溶酶体","level":"掌握","src":"题库"},{"front":"论述内膜系统的组成、膜泡运输途径及其生物学意义。","back":"【组成】\n由单层膜围绕、结构功能发生上相关的细胞器：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)。\n\n【膜泡运输途径】\n①分泌途径(向外)：ER→高尔基体(CGN→中间→TGN)→分泌小泡→质膜/胞外或溶酶体；\n②胞吞途径(向内)：质膜→早期胞内体→晚期胞内体→溶酶体；\n③回收途径：逃逸蛋白经COPI小泡返回ER。\n\n【意义】\n①实现细胞分室化，各细胞器功能专一、效率高；\n②完成蛋白质的合成、加工、分选和运输(分泌蛋白、膜蛋白、溶酶体酶)；\n③实现物质的摄取(胞吞)与降解(溶酶体)；\n④维持细胞器膜的特性和动态平衡；\n⑤是真核细胞比原核细胞复杂高效的根本原因。","points":"","mod":0,"modName":"模块一：真核细胞分室化与内质网","level":"掌握","src":"题库"},{"front":"论述内质网的蛋白质质量监控体系及其意义。","back":"【监控体系组成】\n①分子伴侣：Bip(识别错误折叠/未组装蛋白)、Hsp70家族；\n②折叠酶：PDI(催化二硫键形成与重排)；\n③糖基化系统：N-连接糖基化参与折叠监控；\n④ER驻留信号KDEL使Bip/PDI留在ER。\n\n【监控机制】\n①新生肽链进入ER腔→分子伴侣帮助折叠；\n②正确折叠和装配的蛋白→允许离开ER运往高尔基体；\n③错误折叠蛋白→被Bip滞留→反复尝试折叠；\n④长期不能正确折叠→逆向转运至胞质(ERAD)→泛素化→26S蛋白酶体降解。\n\n【意义】\n①保证分泌蛋白和膜蛋白的质量；\n②防止错误折叠蛋白聚集造成细胞损伤；\n③与多种疾病相关(如囊性纤维化CFTR突变、α1-抗胰蛋白酶缺乏症等折叠病)；\n④维持细胞稳态。","points":"","mod":0,"modName":"模块一：真核细胞分室化与内质网","level":"掌握","src":"题库"},{"front":"论述溶酶体的形成、功能及其与疾病的关系。","back":"【形成(M6P途径)】\n①溶酶体酶在rER合成并进行N-连接糖基化；\n②在高尔基体CGN，由N-乙酰葡萄糖胺磷酸转移酶催化加上6-磷酸甘露糖(M6P)标志；\n③M6P受体识别并结合溶酶体酶；\n④包装入网格蛋白有被小泡→运往胞内体→溶酶体。\n(部分经M6P非依赖途径)\n\n【功能】\n①消化：'清道夫'，清除无用生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子；\n②吞噬(phagocytosis)：消化细菌等外源物质；\n③自噬(autophagy)：降解自身老化废弃的细胞器和蛋白；\n④参与蛋白质存量调节(除泛素途径外的另一途径)；\n⑤维持内部酸性环境(H+泵，pH≈5)。\n\n【疾病】\n溶酶体酶缺陷→底物不能被降解→溶酶体贮积症(如泰-萨克斯病、戈谢病、I细胞病等)，表现为神经退行、肝脾肿大等。","points":"","mod":2,"modName":"模块三：高尔基体与溶酶体","level":"掌握","src":"题库"},{"front":"比较粗面内质网(rER)与光面内质网(sER)在形态和功能上的主要差异。","back":"形态：rER膜表面有核糖体，多呈扁囊状；sER无核糖体，多呈管状。功能：rER合成分泌蛋白和膜蛋白，进行N-糖基化；sER合成脂类、解毒、储钙。两者膜连续。","points":"核糖体有无；形态差异；rER合成蛋白；sER脂类/解毒/储钙","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说内质网是蛋白质分选的起点？请从共翻译转移的角度说明。","back":"分泌蛋白在游离核糖体起始合成；N端信号肽被SRP识别，翻译暂停；SRP-核糖体复合物结合ER膜SRP受体；翻译恢复，肽链边合成边进入ER腔，完成共翻译转移。","points":"游离核糖体起始；信号肽-SRP；SRP受体停泊；共翻译入ER腔","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较N-连接糖基化与O-连接糖基化在合成部位、方式和结合氨基酸上的异同。","back":"部位：N-连接起始于rER，O-连接在高尔基体；方式：N-连接来自同一寡糖前体，O-连接逐个加单糖；氨基酸：N-连接为Asn，O-连接为Ser/Thr。","points":"N在rER起始；O在高尔基；N用寡糖前体；O逐个加；Asn vs Ser/Thr","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么真核细胞中二硫键只在ER腔内形成？其意义是什么？","back":"ER腔为氧化环境，且含二硫键异构酶(PDI)催化；胞质为还原环境，不利于二硫键稳定。意义：保证分泌蛋白和膜蛋白正确折叠与稳定。","points":"ER腔氧化环境；PDI催化；胞质还原；正确折叠","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明分子伴侣在ER中的作用。","back":"Bip是ER驻留分子伴侣，识别错误折叠或未组装蛋白，防止其聚集，帮助正确折叠；Hsp70家族协助新生肽折叠。它们不构成最终产物。","points":"Bip识别错误折叠；防止聚集；帮助折叠；不构成产物","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞中SRP受体(停泊蛋白)功能缺失，分泌蛋白的合成与运输会怎样？","back":"SRP-核糖体复合物无法停泊到ER膜；翻译不能恢复或肽链不能进入ER腔；分泌蛋白无法共翻译转移入ER，后续分泌途径受阻。","points":"不能停泊ER膜；翻译暂停不能恢复；不能入ER腔；分泌受阻","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较游离核糖体与膜结合核糖体在结构和功能上的异同。","back":"结构相同，均为核糖体；区别在于是否附着ER膜。游离核糖体合成胞质蛋白、核编码线粒体蛋白等；膜结合核糖体合成分泌蛋白、膜蛋白和溶酶体酶。","points":"结构相同；附着与否；游离合成胞质/线粒体蛋白；膜结合合成分泌/膜蛋白","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说高尔基体是蛋白质分选和运输的枢纽？","back":"高尔基体由顺面、中间、反面膜囊组成，具极性；接收ER新合成物质，进行加工修饰；通过信号序列与受体相互作用，将蛋白分选运往溶酶体、质膜或胞外。","points":"极性区室；接收ER物质；加工修饰；分选运往溶酶体/质膜/胞外","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明溶酶体异质性的表现。","back":"不同来源、不同发育阶段的溶酶体形态大小和所含水解酶不同；分为初级溶酶体(刚形成)、次级溶酶体(正在消化)、残余小体。","points":"来源/阶段不同；形态大小不同；酶类不同；初级/次级/残余小体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较吞噬作用与自噬作用在溶酶体消化中的异同。","back":"相同：最终均由溶酶体酸性水解酶降解。不同：吞噬作用摄取胞外物质如细菌、衰老红细胞；自噬作用降解细胞自身老化细胞器或生物大分子。","points":"均由溶酶体降解；吞噬摄胞外；自噬降解自身；举例","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么溶酶体膜不会被自身水解酶消化？","back":"溶酶体膜蛋白高度糖基化，保护膜不被水解酶消化；同时膜上有H+泵维持腔内酸性环境，水解酶在pH≈5时活性最高，在胞质中性pH下活性低。","points":"膜蛋白高度糖基化；H+泵维持酸性；酶最适pH≈5；胞质中性保护","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若溶酶体H+泵功能丧失，溶酶体的消化功能会受到什么影响？","back":"腔内pH升高，酸性水解酶活性降低或丧失；水解酶不能有效降解生物大分子；未降解物质在溶酶体内积累，影响细胞清除功能。","points":"pH升高；酶活性降低；降解受阻；物质积累","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"说明M6P分选信号在溶酶体酶定向运输中的作用。","back":"溶酶体酶在rER合成并N-糖基化；在高尔基体CGN，甘露糖残基被磷酸化形成M6P标志；M6P受体识别并分选，包装入运输小泡运往溶酶体。","points":"rER合成/N-糖基化；高尔基体磷酸化形成M6P；M6P受体识别；运往溶酶体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若M6P受体缺失，溶酶体酶的运输会发生什么变化？","back":"溶酶体酶不能被M6P受体识别和分选；酶可能被分泌到细胞外，而不是运往溶酶体；溶酶体缺乏水解酶，导致未降解物质积累。","points":"不能识别分选；酶分泌到胞外；溶酶体缺酶；物质积累","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较信号肽与信号斑在蛋白质分选中的异同。","back":"信号肽是线性氨基酸序列，通常位于N端，完成使命后被切除；信号斑由折叠后空间结构形成，可位于蛋白内部。两者均为分选信号。","points":"信号肽线性/N端/可切除；信号斑空间结构；均为分选信号","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说ER的质量监控系统对细胞具有重要意义？","back":"只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被滞留并逆向转运到胞质，经泛素-蛋白酶体系统降解；保证分泌蛋白和膜蛋白质量。","points":"正确折叠才能离开；错误折叠滞留；ERAD降解；保证蛋白质量","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明泛素-蛋白酶体系统降解错误折叠ER蛋白的过程。","back":"错误折叠ER蛋白被逆向转运到胞质；泛素分子共价结合到靶蛋白赖氨酸残基上；经E1、E2、E3催化形成多聚泛素链；26S蛋白酶体将其降解成短肽。","points":"逆向转运胞质；泛素化；E1/E2/E3；26S蛋白酶体降解","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若26S蛋白酶体功能被抑制，错误折叠蛋白的降解会怎样？","back":"泛素化的错误折叠蛋白不能被降解；在胞质中积累，可能形成聚集体；影响细胞正常功能，甚至导致细胞应激或死亡。","points":"不能降解；蛋白积累；形成聚集体；细胞功能受损","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"说明ER驻留信号KDEL的作用。","back":"Bip、PDI等ER驻留蛋白含KDEL序列；该信号使其被保留在ER中而不被分泌；保证ER内分子伴侣和折叠酶浓度充足。","points":"KDEL序列；保留在ER；不被分泌；保证伴侣/酶浓度","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较组成型分泌途径与调节型分泌途径的异同。","back":"相同：均经ER→高尔基体→分泌小泡运输。不同：组成型分泌持续进行，分泌小泡直接与质膜融合；调节型分泌小泡储存，需信号刺激才释放。","points":"均经ER/高尔基；组成型持续；调节型需信号；小泡储存","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说内质网是脂类合成的中心？","back":"sER合成构成细胞所需的绝大多数膜脂，包括甘油磷脂和胆固醇；磷脂酰胆碱在sER膜上经酶催化合成；膜脂在ER合成后运往其他膜。","points":"sER合成膜脂；甘油磷脂/胆固醇；磷脂酰胆碱合成；运往其他膜","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明sER的解毒功能。","back":"肝细胞sER很丰富，含细胞色素P450等酶；清除脂溶性药物和代谢产生的有害物质；多数解毒反应与氧化作用有关。","points":"肝细胞sER丰富；细胞色素P450；清除脂溶性药物；氧化反应","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"说明sER储钙功能与细胞信号传递的关系。","back":"ER膜上Ca2+-ATPase将胞质钙泵入ER腔，使腔内钙浓度高达3mM；sER通过释放/回收Ca2+调节细胞信号，如肌肉收缩。","points":"Ca2+-ATPase泵钙；腔内高钙；释放/回收Ca2+；肌肉收缩","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞中PDI功能缺失，分泌蛋白的折叠会受什么影响？","back":"二硫键不能正确形成或重排；分泌蛋白折叠异常；错误折叠蛋白被ER质量监控滞留并降解；分泌蛋白产量下降。","points":"二硫键形成异常；折叠异常；被滞留降解；分泌下降","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明放射自显影与电镜技术在研究膜泡运输中的应用。","back":"用放射性标记氨基酸脉冲标记胰腺腺泡细胞；追踪分泌蛋白在ER→Golgi→分泌小泡→细胞外的运输路径；证明膜泡运输的经典实验。","points":"放射性标记氨基酸；脉冲标记胰腺腺泡细胞；追踪ER→Golgi→小泡→胞外；经典实验","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}]};